INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C1','kor',3,2,'u3',2,'설명하는 글과 일의 차례 — 무엇을 만드는 방법·가는 길·놀이를 하는 차례처럼 일을 알려 주는 글이 설명하는 글이고, 읽는 사람이 그대로 따라 할 수 있게 일의 차례가 드러나야 함(글씨 크기·글 길이가 아님)',ARRAY['[4국02-05][4국03-02]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C2','kor',3,2,'u3',2,'설명할 내용을 알아볼 곳 — 아는 것만으로 모자라면 책·누리집·잘 아는 어른께 여쭈어 확인하고, 그럴듯하게 지어내거나 짐작해 쓰지 않음',ARRAY['[4국02-05]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C3','kor',3,2,'u3',2,'출처의 뜻 — 자료를 만든 곳이나 자료의 이름처럼 가져온 자료가 어디에서 왔는지 알려 주는 것(글을 쓴 사람·신문 이름·쓴 날짜·쪽수는 출처가 아님)',ARRAY['[4국02-05]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C4','kor',3,2,'u3',2,'출처가 나타나는 곳 — 글 속 문장 안(「…에 따르면」), 그림 자료 바로 아래(「■ 출처」), 영상 화면 아래 작은 글씨처럼 자료에 따라 여러 방법으로 밝힘',ARRAY['[4국02-05]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C5','kor',3,2,'u3',2,'출처를 밝히는 까닭 — 읽는 사람이 믿을 만한 자료인지 살펴볼 수 있고, 만든 사람의 것을 내 것처럼 쓰지 않았다는 뜻이 되어 다른 사람이 만든 것을 존중하는 일이 됨',ARRAY['[4국02-05]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C6','kor',3,2,'u3',3,'글쓴이의 의견과 자료·출처 정리 — 주장하는 글에서 글쓴이의 의견과 까닭을 찾고, 글에 쓰인 자료마다 출처를 짝지어 정리하며, 들은 이야기·아래에 아무 글 없는 그림처럼 출처가 없는 자료를 가려냄',ARRAY['[4국02-05][4국02-03]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C7','kor',3,2,'u3',3,'출처를 확인하며 읽으면 좋은 점 — 글에 쓰인 자료가 믿을 만한지 살펴볼 수 있고, 더 알고 싶을 때 어디에 가서 찾아볼지 알 수 있음; 출처가 없으면 찾아갈 곳을 알 수 없음',ARRAY['[4국02-05][4국02-03]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C8','kor',3,2,'u3',3,'출처가 있는 자료를 대하는 태도 — 출처가 붙어 있다고 다 맞는 것도, 다 거짓인 것도 아니므로 어떤 곳에서 가져왔는지 살펴보고 생각하며 읽음(출처는 「믿어라」는 표가 아니라 「살펴볼 수 있다」는 표)',ARRAY['[4국02-05][4국02-03]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C9','kor',3,2,'u3',5,'스스로 출처를 찾으며 글 내용 알기 — 밑줄 같은 표시가 없어도 「…에 따르면」·「■ 출처」처럼 가져온 곳을 밝힌 말을 찾아 자료와 출처를 정리하고, 글이 무엇을 설명하는지와 글에 쓰인 내용을 확인함',ARRAY['[4국02-05][4국02-04]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C10','kor',3,2,'u3',5,'글에 나온 낱말의 뜻 — 가꾸다(잘 자라도록 보살피다)·차례(순서에 따라 돌아오는 것)·마련하다(필요한 것을 준비해 갖추다)를 그 낱말이 든 문장에서 짐작하고 바꾸어 넣어 확인함',ARRAY['[4국02-05][4국02-04]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C11','kor',3,2,'u3',5,'출처가 알맞은지 확인하는 방법 — 적혀 있는 곳에 직접 가 보거나 그 누리집에 들어가 보고, 그곳이 어떤 곳인지 알아봄(이름이 길거나 글씨가 크다고 믿을 만한 것이 아님)',ARRAY['[4국02-05][4국02-04]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C12','kor',3,2,'u3',7,'이어 주는 말의 쓰임 — 그리고(앞과 비슷한 내용이 이어질 때)·그러나(앞과 반대되는 내용이 이어질 때)·그래서(앞이 뒤의 까닭이 될 때)처럼 앞뒤 문장의 관계에 따라 알맞은 말을 고름(때·곳을 나타내는 말은 이어 주는 말이 아님)',ARRAY['[4국04-03][4국03-02]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C13','kor',3,2,'u3',7,'이어 주는 말을 알맞게 쓰기 — 이어 주는 말은 많이 쓸수록 좋은 것이 아니라 앞뒤 뜻이 어떻게 이어지는지에 맞을 때 쓰며, 문장마다 빠짐없이 넣지도 하나도 쓰지 않지도 않음',ARRAY['[4국04-03][4국03-02]']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C14','kor',3,2,'u3',9,'쓰기 전에 생각할 것 — 이 글을 읽을 사람·쓰는 목적·꼭 들어가야 할 내용을 먼저 정하면 쓸 내용이 보이고, 글씨 색·글자 수 같은 꾸밈은 나중의 일임',ARRAY['[4국03-02]']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C15','kor',3,2,'u3',9,'알기 쉽게 고쳐 쓰기와 차례를 나타내는 말 — 어려운 낱말은 쉬운 말로 풀고, 먼저·다음으로·끝으로(처음에·그다음에·마지막으로, 첫째·둘째·셋째)를 일의 순서에 맞게 넣어 무엇을 먼저 할지 드러냄',ARRAY['[4국03-02]']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C16','kor',3,2,'u3',9,'쓸 때 출처 밝히기 — 책이나 안내판에서 알아낸 내용을 썼다면 가져온 곳을 글 끝에 밝히고(빼지도 내 것처럼 쓰지도 않음), 찾아본 곳이 기억나지 않으면 지어 적지 않고 다시 확인해 적거나 그 내용은 쓰지 않으며, 내가 이미 해 본 방법에는 출처가 없어도 됨',ARRAY['[4국03-02]']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C17','kor',3,2,'u3',10,'처음·가운데·끝으로 짜기 — 읽을 사람을 먼저 정한 뒤, 처음에는 무엇을 설명할 글인지 밝히고 가운데에는 일의 차례와 방법을 자세히, 끝에는 설명한 내용을 간추림',ARRAY['[4국03-02][4국03-05]']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C18','kor',3,2,'u3',10,'쓴 글 점검하기와 서로 다른 방법 — 차례와 방법이 드러났는지·읽는 사람이 궁금해할 내용을 넣었는지·이어 주는 말이 알맞은지·출처를 밝혔는지를 고치려고 살피며, 같은 일도 방법이 달라도 차례와 까닭이 드러나면 둘 다 알맞은 글임',ARRAY['[4국03-02][4국03-05]']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C19','kor',3,2,'u3',12,'함께 쓰는 곳의 이용 설명서 — 어떤 곳인지·이용하는 차례·지킬 것으로 문단을 나누어 맡고, 안내판·안내장·누리집 알림 글·사진처럼 자료의 종류가 달라도 가져온 곳을 똑같이 적으며, 하나로 모을 때 이어 주는 말로 잇고 빠진 차례를 살핌',ARRAY['[4국03-02][4국04-03]']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C20','kor',3,2,'u3',12,'‘-데’와 ‘-대’ — 내가 직접 겪어 안 것을 말할 때는 ‘-데’, 남의 말을 전할 때(…다고 해)는 ‘-대’를 씀; ‘보니’가 붙었는지가 아니라 내가 겪었는지 남에게 들었는지가 가름(기초 다지기)',ARRAY['[4국04-03](케이티처 l14 표기)']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u3-C21','kor',3,2,'u3',12,'낱말 그물 — 한 낱말에서 그곳에 있는 것·그곳에서 하는 일·그곳에서 지킬 것처럼 떠오르는 말이 여러 갈래로 뻗고, 떠오른 까닭은 저마다 다름(기초 다지기)',ARRAY['[4국04-03](케이티처 l14 표기)']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X01','kor',3,'u3',ARRAY['K3-2-u3-C1','K3-2-u3-C15']::text[],'설명하는 글을 따라 하기 어려운 까닭을 글씨 크기·글 길이에서 찾고, 일의 차례가 드러나야 한다는 것을 놓친다','읽는 사람이 무엇을 먼저 해야 하는지 알까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X02','kor',3,'u3',ARRAY['K3-2-u3-C2','K3-2-u3-C19']::text[],'설명할 내용이 모자라면 그럴듯하게 지어내거나 짐작해서 쓴다','내가 확인할 수 있는 곳인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X03','kor',3,'u3',ARRAY['K3-2-u3-C3','K3-2-u3-C9']::text[],'출처를 글쓴이 이름·신문 이름·쓴 날짜·쪽수와 헷갈린다','가져온 자료가 온 곳은 어디?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X04','kor',3,'u3',ARRAY['K3-2-u3-C4']::text[],'출처는 자료 아래 「■ 출처」로만 적는다고 여겨 글 속 「…에 따르면」을 놓치거나, 출처를 밝힌 곳을 엇갈리게 안다','글 속 문장 안에도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X05','kor',3,'u3',ARRAY['K3-2-u3-C5']::text[],'출처를 밝히는 까닭을 글을 길어 보이게·어려워 보이게 하려고라고 여긴다','읽는 사람은 출처로 무엇을 할 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X06','kor',3,'u3',ARRAY['K3-2-u3-C5','K3-2-u3-C16']::text[],'다른 사람이 만든 자료를 가져와 내가 생각해 낸 것처럼 쓴다','그 자료를 만든 사람은 누구?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X07','kor',3,'u3',ARRAY['K3-2-u3-C16']::text[],'찾아본 자료는 출처를 밝히면 쓸 수 있는데도 아예 빼야 한다고 여긴다','가져온 곳을 밝히면 쓸 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X08','kor',3,'u3',ARRAY['K3-2-u3-C6','K3-2-u3-C9']::text[],'글쓴이의 의견이나 글에 쓰인 내용을 잘못 읽는다','그 내용이 적힌 줄을 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X09','kor',3,'u3',ARRAY['K3-2-u3-C6','K3-2-u3-C9']::text[],'출처가 적혀 있지 않은 자료(들은 이야기·아래에 아무 글 없는 그림)도 출처가 있다고 여기거나, 자료와 출처를 엇갈리게 잇는다','그 자료 바로 옆·아래에 가져온 곳이 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X10','kor',3,'u3',ARRAY['K3-2-u3-C7']::text[],'출처를 확인하며 읽으면 글을 더 빨리 읽거나 읽지 않아도 내용을 알 수 있다고 여긴다','출처를 보면 무엇을 더 할 수 있게 되나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X11','kor',3,'u3',ARRAY['K3-2-u3-C7']::text[],'출처가 없는 자료의 아쉬움(더 알고 싶어도 찾아갈 곳이 없음)을 모르고 글 길이·낱말 탓을 한다','「어떤 형에게 들었다」면 어디로 가나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X12','kor',3,'u3',ARRAY['K3-2-u3-C8']::text[],'출처가 적혀 있으면 무엇이든 그대로 믿는다','이름만 적어 놓은 것일 수도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X13','kor',3,'u3',ARRAY['K3-2-u3-C8']::text[],'출처가 있어도 거짓일 수 있다며 글에 쓰인 자료를 무조건 믿지 않는다','살펴보고 생각하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X14','kor',3,'u3',ARRAY['K3-2-u3-C11']::text[],'출처의 이름이 길거나 글씨가 크면 믿을 만하다고 여겨, 직접 가 보거나 누리집에 들어가 보는 확인을 하지 않는다','내가 직접 해 볼 수 있는 일은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X15','kor',3,'u3',ARRAY['K3-2-u3-C10']::text[],'낱말 뜻을 앞뒤 문장을 보지 않고 짐작해 다른 낱말의 뜻과 섞는다','그 낱말이 든 문장에 넣어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X16','kor',3,'u3',ARRAY['K3-2-u3-C12','K3-2-u3-C19']::text[],'그리고·그러나·그래서의 쓰임(비슷한 내용·반대되는 내용·까닭)을 엇갈리게 안다','앞과 뒤가 비슷한가, 반대인가, 까닭인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X17','kor',3,'u3',ARRAY['K3-2-u3-C12']::text[],'때나 곳을 나타내는 말(목요일·체육관에서)을 이어 주는 말로 여긴다','앞 문장과 뒤 문장을 이어 주나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X18','kor',3,'u3',ARRAY['K3-2-u3-C13']::text[],'이어 주는 말은 문장마다 빠짐없이 넣을수록 좋다고 여긴다','개수가 아니라 앞뒤 뜻') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X19','kor',3,'u3',ARRAY['K3-2-u3-C13']::text[],'이어 주는 말을 하나도 쓰지 않아 앞뒤 문장이 왜 붙어 있는지 드러나지 않는다','두 문장이 왜 붙어 있지?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X20','kor',3,'u3',ARRAY['K3-2-u3-C14','K3-2-u3-C17']::text[],'글을 쓰기 전에 글씨 색·글자 수·제목 꾸미기부터 정한다','쓰기 전에 정할 것과 다 쓴 뒤 꾸밀 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X21','kor',3,'u3',ARRAY['K3-2-u3-C14','K3-2-u3-C15','K3-2-u3-C17']::text[],'읽을 사람과 목적을 생각하지 않고 쓸 내용을 정하거나, 어려운 낱말을 많이 써야 좋은 설명하는 글이라고 여긴다','누가 읽나? 그 사람이 알아들을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X22','kor',3,'u3',ARRAY['K3-2-u3-C15','K3-2-u3-C18']::text[],'차례를 나타내는 말을 일의 순서와 맞지 않게 쓰거나 꾸밈말로 여겨 아무 차례로 쓴다','먼저 → 다음으로 → 끝으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X23','kor',3,'u3',ARRAY['K3-2-u3-C16','K3-2-u3-C19']::text[],'찾아본 곳이 기억나지 않으면 그럴듯한 이름을 지어 적거나 출처 칸을 아무 말로 채운다','그 이름을 믿고 찾아간 친구는?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X24','kor',3,'u3',ARRAY['K3-2-u3-C16']::text[],'내가 직접 해 본 방법에도 출처를 꼭 붙여야 한다고 여긴다','내가 해 본 일인가, 찾아본 것인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X25','kor',3,'u3',ARRAY['K3-2-u3-C17','K3-2-u3-C19']::text[],'처음·가운데·끝(첫째·둘째·셋째 문단)에 들어갈 내용을 엇갈리게 놓는다','처음 읽는 사람이 무엇부터 알아야 할까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X26','kor',3,'u3',ARRAY['K3-2-u3-C18']::text[],'쓴 글을 점검하는 일을 칸을 채우거나 점수를 매기는 일로 여긴다','고치려고 보는 거예요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X27','kor',3,'u3',ARRAY['K3-2-u3-C18']::text[],'같은 일을 다른 방법으로 설명하면 하나는 틀린 글이라고 여긴다','차례와 까닭이 드러났나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X28','kor',3,'u3',ARRAY['K3-2-u3-C19']::text[],'사진·안내장처럼 자료의 종류가 다르면 가져온 곳을 적지 않아도 된다고 여긴다','종류가 달라도 가져온 곳은') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X29','kor',3,'u3',ARRAY['K3-2-u3-C20']::text[],'‘-데’와 ‘-대’를 ‘보니’가 붙었는지로 가르거나 바꾸어 쓴다','내가 겪었나, 남에게 들었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X30','kor',3,'u3',ARRAY['K3-2-u3-C21']::text[],'낱말 그물에서 떠오른 말과 떠오른 까닭을 엇갈리게 잇거나, 한 낱말에서 한 갈래로만 떠올려야 한다고 여긴다','그 말이 무엇을 가리키나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u3-X31','kor',3,'u3',ARRAY['K3-2-u3-C1','K3-2-u3-C14']::text[],'설명하는 글을 읽는 사람이 따라 할 수 있게 알려 주는 글이 아니라 내 느낌이나 꾸민 이야기를 쓰는 글로 여긴다','읽는 사람이 따라 할 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L02_basic#1','kor',3,2,'u3','L02','g3_2_kor_u3_L02_basic','lesson_basic','K3-2-u3-C1',1,'mc','auto','설명하는 글은 어떤 글인가요?',ARRAY['K3-2-u3-X31','K3-2-u3-X01']::text[],false,'{"seq":1,"concept":"K3-2-u3-C1","difficulty":1,"kind":"mc","stem":"설명하는 글은 어떤 글인가요?","options":[{"t":"무엇을 만드는 방법이나 놀이를 하는 차례처럼 일을 알려 주는 글","correct":true},{"t":"내가 겪은 일에 대한 느낌만 쓴 글","mis":"K3-2-u3-X31"},{"t":"있었던 일을 꾸며 쓴 이야기","mis":"K3-2-u3-X31"},{"t":"글씨를 크게 쓴 글","mis":"K3-2-u3-X01"}],"explanation":["설명하는 글은 무엇을 알려 줘요.","만드는 방법, 가는 길, 놀이 차례 같은 것이에요.","읽는 사람이 따라 할 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L02_basic#2','kor',3,2,'u3','L02','g3_2_kor_u3_L02_basic','lesson_basic','K3-2-u3-C1',1,'mc','auto','도영이가 하선이 글을 따라 하기 어려웠던 까닭은 무엇인가요?',ARRAY['K3-2-u3-X01','K3-2-u3-X31']::text[],false,'{"seq":2,"concept":"K3-2-u3-C1","difficulty":1,"kind":"mc","stem":"도영이가 하선이 글을 따라 하기 어려웠던 까닭은 무엇인가요?","options":[{"t":"일의 차례가 드러나지 않아서","correct":true},{"t":"글씨가 작아서","mis":"K3-2-u3-X01"},{"t":"글이 너무 짧아서","mis":"K3-2-u3-X01"},{"t":"딱지 놀이가 재미없어서","mis":"K3-2-u3-X31"}],"explanation":["도영이가 한 말을 다시 읽어요.","무엇을 먼저 해야 할지 모르겠다고 했어요.","차례가 드러나야 따라 해요."],"asset":{"type":"speech","turns":[{"who":"하선","text":"“딱지 접는 방법을 알려 줄게. 색종이를 반으로 접어. 그리고 또 접어. 그다음에 끼우면 돼.”"},{"who":"도영","text":"읽어 봤는데 무엇을 먼저 해야 하는지 모르겠어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L02_basic#3','kor',3,2,'u3','L02','g3_2_kor_u3_L02_basic','lesson_basic','K3-2-u3-C3',1,'ox','auto','출처는 가져온 자료가 어디에서 왔는지 알려 주는 것이에요.',ARRAY['K3-2-u3-X03']::text[],false,'{"seq":3,"concept":"K3-2-u3-C3","difficulty":1,"kind":"ox","stem":"출처는 가져온 자료가 어디에서 왔는지 알려 주는 것이에요.","answer":"O","reason_options":[{"t":"자료를 만든 곳이나 자료의 이름처럼 자료가 온 곳을 알려 주기 때문에","correct":true},{"t":"글을 쓴 날짜를 알려 주는 것이기 때문에","mis":"K3-2-u3-X03"}],"mis":"K3-2-u3-X03","explanation":["출처는 자료가 온 곳이에요.","만든 곳이나 자료 이름을 적어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L02_basic#4','kor',3,2,'u3','L02','g3_2_kor_u3_L02_basic','lesson_basic','K3-2-u3-C2',1,'mc','auto','설명할 내용을 더 알아볼 곳으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X02','K3-2-u3-X06']::text[],false,'{"seq":4,"concept":"K3-2-u3-C2","difficulty":1,"kind":"mc","stem":"설명할 내용을 더 알아볼 곳으로 알맞은 것은 무엇인가요?","options":[{"t":"도서관에서 빌린 책","correct":true},{"t":"잘 모르지만 그럴듯하게 지어내기","mis":"K3-2-u3-X02"},{"t":"아마 그럴 것 같다고 짐작하기","mis":"K3-2-u3-X02"},{"t":"친구가 쓴 글을 내 것처럼 옮기기","mis":"K3-2-u3-X06"}],"explanation":["내가 확인할 수 있는 곳이어야 해요.","책·누리집·잘 아는 어른이 있어요.","지어내는 것은 알아본 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L02_basic#5','kor',3,2,'u3','L02','g3_2_kor_u3_L02_basic','lesson_basic','K3-2-u3-C3',2,'mc','auto','「급식실에서 지킬 것」에서 출처로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X03','K3-2-u3-X08']::text[],false,'{"seq":5,"concept":"K3-2-u3-C3","difficulty":2,"kind":"mc","stem":"「급식실에서 지킬 것」에서 출처로 알맞은 것은 무엇인가요?","options":[{"t":"「손 씻는 차례」, 보건실 안내장","correct":true},{"t":"글 하선","mis":"K3-2-u3-X03"},{"t":"3학년 1반 학급 신문","mis":"K3-2-u3-X03"},{"t":"우리 반 친구들 모두","mis":"K3-2-u3-X08"}],"explanation":["가져온 자료가 온 곳을 찾아요.","하선이는 글을 쓴 사람이에요.","보건실 안내장이 출처예요."],"asset":{"type":"passage","lines":["우리 학교 누리집에 올라와 있는 「급식실 이용 안내」에 따르면,","급식실에 들어가기 전에는 손을 씻고 차례대로 줄을 서야 한다고 합니다.","식판을 받을 때에는 먹을 만큼만 받습니다.","다 먹은 뒤에는 정해진 곳에 식판을 놓습니다.","손을 씻는 차례를 그린 그림이 보건실 앞에 붙어 있습니다.","[그림] 손을 씻는 차례를 나타낸 그림","■ 출처: 「손 씻는 차례」, 보건실 안내장.","우리 반 친구들 모두 급식실에서 지킬 것을 지켜 봅시다."],"title":"「급식실에서 지킬 것」 — 3학년 1반 학급 신문 · 글 하선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L02_basic#6','kor',3,2,'u3','L02','g3_2_kor_u3_L02_basic','lesson_basic','K3-2-u3-C4',2,'match','auto','출처를 밝힌 방법과 밝힌 곳을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K3-2-u3-C4","difficulty":2,"kind":"match","stem":"출처를 밝힌 방법과 밝힌 곳을 알맞게 이으세요.","pairs":[{"l":"“「급식실 이용 안내」에 따르면”","r":"글 속 문장 안"},{"l":"“■ 출처: 「손 씻는 차례」, 보건실 안내장.”","r":"그림 자료 바로 아래"},{"l":"작은 글씨로 적은 출처","r":"영상 화면 아래쪽"}],"mis":"K3-2-u3-X04","explanation":["출처는 여러 곳에 적어요.","문장 안에도, 그림 아래에도 있어요.","영상은 화면 아래에 적기도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L02_basic#7','kor',3,2,'u3','L02','g3_2_kor_u3_L02_basic','lesson_basic','K3-2-u3-C5',2,'mc','auto','글에 출처를 밝히는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X05','K3-2-u3-X06']::text[],false,'{"seq":7,"concept":"K3-2-u3-C5","difficulty":2,"kind":"mc","stem":"글에 출처를 밝히는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"자료를 어디에서 가져왔는지 알리려고","correct":true},{"t":"글이 길어 보이게 하려고","mis":"K3-2-u3-X05"},{"t":"글이 어려워 보이게 하려고","mis":"K3-2-u3-X05"},{"t":"가져온 자료를 내 것으로 만들려고","mis":"K3-2-u3-X06"}],"explanation":["출처가 없으면 읽는 사람이 살펴볼 수 없어요.","어디에서 왔는지 알려 줘요.","내 것처럼 쓰지 않는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L02_basic#8','kor',3,2,'u3','L02','g3_2_kor_u3_L02_basic','lesson_basic','K3-2-u3-C3',2,'mc','auto','글 ㉯가 글 ㉮보다 믿음이 가는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X05','K3-2-u3-X21','K3-2-u3-X13']::text[],false,'{"seq":8,"concept":"K3-2-u3-C3","difficulty":2,"kind":"mc","stem":"글 ㉯가 글 ㉮보다 믿음이 가는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"어디에서 알아낸 것인지 밝혀 살펴볼 수 있어서","correct":true},{"t":"㉯가 더 길어서","mis":"K3-2-u3-X05"},{"t":"㉯에 어려운 말이 많아서","mis":"K3-2-u3-X21"},{"t":"㉮는 친구가 말했으니 무조건 틀려서","mis":"K3-2-u3-X13"}],"explanation":["㉯에는 「이용 안내」가 나와요.","어디에서 알아냈는지 알 수 있어요.","그래서 살펴볼 수 있어요."],"asset":{"type":"passage","lines":["글 ㉮ — “도서관 책은 아무 때나 돌려주어도 된대. 내가 들었어.”","글 ㉯ — “도서관 앞 「이용 안내」에 따르면,","빌린 책은 정해진 날까지 돌려주어야 한다고 합니다.”"],"title":"같은 이야기, 두 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L02_basic#9','kor',3,2,'u3','L02','g3_2_kor_u3_L02_basic','lesson_basic','K3-2-u3-C5',2,'ox','auto','출처를 밝히면 그 자료를 만든 사람의 것을 내 것처럼 쓰지 않았다는 뜻이 돼요.',ARRAY['K3-2-u3-X05']::text[],false,'{"seq":9,"concept":"K3-2-u3-C5","difficulty":2,"kind":"ox","stem":"출처를 밝히면 그 자료를 만든 사람의 것을 내 것처럼 쓰지 않았다는 뜻이 돼요.","answer":"O","reason_options":[{"t":"다른 사람이 만든 것을 존중하는 일이기 때문에","correct":true},{"t":"출처는 글을 꾸미는 장식이기 때문에","mis":"K3-2-u3-X05"}],"mis":"K3-2-u3-X05","explanation":["자료를 만든 사람이 있어요.","출처는 그 사람을 밝혀 줘요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L02_basic#10','kor',3,2,'u3','L02','g3_2_kor_u3_L02_basic','lesson_basic','K3-2-u3-C2',3,'error','auto','하선이가 딱지 접는 방법을 더 자세히 쓰려고 알아볼 곳을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X02']::text[],false,'{"seq":10,"concept":"K3-2-u3-C2","difficulty":3,"kind":"error","stem":"하선이가 딱지 접는 방법을 더 자세히 쓰려고 알아볼 곳을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「기억이 안 나는 곳은 그럴 것 같은 대로 지어 쓰면 돼.」","correct":true,"mis_target":"K3-2-u3-X02"},{"t":"친구 가 — 「종이접기 책을 찾아보자.」","mis":"K3-2-u3-X02"},{"t":"친구 나 — 「종이접기를 잘 아시는 어른께 여쭈어보자.」","mis":"K3-2-u3-X02"}],"explanation":["알아볼 곳은 확인할 수 있는 곳이에요.","책과 어른은 확인할 수 있어요.","친구 다는 지어내자고 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L02_challenge#1','kor',3,2,'u3','L02','g3_2_kor_u3_L02_challenge','lesson_challenge','K3-2-u3-C3',2,'sa','auto','자료를 만든 곳이나 자료의 이름처럼 자료가 어디에서 왔는지 알려 주는 것을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u3-C3","difficulty":2,"kind":"sa","stem":"자료를 만든 곳이나 자료의 이름처럼 자료가 어디에서 왔는지 알려 주는 것을 두 글자로 쓰세요.","answer":["출처"],"explanation":["자료가 온 곳을 알려 줘요.","글 끝에 「■」와 함께 적기도 해요.","출처예요."],"mis":"K3-2-u3-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L02_challenge#2','kor',3,2,'u3','L02','g3_2_kor_u3_L02_challenge','lesson_challenge','K3-2-u3-C4',2,'mc','auto','「급식실에서 지킬 것」에서 출처를 글 속 문장 안에 밝힌 것은 무엇인가요?',ARRAY['K3-2-u3-X04','K3-2-u3-X03']::text[],false,'{"seq":2,"concept":"K3-2-u3-C4","difficulty":2,"kind":"mc","stem":"「급식실에서 지킬 것」에서 출처를 글 속 문장 안에 밝힌 것은 무엇인가요?","options":[{"t":"「급식실 이용 안내」, 학교 누리집","correct":true},{"t":"「손 씻는 차례」, 보건실 안내장","mis":"K3-2-u3-X04"},{"t":"글 하선","mis":"K3-2-u3-X03"},{"t":"3학년 1반 학급 신문","mis":"K3-2-u3-X03"}],"explanation":["「…에 따르면」을 찾아요.","첫 문장 안에 있어요.","학교 누리집의 안내예요."],"asset":{"type":"passage","lines":["우리 학교 누리집에 올라와 있는 「급식실 이용 안내」에 따르면,","급식실에 들어가기 전에는 손을 씻고 차례대로 줄을 서야 한다고 합니다.","식판을 받을 때에는 먹을 만큼만 받습니다.","다 먹은 뒤에는 정해진 곳에 식판을 놓습니다.","손을 씻는 차례를 그린 그림이 보건실 앞에 붙어 있습니다.","[그림] 손을 씻는 차례를 나타낸 그림","■ 출처: 「손 씻는 차례」, 보건실 안내장.","우리 반 친구들 모두 급식실에서 지킬 것을 지켜 봅시다."],"title":"「급식실에서 지킬 것」 — 3학년 1반 학급 신문 · 글 하선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L02_challenge#3','kor',3,2,'u3','L02','g3_2_kor_u3_L02_challenge','lesson_challenge','K3-2-u3-C3',3,'error','auto','「급식실에서 지킬 것」의 출처를 찾았어요. 잘못 찾은 친구는 누구인가요?',ARRAY['K3-2-u3-X03','K3-2-u3-X04']::text[],false,'{"seq":3,"concept":"K3-2-u3-C3","difficulty":3,"kind":"error","stem":"「급식실에서 지킬 것」의 출처를 찾았어요. 잘못 찾은 친구는 누구인가요?","options":[{"t":"친구 나 — 「「글 하선」도 출처야. 글을 쓴 사람이니까.」","correct":true,"mis_target":"K3-2-u3-X03"},{"t":"친구 가 — 「「손 씻는 차례」, 보건실 안내장」","mis":"K3-2-u3-X04"},{"t":"친구 다 — 「「급식실 이용 안내」, 학교 누리집」","mis":"K3-2-u3-X04"}],"explanation":["글쓴이는 이 글을 쓴 사람이에요.","출처는 가져온 자료가 온 곳이에요.","친구 나가 잘못 찾았어요."],"asset":{"type":"passage","lines":["우리 학교 누리집에 올라와 있는 「급식실 이용 안내」에 따르면,","급식실에 들어가기 전에는 손을 씻고 차례대로 줄을 서야 한다고 합니다.","식판을 받을 때에는 먹을 만큼만 받습니다.","다 먹은 뒤에는 정해진 곳에 식판을 놓습니다.","손을 씻는 차례를 그린 그림이 보건실 앞에 붙어 있습니다.","[그림] 손을 씻는 차례를 나타낸 그림","■ 출처: 「손 씻는 차례」, 보건실 안내장.","우리 반 친구들 모두 급식실에서 지킬 것을 지켜 봅시다."],"title":"「급식실에서 지킬 것」 — 3학년 1반 학급 신문 · 글 하선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L02_challenge#4','kor',3,2,'u3','L02','g3_2_kor_u3_L02_challenge','lesson_challenge','K3-2-u3-C1',3,'ox','auto','설명하는 글은 읽는 사람이 그대로 따라 할 수 있게 일의 차례가 드러나야 해요.',ARRAY['K3-2-u3-X01']::text[],false,'{"seq":4,"concept":"K3-2-u3-C1","difficulty":3,"kind":"ox","stem":"설명하는 글은 읽는 사람이 그대로 따라 할 수 있게 일의 차례가 드러나야 해요.","answer":"O","reason_options":[{"t":"차례가 드러나지 않으면 무엇을 먼저 할지 알 수 없기 때문에","correct":true},{"t":"글씨만 크게 쓰면 누구나 따라 할 수 있기 때문에","mis":"K3-2-u3-X01"}],"mis":"K3-2-u3-X01","explanation":["도영이를 떠올려요.","차례가 없어서 막혔어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L02_challenge#5','kor',3,2,'u3','L02','g3_2_kor_u3_L02_challenge','lesson_challenge','K3-2-u3-C5',3,'mc','auto','출처를 밝히면 생기는 두 가지 좋은 점을 알맞게 짝지은 것은 무엇인가요?',ARRAY['K3-2-u3-X05','K3-2-u3-X10','K3-2-u3-X06']::text[],false,'{"seq":5,"concept":"K3-2-u3-C5","difficulty":3,"kind":"mc","stem":"출처를 밝히면 생기는 두 가지 좋은 점을 알맞게 짝지은 것은 무엇인가요?","options":[{"t":"읽는 사람이 믿을 만한지 살펴볼 수 있다 · 만든 사람의 것을 존중한다","correct":true},{"t":"글이 길어진다 · 글이 어려워 보인다","mis":"K3-2-u3-X05"},{"t":"글을 안 읽어도 된다 · 빨리 읽는다","mis":"K3-2-u3-X10"},{"t":"내 생각처럼 보인다 · 칭찬을 받는다","mis":"K3-2-u3-X06"}],"explanation":["읽는 사람 쪽에서 하나예요.","만든 사람 쪽에서 하나예요.","살펴보기와 존중이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L02_challenge#6','kor',3,2,'u3','L02','g3_2_kor_u3_L02_challenge','lesson_challenge','K3-2-u3-C2',3,'mc','auto','딱지 접는 방법을 쓰다가 마지막 차례가 기억나지 않아요. 어떻게 하는 것이 가장 알맞은가요?',ARRAY['K3-2-u3-X02','K3-2-u3-X06','K3-2-u3-X01']::text[],false,'{"seq":6,"concept":"K3-2-u3-C2","difficulty":3,"kind":"mc","stem":"딱지 접는 방법을 쓰다가 마지막 차례가 기억나지 않아요. 어떻게 하는 것이 가장 알맞은가요?","options":[{"t":"종이접기 책을 다시 찾아보거나 직접 접어 보며 확인한다","correct":true},{"t":"그럴 것 같은 대로 짐작해 쓴다","mis":"K3-2-u3-X02"},{"t":"친구가 쓴 글을 그대로 옮겨 내 것처럼 쓴다","mis":"K3-2-u3-X06"},{"t":"차례는 상관없으니 아무 순서로 쓴다","mis":"K3-2-u3-X01"}],"explanation":["모르는 것은 확인해요.","책을 보거나 직접 해 봐요.","짐작해 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L02_challenge#7','kor',3,2,'u3','L02','g3_2_kor_u3_L02_challenge','lesson_challenge','K3-2-u3-C1',3,'match','auto','이 단원에서 배울 내용과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u3-C1","difficulty":3,"kind":"match","stem":"이 단원에서 배울 내용과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"출처를 확인하며 글 읽기","r":"자료를 어디에서 가져왔는지 살피며 읽는 것"},{"l":"순서나 방법을 설명하는 글 쓰기","r":"일의 차례가 드러나게 알려 주는 글을 쓰는 것"},{"l":"이어 주는 말","r":"앞 문장과 뒤 문장을 이어 주는 말"}],"mis":"K3-2-u3-X31","explanation":["낱말 속에 뜻이 들어 있어요.","읽기 하나, 쓰기 하나예요.","이어 주는 말은 문장 사이에 놓여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L02_challenge#8','kor',3,2,'u3','L02','g3_2_kor_u3_L02_challenge','lesson_challenge','K3-2-u3-C4',4,'mc','auto','하선이는 「손 씻는 차례」는 그림 바로 아래에, 「급식실 이용 안내」는 문장 안에 출처를 밝혔어요. 이렇게 다르게 적은 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X04','K3-2-u3-X28','K3-2-u3-X05']::text[],false,'{"seq":8,"concept":"K3-2-u3-C4","difficulty":4,"kind":"mc","stem":"하선이는 「손 씻는 차례」는 그림 바로 아래에, 「급식실 이용 안내」는 문장 안에 출처를 밝혔어요. 이렇게 다르게 적은 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"그림은 바로 아래에, 글로 가져온 내용은 그 문장 안에 밝히면 어느 자료가 어디서 왔는지 바로 알 수 있어서","correct":true},{"t":"출처는 한 글에 한 번만 적어야 해서","mis":"K3-2-u3-X04"},{"t":"그림에는 출처가 필요 없어서 덧붙인 것이라서","mis":"K3-2-u3-X28"},{"t":"글을 길어 보이게 하려고","mis":"K3-2-u3-X05"}],"explanation":["자료마다 모양이 달라요.","그 자료 가까이에 밝혀요.","그래서 어느 자료인지 바로 알아요."],"asset":{"type":"passage","lines":["우리 학교 누리집에 올라와 있는 「급식실 이용 안내」에 따르면,","급식실에 들어가기 전에는 손을 씻고 차례대로 줄을 서야 한다고 합니다.","식판을 받을 때에는 먹을 만큼만 받습니다.","다 먹은 뒤에는 정해진 곳에 식판을 놓습니다.","손을 씻는 차례를 그린 그림이 보건실 앞에 붙어 있습니다.","[그림] 손을 씻는 차례를 나타낸 그림","■ 출처: 「손 씻는 차례」, 보건실 안내장.","우리 반 친구들 모두 급식실에서 지킬 것을 지켜 봅시다."],"title":"「급식실에서 지킬 것」 — 3학년 1반 학급 신문 · 글 하선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L02_challenge#9','kor',3,2,'u3','L02','g3_2_kor_u3_L02_challenge','lesson_challenge','K3-2-u3-C1',4,'essay','teacher','하선이의 딱지 접는 글을 도영이가 따라 할 수 있게 고치는 방법 두 가지를 쓰고, 각각 그렇게 고치는 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u3-C1","difficulty":4,"kind":"essay","stem":"하선이의 딱지 접는 글을 도영이가 따라 할 수 있게 고치는 방법 두 가지를 쓰고, 각각 그렇게 고치는 까닭을 쓰세요.","answer_guide":{"answer":"예: 첫째, 「먼저」·「다음으로」·「끝으로」 같은 말을 넣어 접는 차례를 드러낸다. 무엇을 먼저 해야 하는지 알 수 있기 때문이다. 둘째, 「또 접어」처럼 흐린 말 대신 어느 쪽으로 접는지 자세히 쓴다. 읽는 사람이 그대로 따라 할 수 있기 때문이다.","scoring_points":["차례를 드러내는 방법을 썼는가","자세히 쓰는 방법을 썼는가","읽는 사람이 따라 할 수 있다는 까닭을 썼는가"]},"explanation":["도영이가 막힌 곳을 떠올려요.","차례와 자세함이 필요해요.","읽는 사람 쪽에서 까닭을 써요."],"asset":{"type":"speech","turns":[{"who":"하선","text":"“딱지 접는 방법을 알려 줄게. 색종이를 반으로 접어. 그리고 또 접어. 그다음에 끼우면 돼.”"},{"who":"도영","text":"읽어 봤는데 무엇을 먼저 해야 하는지 모르겠어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L02_challenge#10','kor',3,2,'u3','L02','g3_2_kor_u3_L02_challenge','lesson_challenge','K3-2-u3-C5',4,'essay','teacher','책에서 찾은 내용을 내 글에 쓸 때 어떻게 해야 하는지 쓰고, 그렇게 해야 하는 까닭을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u3-C5","difficulty":4,"kind":"essay","stem":"책에서 찾은 내용을 내 글에 쓸 때 어떻게 해야 하는지 쓰고, 그렇게 해야 하는 까닭을 두 가지 쓰세요.","answer_guide":{"answer":"예: 책에서 찾은 내용을 쓸 때에는 어느 책에서 가져왔는지 출처를 함께 밝힌다. 첫째, 읽는 사람이 믿을 만한 자료인지 살펴보고 더 찾아볼 수 있다. 둘째, 그 책을 만든 사람의 것을 내 것처럼 쓰지 않아 존중하는 일이 된다.","scoring_points":["출처를 함께 밝힌다고 썼는가","읽는 사람 쪽 까닭을 썼는가","만든 사람을 존중한다는 까닭을 썼는가"]},"explanation":["1차시와 14차시의 물음이에요.","가져온 곳을 밝혀요.","까닭은 두 쪽에서 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L03_basic#1','kor',3,2,'u3','L03','g3_2_kor_u3_L03_basic','lesson_basic','K3-2-u3-C6',1,'mc','auto','「복도에서는 걸어 다녀요」에서 글쓴이가 하고 싶은 말은 무엇인가요?',ARRAY['K3-2-u3-X08']::text[],false,'{"seq":1,"concept":"K3-2-u3-C6","difficulty":1,"kind":"mc","stem":"「복도에서는 걸어 다녀요」에서 글쓴이가 하고 싶은 말은 무엇인가요?","options":[{"t":"복도에서는 걸어 다니자","correct":true},{"t":"복도를 쓰지 말자","mis":"K3-2-u3-X08"},{"t":"복도에서는 빨리 다니자","mis":"K3-2-u3-X08"},{"t":"모퉁이에 그림을 붙이자","mis":"K3-2-u3-X08"}],"explanation":["마지막 줄을 다시 읽어요.","걸어 다니기로 하자고 했어요.","그것이 글쓴이의 의견이에요."],"asset":{"type":"passage","lines":["복도는 여러 반이 함께 쓰는 곳이고, 모퉁이에서는 앞이 잘 보이지 않습니다.","㉮ 어떤 형에게 들으니 복도에서 부딪치는 일이 많다고 합니다.","㉯ [그림] 복도에서 나란히 걸어가는 모습을 그린 그림","㉰ 보건실 안내장 「다친 곳을 줄이려면」에 따르면,","부딪쳐서 다치는 일은 걸을 때보다 뛸 때 더 자주 생긴다고 합니다.","㉱ [그림] 오른쪽으로 걸어가는 방향을 나타낸 그림","■ 출처: 「복도 통행 안내」, 학교 누리집.","우리 모두 복도에서는 걸어 다니기로 해요."],"title":"주장하는 글 「복도에서는 걸어 다녀요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L03_basic#2','kor',3,2,'u3','L03','g3_2_kor_u3_L03_basic','lesson_basic','K3-2-u3-C6',1,'mc','auto','글쓴이가 복도에서 뛰면 안 된다고 한 까닭은 무엇인가요?',ARRAY['K3-2-u3-X08']::text[],false,'{"seq":2,"concept":"K3-2-u3-C6","difficulty":1,"kind":"mc","stem":"글쓴이가 복도에서 뛰면 안 된다고 한 까닭은 무엇인가요?","options":[{"t":"여러 반이 함께 쓰고 모퉁이에서는 앞이 잘 보이지 않아서","correct":true},{"t":"복도가 너무 넓어서","mis":"K3-2-u3-X08"},{"t":"형에게 혼날까 봐서","mis":"K3-2-u3-X08"},{"t":"복도에 그림이 붙어 있어서","mis":"K3-2-u3-X08"}],"explanation":["첫 줄을 다시 읽어요.","함께 쓰는 곳이에요.","모퉁이는 앞이 안 보여요."],"asset":{"type":"passage","lines":["복도는 여러 반이 함께 쓰는 곳이고, 모퉁이에서는 앞이 잘 보이지 않습니다.","㉮ 어떤 형에게 들으니 복도에서 부딪치는 일이 많다고 합니다.","㉯ [그림] 복도에서 나란히 걸어가는 모습을 그린 그림","㉰ 보건실 안내장 「다친 곳을 줄이려면」에 따르면,","부딪쳐서 다치는 일은 걸을 때보다 뛸 때 더 자주 생긴다고 합니다.","㉱ [그림] 오른쪽으로 걸어가는 방향을 나타낸 그림","■ 출처: 「복도 통행 안내」, 학교 누리집.","우리 모두 복도에서는 걸어 다니기로 해요."],"title":"주장하는 글 「복도에서는 걸어 다녀요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L03_basic#3','kor',3,2,'u3','L03','g3_2_kor_u3_L03_basic','lesson_basic','K3-2-u3-C7',1,'ox','auto','출처를 확인하며 읽으면 글에 쓰인 자료가 믿을 만한지 살펴볼 수 있어요.',ARRAY['K3-2-u3-X10']::text[],false,'{"seq":3,"concept":"K3-2-u3-C7","difficulty":1,"kind":"ox","stem":"출처를 확인하며 읽으면 글에 쓰인 자료가 믿을 만한지 살펴볼 수 있어요.","answer":"O","reason_options":[{"t":"어디에서 가져온 자료인지 알 수 있기 때문에","correct":true},{"t":"출처를 보면 글을 읽지 않아도 되기 때문에","mis":"K3-2-u3-X10"}],"mis":"K3-2-u3-X10","explanation":["출처는 자료가 온 곳이에요.","온 곳을 알면 살펴볼 수 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L03_basic#4','kor',3,2,'u3','L03','g3_2_kor_u3_L03_basic','lesson_basic','K3-2-u3-C8',1,'mc','auto','연호와 하경이의 말을 듣고, 출처가 적혀 있는 자료를 읽는 알맞은 태도를 고르세요.',ARRAY['K3-2-u3-X12','K3-2-u3-X13','K3-2-u3-X10']::text[],false,'{"seq":4,"concept":"K3-2-u3-C8","difficulty":1,"kind":"mc","stem":"연호와 하경이의 말을 듣고, 출처가 적혀 있는 자료를 읽는 알맞은 태도를 고르세요.","options":[{"t":"어떤 곳에서 가져왔는지 살펴보고 생각한다","correct":true},{"t":"출처가 있으면 무엇이든 그대로 믿는다","mis":"K3-2-u3-X12"},{"t":"출처가 있어도 믿지 않는다","mis":"K3-2-u3-X13"},{"t":"출처는 읽지 않고 넘어간다","mis":"K3-2-u3-X10"}],"explanation":["출처가 있다고 다 맞지는 않아요.","다 틀린 것도 아니에요.","어떤 곳인지 살펴봐요."],"asset":{"type":"speech","turns":[{"who":"연호","text":"출처가 적혀 있으면 그건 다 맞는 말이야."},{"who":"하경","text":"이름만 적어 놓은 걸 수도 있잖아. 어떤 곳인지 봐야지."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L03_basic#5','kor',3,2,'u3','L03','g3_2_kor_u3_L03_basic','lesson_basic','K3-2-u3-C6',2,'match','auto','「복도에서는 걸어 다녀요」의 자료와 그 출처를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u3-C6","difficulty":2,"kind":"match","stem":"「복도에서는 걸어 다녀요」의 자료와 그 출처를 알맞게 이으세요.","pairs":[{"l":"㉰ 뛸 때 더 자주 다친다는 내용","r":"보건실 안내장 「다친 곳을 줄이려면」"},{"l":"㉱ 걸어가는 방향을 나타낸 그림","r":"「복도 통행 안내」, 학교 누리집"},{"l":"㉮ 형에게 들은 이야기","r":"출처 없음"}],"mis":"K3-2-u3-X09","explanation":["자료 바로 옆이나 아래를 봐요.","㉰는 문장 안에 있어요.","㉮는 어디서 왔는지 알 수 없어요."],"asset":{"type":"passage","lines":["복도는 여러 반이 함께 쓰는 곳이고, 모퉁이에서는 앞이 잘 보이지 않습니다.","㉮ 어떤 형에게 들으니 복도에서 부딪치는 일이 많다고 합니다.","㉯ [그림] 복도에서 나란히 걸어가는 모습을 그린 그림","㉰ 보건실 안내장 「다친 곳을 줄이려면」에 따르면,","부딪쳐서 다치는 일은 걸을 때보다 뛸 때 더 자주 생긴다고 합니다.","㉱ [그림] 오른쪽으로 걸어가는 방향을 나타낸 그림","■ 출처: 「복도 통행 안내」, 학교 누리집.","우리 모두 복도에서는 걸어 다니기로 해요."],"title":"주장하는 글 「복도에서는 걸어 다녀요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L03_basic#6','kor',3,2,'u3','L03','g3_2_kor_u3_L03_basic','lesson_basic','K3-2-u3-C6',2,'mc','auto','「복도에서는 걸어 다녀요」에서 출처가 있는 자료를 바르게 고른 것은 무엇인가요?',ARRAY['K3-2-u3-X09']::text[],false,'{"seq":6,"concept":"K3-2-u3-C6","difficulty":2,"kind":"mc","stem":"「복도에서는 걸어 다녀요」에서 출처가 있는 자료를 바르게 고른 것은 무엇인가요?","options":[{"t":"㉰와 ㉱","correct":true},{"t":"㉮와 ㉯","mis":"K3-2-u3-X09"},{"t":"㉮와 ㉰","mis":"K3-2-u3-X09"},{"t":"㉯와 ㉱","mis":"K3-2-u3-X09"}],"explanation":["가져온 곳이 적혀 있는지만 봐요.","㉰는 안내장, ㉱는 누리집이에요.","㉮·㉯는 적혀 있지 않아요."],"asset":{"type":"passage","lines":["복도는 여러 반이 함께 쓰는 곳이고, 모퉁이에서는 앞이 잘 보이지 않습니다.","㉮ 어떤 형에게 들으니 복도에서 부딪치는 일이 많다고 합니다.","㉯ [그림] 복도에서 나란히 걸어가는 모습을 그린 그림","㉰ 보건실 안내장 「다친 곳을 줄이려면」에 따르면,","부딪쳐서 다치는 일은 걸을 때보다 뛸 때 더 자주 생긴다고 합니다.","㉱ [그림] 오른쪽으로 걸어가는 방향을 나타낸 그림","■ 출처: 「복도 통행 안내」, 학교 누리집.","우리 모두 복도에서는 걸어 다니기로 해요."],"title":"주장하는 글 「복도에서는 걸어 다녀요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L03_basic#7','kor',3,2,'u3','L03','g3_2_kor_u3_L03_basic','lesson_basic','K3-2-u3-C7',2,'mc','auto','출처가 없는 자료 ㉮의 아쉬운 점은 무엇인가요?',ARRAY['K3-2-u3-X11','K3-2-u3-X03']::text[],false,'{"seq":7,"concept":"K3-2-u3-C7","difficulty":2,"kind":"mc","stem":"출처가 없는 자료 ㉮의 아쉬운 점은 무엇인가요?","options":[{"t":"더 알고 싶어도 찾아갈 곳을 알 수 없다","correct":true},{"t":"글이 너무 짧아진다","mis":"K3-2-u3-X11"},{"t":"낱말이 어려워진다","mis":"K3-2-u3-X11"},{"t":"글쓴이가 누구인지 알 수 없다","mis":"K3-2-u3-X03"}],"explanation":["「어떤 형에게 들으니」만 있어요.","어느 형인지 몰라요.","찾아갈 곳이 없어요."],"asset":{"type":"passage","lines":["복도는 여러 반이 함께 쓰는 곳이고, 모퉁이에서는 앞이 잘 보이지 않습니다.","㉮ 어떤 형에게 들으니 복도에서 부딪치는 일이 많다고 합니다.","㉯ [그림] 복도에서 나란히 걸어가는 모습을 그린 그림","㉰ 보건실 안내장 「다친 곳을 줄이려면」에 따르면,","부딪쳐서 다치는 일은 걸을 때보다 뛸 때 더 자주 생긴다고 합니다.","㉱ [그림] 오른쪽으로 걸어가는 방향을 나타낸 그림","■ 출처: 「복도 통행 안내」, 학교 누리집.","우리 모두 복도에서는 걸어 다니기로 해요."],"title":"주장하는 글 「복도에서는 걸어 다녀요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L03_basic#8','kor',3,2,'u3','L03','g3_2_kor_u3_L03_basic','lesson_basic','K3-2-u3-C7',2,'mc','auto','「「복도 통행 안내」라고 적혀 있길래 학교 누리집에 들어가 봤어. 계단에서 지킬 것도 같이 나와 있더라.」 이 친구가 출처를 보고 한 일은 무엇인가요?',ARRAY['K3-2-u3-X10','K3-2-u3-X12']::text[],false,'{"seq":8,"concept":"K3-2-u3-C7","difficulty":2,"kind":"mc","stem":"「「복도 통행 안내」라고 적혀 있길래 학교 누리집에 들어가 봤어. 계단에서 지킬 것도 같이 나와 있더라.」 이 친구가 출처를 보고 한 일은 무엇인가요?","options":[{"t":"궁금한 것을 더 찾아보았다","correct":true},{"t":"글을 더 빨리 읽었다","mis":"K3-2-u3-X10"},{"t":"글을 읽지 않고 내용을 알았다","mis":"K3-2-u3-X10"},{"t":"출처가 있으니 무조건 다 맞다고 정했다","mis":"K3-2-u3-X12"}],"explanation":["출처를 보고 누리집에 갔어요.","계단 이야기를 더 알게 됐어요.","더 찾아본 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L03_basic#9','kor',3,2,'u3','L03','g3_2_kor_u3_L03_basic','lesson_basic','K3-2-u3-C8',2,'ox','auto','연호의 말처럼 출처가 적혀 있으면 그건 다 맞는 말이에요.',ARRAY['K3-2-u3-X12']::text[],false,'{"seq":9,"concept":"K3-2-u3-C8","difficulty":2,"kind":"ox","stem":"연호의 말처럼 출처가 적혀 있으면 그건 다 맞는 말이에요.","answer":"X","reason_options":[{"t":"이름만 적어 놓은 것일 수도 있어 어떤 곳인지 살펴봐야 하기 때문에","correct":true},{"t":"출처는 맞는 말에만 붙기 때문에","mis":"K3-2-u3-X12"}],"mis":"K3-2-u3-X12","explanation":["하경이의 말을 떠올려요.","이름만 적었을 수도 있어요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"연호","text":"출처가 적혀 있으면 그건 다 맞는 말이야."},{"who":"하경","text":"이름만 적어 놓은 걸 수도 있잖아. 어떤 곳인지 봐야지."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L03_basic#10','kor',3,2,'u3','L03','g3_2_kor_u3_L03_basic','lesson_basic','K3-2-u3-C6',3,'error','auto','「복도에서는 걸어 다녀요」의 ㉯ 그림을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X09']::text[],false,'{"seq":10,"concept":"K3-2-u3-C6","difficulty":3,"kind":"error","stem":"「복도에서는 걸어 다녀요」의 ㉯ 그림을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「㉯ 그림도 학교 누리집에서 가져온 거야.」","correct":true,"mis_target":"K3-2-u3-X09"},{"t":"친구 나 — 「㉯ 그림 아래에는 아무 글도 없어.」","mis":"K3-2-u3-X09"},{"t":"친구 다 — 「그래서 ㉯는 어디에서 왔는지 알 수 없어.」","mis":"K3-2-u3-X09"}],"explanation":["㉯ 바로 아래를 봐요.","아무 출처도 없어요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["복도는 여러 반이 함께 쓰는 곳이고, 모퉁이에서는 앞이 잘 보이지 않습니다.","㉮ 어떤 형에게 들으니 복도에서 부딪치는 일이 많다고 합니다.","㉯ [그림] 복도에서 나란히 걸어가는 모습을 그린 그림","㉰ 보건실 안내장 「다친 곳을 줄이려면」에 따르면,","부딪쳐서 다치는 일은 걸을 때보다 뛸 때 더 자주 생긴다고 합니다.","㉱ [그림] 오른쪽으로 걸어가는 방향을 나타낸 그림","■ 출처: 「복도 통행 안내」, 학교 누리집.","우리 모두 복도에서는 걸어 다니기로 해요."],"title":"주장하는 글 「복도에서는 걸어 다녀요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L03_challenge#1','kor',3,2,'u3','L03','g3_2_kor_u3_L03_challenge','lesson_challenge','K3-2-u3-C6',2,'sa','auto','「복도에서는 걸어 다녀요」의 자료 넷 가운데 출처가 적혀 있는 자료는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u3-C6","difficulty":2,"kind":"sa","stem":"「복도에서는 걸어 다녀요」의 자료 넷 가운데 출처가 적혀 있는 자료는 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["㉮~㉱를 하나씩 봐요.","㉰와 ㉱에만 가져온 곳이 있어요.","2개예요."],"asset":{"type":"passage","lines":["복도는 여러 반이 함께 쓰는 곳이고, 모퉁이에서는 앞이 잘 보이지 않습니다.","㉮ 어떤 형에게 들으니 복도에서 부딪치는 일이 많다고 합니다.","㉯ [그림] 복도에서 나란히 걸어가는 모습을 그린 그림","㉰ 보건실 안내장 「다친 곳을 줄이려면」에 따르면,","부딪쳐서 다치는 일은 걸을 때보다 뛸 때 더 자주 생긴다고 합니다.","㉱ [그림] 오른쪽으로 걸어가는 방향을 나타낸 그림","■ 출처: 「복도 통행 안내」, 학교 누리집.","우리 모두 복도에서는 걸어 다니기로 해요."],"title":"주장하는 글 「복도에서는 걸어 다녀요」"},"mis":"K3-2-u3-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L03_challenge#2','kor',3,2,'u3','L03','g3_2_kor_u3_L03_challenge','lesson_challenge','K3-2-u3-C7',2,'mc','auto','출처를 확인하며 읽으면 좋은 점 두 가지를 알맞게 짝지은 것은 무엇인가요?',ARRAY['K3-2-u3-X10','K3-2-u3-X03','K3-2-u3-X12']::text[],false,'{"seq":2,"concept":"K3-2-u3-C7","difficulty":2,"kind":"mc","stem":"출처를 확인하며 읽으면 좋은 점 두 가지를 알맞게 짝지은 것은 무엇인가요?","options":[{"t":"믿을 만한지 살펴볼 수 있다 · 더 찾아볼 곳을 알 수 있다","correct":true},{"t":"글을 빨리 읽는다 · 글이 짧아진다","mis":"K3-2-u3-X10"},{"t":"누가 썼는지 안다 · 쓴 날짜를 안다","mis":"K3-2-u3-X03"},{"t":"그대로 믿으면 된다 · 의심하지 않는다","mis":"K3-2-u3-X12"}],"explanation":["출처는 다음 길을 알려 주는 표 같아요.","살펴볼 수 있어요.","더 찾아볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L03_challenge#3','kor',3,2,'u3','L03','g3_2_kor_u3_L03_challenge','lesson_challenge','K3-2-u3-C8',3,'mc','auto','하경이가 「이름만 적어 놓은 걸 수도 있잖아.」라고 말하며 하려는 일은 무엇인가요?',ARRAY['K3-2-u3-X13','K3-2-u3-X23','K3-2-u3-X12']::text[],false,'{"seq":3,"concept":"K3-2-u3-C8","difficulty":3,"kind":"mc","stem":"하경이가 「이름만 적어 놓은 걸 수도 있잖아.」라고 말하며 하려는 일은 무엇인가요?","options":[{"t":"출처가 어떤 곳인지 살펴보고 생각하려는 것","correct":true},{"t":"출처가 있는 자료는 모두 버리려는 것","mis":"K3-2-u3-X13"},{"t":"출처를 지우고 다시 쓰려는 것","mis":"K3-2-u3-X23"},{"t":"연호의 말을 그대로 따르려는 것","mis":"K3-2-u3-X12"}],"explanation":["하경이는 버리자고 하지 않았어요.","어떤 곳인지 보자고 했어요.","살펴보고 생각하려는 거예요."],"asset":{"type":"speech","turns":[{"who":"연호","text":"출처가 적혀 있으면 그건 다 맞는 말이야."},{"who":"하경","text":"이름만 적어 놓은 걸 수도 있잖아. 어떤 곳인지 봐야지."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L03_challenge#4','kor',3,2,'u3','L03','g3_2_kor_u3_L03_challenge','lesson_challenge','K3-2-u3-C8',3,'error','auto','「복도에서는 걸어 다녀요」의 자료를 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X13','K3-2-u3-X14','K3-2-u3-X11']::text[],false,'{"seq":4,"concept":"K3-2-u3-C8","difficulty":3,"kind":"error","stem":"「복도에서는 걸어 다녀요」의 자료를 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「출처가 있어도 다 거짓일 수 있으니 ㉰도 믿지 말자.」","correct":true,"mis_target":"K3-2-u3-X13"},{"t":"친구 가 — 「㉰는 보건실 안내장이라니 보건실에 가서 확인해 볼 수 있어.」","mis":"K3-2-u3-X14"},{"t":"친구 나 — 「㉮는 누구에게 들었는지 몰라서 살펴볼 수가 없어.」","mis":"K3-2-u3-X11"}],"explanation":["무조건 믿지도 않아요.","무조건 의심하지도 않아요.","친구 다가 알맞지 않아요."],"asset":{"type":"passage","lines":["복도는 여러 반이 함께 쓰는 곳이고, 모퉁이에서는 앞이 잘 보이지 않습니다.","㉮ 어떤 형에게 들으니 복도에서 부딪치는 일이 많다고 합니다.","㉯ [그림] 복도에서 나란히 걸어가는 모습을 그린 그림","㉰ 보건실 안내장 「다친 곳을 줄이려면」에 따르면,","부딪쳐서 다치는 일은 걸을 때보다 뛸 때 더 자주 생긴다고 합니다.","㉱ [그림] 오른쪽으로 걸어가는 방향을 나타낸 그림","■ 출처: 「복도 통행 안내」, 학교 누리집.","우리 모두 복도에서는 걸어 다니기로 해요."],"title":"주장하는 글 「복도에서는 걸어 다녀요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L03_challenge#5','kor',3,2,'u3','L03','g3_2_kor_u3_L03_challenge','lesson_challenge','K3-2-u3-C7',3,'ox','auto','출처가 없는 자료 ㉮는 더 알고 싶어도 어디로 가서 찾아봐야 할지 알 수 없어요.',ARRAY['K3-2-u3-X11']::text[],false,'{"seq":5,"concept":"K3-2-u3-C7","difficulty":3,"kind":"ox","stem":"출처가 없는 자료 ㉮는 더 알고 싶어도 어디로 가서 찾아봐야 할지 알 수 없어요.","answer":"O","reason_options":[{"t":"누구에게 들었는지 알 수 없어 찾아갈 곳이 없기 때문에","correct":true},{"t":"출처가 없으면 오히려 더 쉽게 찾아볼 수 있기 때문에","mis":"K3-2-u3-X11"}],"mis":"K3-2-u3-X11","explanation":["「어떤 형」은 누구일까요?","알 수 없어요.","그래서 O예요."],"asset":{"type":"passage","lines":["복도는 여러 반이 함께 쓰는 곳이고, 모퉁이에서는 앞이 잘 보이지 않습니다.","㉮ 어떤 형에게 들으니 복도에서 부딪치는 일이 많다고 합니다.","㉯ [그림] 복도에서 나란히 걸어가는 모습을 그린 그림","㉰ 보건실 안내장 「다친 곳을 줄이려면」에 따르면,","부딪쳐서 다치는 일은 걸을 때보다 뛸 때 더 자주 생긴다고 합니다.","㉱ [그림] 오른쪽으로 걸어가는 방향을 나타낸 그림","■ 출처: 「복도 통행 안내」, 학교 누리집.","우리 모두 복도에서는 걸어 다니기로 해요."],"title":"주장하는 글 「복도에서는 걸어 다녀요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L03_challenge#6','kor',3,2,'u3','L03','g3_2_kor_u3_L03_challenge','lesson_challenge','K3-2-u3-C6',3,'mc','auto','글쓴이가 의견을 뒷받침하려고 가져온 자료 가운데, 읽는 사람이 직접 찾아가 살펴볼 수 있는 것은 무엇인가요?',ARRAY['K3-2-u3-X09','K3-2-u3-X08']::text[],false,'{"seq":6,"concept":"K3-2-u3-C6","difficulty":3,"kind":"mc","stem":"글쓴이가 의견을 뒷받침하려고 가져온 자료 가운데, 읽는 사람이 직접 찾아가 살펴볼 수 있는 것은 무엇인가요?","options":[{"t":"㉰ 보건실 안내장 「다친 곳을 줄이려면」","correct":true},{"t":"㉮ 어떤 형에게 들은 이야기","mis":"K3-2-u3-X09"},{"t":"㉯ 나란히 걸어가는 그림","mis":"K3-2-u3-X09"},{"t":"글쓴이의 마지막 말 「걸어 다니기로 해요」","mis":"K3-2-u3-X08"}],"explanation":["찾아갈 곳이 적혀 있어야 해요.","보건실은 학교 안에 있어요.","㉰예요."],"asset":{"type":"passage","lines":["복도는 여러 반이 함께 쓰는 곳이고, 모퉁이에서는 앞이 잘 보이지 않습니다.","㉮ 어떤 형에게 들으니 복도에서 부딪치는 일이 많다고 합니다.","㉯ [그림] 복도에서 나란히 걸어가는 모습을 그린 그림","㉰ 보건실 안내장 「다친 곳을 줄이려면」에 따르면,","부딪쳐서 다치는 일은 걸을 때보다 뛸 때 더 자주 생긴다고 합니다.","㉱ [그림] 오른쪽으로 걸어가는 방향을 나타낸 그림","■ 출처: 「복도 통행 안내」, 학교 누리집.","우리 모두 복도에서는 걸어 다니기로 해요."],"title":"주장하는 글 「복도에서는 걸어 다녀요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L03_challenge#7','kor',3,2,'u3','L03','g3_2_kor_u3_L03_challenge','lesson_challenge','K3-2-u3-C7',3,'match','auto','글에 적힌 것과 그것을 보고 할 수 있는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u3-C7","difficulty":3,"kind":"match","stem":"글에 적힌 것과 그것을 보고 할 수 있는 일을 알맞게 이으세요.","pairs":[{"l":"「복도 통행 안내」, 학교 누리집","r":"누리집에 들어가 더 찾아본다"},{"l":"보건실 안내장 「다친 곳을 줄이려면」","r":"보건실에 가서 안내장을 살펴본다"},{"l":"어떤 형에게 들으니","r":"찾아갈 곳을 알 수 없다"}],"mis":"K3-2-u3-X11","explanation":["출처는 다음 길을 알려 줘요.","누리집은 들어가 보고, 안내장은 가서 봐요.","들은 이야기는 갈 곳이 없어요."],"asset":{"type":"passage","lines":["복도는 여러 반이 함께 쓰는 곳이고, 모퉁이에서는 앞이 잘 보이지 않습니다.","㉮ 어떤 형에게 들으니 복도에서 부딪치는 일이 많다고 합니다.","㉯ [그림] 복도에서 나란히 걸어가는 모습을 그린 그림","㉰ 보건실 안내장 「다친 곳을 줄이려면」에 따르면,","부딪쳐서 다치는 일은 걸을 때보다 뛸 때 더 자주 생긴다고 합니다.","㉱ [그림] 오른쪽으로 걸어가는 방향을 나타낸 그림","■ 출처: 「복도 통행 안내」, 학교 누리집.","우리 모두 복도에서는 걸어 다니기로 해요."],"title":"주장하는 글 「복도에서는 걸어 다녀요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L03_challenge#8','kor',3,2,'u3','L03','g3_2_kor_u3_L03_challenge','lesson_challenge','K3-2-u3-C8',4,'mc','auto','하경이의 생각에 맞게 ㉰를 읽은 친구는 누구인가요?',ARRAY['K3-2-u3-X12','K3-2-u3-X13','K3-2-u3-X14']::text[],false,'{"seq":8,"concept":"K3-2-u3-C8","difficulty":4,"kind":"mc","stem":"하경이의 생각에 맞게 ㉰를 읽은 친구는 누구인가요?","options":[{"t":"「보건실 안내장이라니 학교에 있는 곳이네. 보건실에 가서 살펴보고 생각해 볼래.」","correct":true},{"t":"「안내장이라고 적혀 있으니 더 볼 것 없이 맞아.」","mis":"K3-2-u3-X12"},{"t":"「안내장도 틀릴 수 있으니 ㉰는 아예 빼고 읽을래.」","mis":"K3-2-u3-X13"},{"t":"「출처 이름이 기니까 믿을 만해.」","mis":"K3-2-u3-X14"}],"explanation":["하경이는 어떤 곳인지 보자고 했어요.","보건실은 가서 볼 수 있어요.","살펴보고 생각하는 친구예요."],"asset":{"type":"passage","lines":["복도는 여러 반이 함께 쓰는 곳이고, 모퉁이에서는 앞이 잘 보이지 않습니다.","㉮ 어떤 형에게 들으니 복도에서 부딪치는 일이 많다고 합니다.","㉯ [그림] 복도에서 나란히 걸어가는 모습을 그린 그림","㉰ 보건실 안내장 「다친 곳을 줄이려면」에 따르면,","부딪쳐서 다치는 일은 걸을 때보다 뛸 때 더 자주 생긴다고 합니다.","㉱ [그림] 오른쪽으로 걸어가는 방향을 나타낸 그림","■ 출처: 「복도 통행 안내」, 학교 누리집.","우리 모두 복도에서는 걸어 다니기로 해요."],"title":"주장하는 글 「복도에서는 걸어 다녀요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L03_challenge#9','kor',3,2,'u3','L03','g3_2_kor_u3_L03_challenge','lesson_challenge','K3-2-u3-C7',4,'essay','teacher','「복도에서는 걸어 다녀요」를 읽고 새롭게 안 것과 더 알고 싶은 것을 하나씩 쓰고, 더 알고 싶은 것은 어디에서 찾아볼지 글의 출처를 들어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u3-C7","difficulty":4,"kind":"essay","stem":"「복도에서는 걸어 다녀요」를 읽고 새롭게 안 것과 더 알고 싶은 것을 하나씩 쓰고, 더 알고 싶은 것은 어디에서 찾아볼지 글의 출처를 들어 쓰세요.","answer_guide":{"answer":"예: 새롭게 안 것 — 부딪쳐 다치는 일은 뛸 때 더 자주 생긴다는 것. 더 알고 싶은 것 — 계단에서는 어떻게 다녀야 하는지. 「복도 통행 안내」의 출처가 학교 누리집이라고 적혀 있으니 학교 누리집에 들어가 찾아보겠다.","scoring_points":["새롭게 안 것을 글에서 찾아 썼는가","더 알고 싶은 것을 썼는가","글의 출처를 들어 찾아볼 곳을 썼는가"]},"explanation":["글에 쓰인 내용에서 찾아요.","궁금한 것을 하나 정해요.","출처가 찾아갈 곳을 알려 줘요."],"asset":{"type":"passage","lines":["복도는 여러 반이 함께 쓰는 곳이고, 모퉁이에서는 앞이 잘 보이지 않습니다.","㉮ 어떤 형에게 들으니 복도에서 부딪치는 일이 많다고 합니다.","㉯ [그림] 복도에서 나란히 걸어가는 모습을 그린 그림","㉰ 보건실 안내장 「다친 곳을 줄이려면」에 따르면,","부딪쳐서 다치는 일은 걸을 때보다 뛸 때 더 자주 생긴다고 합니다.","㉱ [그림] 오른쪽으로 걸어가는 방향을 나타낸 그림","■ 출처: 「복도 통행 안내」, 학교 누리집.","우리 모두 복도에서는 걸어 다니기로 해요."],"title":"주장하는 글 「복도에서는 걸어 다녀요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L03_challenge#10','kor',3,2,'u3','L03','g3_2_kor_u3_L03_challenge','lesson_challenge','K3-2-u3-C8',4,'essay','teacher','연호와 하경이의 말 가운데 어느 쪽에 더 가까운지 쓰고, 출처가 적힌 자료를 어떻게 읽어야 하는지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u3-C8","difficulty":4,"kind":"essay","stem":"연호와 하경이의 말 가운데 어느 쪽에 더 가까운지 쓰고, 출처가 적힌 자료를 어떻게 읽어야 하는지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 하경이 말에 더 가깝다. 출처가 적혀 있다고 다 맞는 것은 아니고, 이름만 적어 놓았을 수도 있다. 그렇다고 다 틀린 것도 아니니 어떤 곳에서 가져왔는지 살펴보고 생각하며 읽어야 한다.","scoring_points":["출처가 있다고 다 맞는 것은 아니라고 썼는가","다 틀린 것도 아니라고 썼는가","어떤 곳인지 살펴보고 생각한다고 썼는가"]},"explanation":["두 친구의 말을 견주어요.","함부로 믿지 않아요.","무조건 의심하지도 않아요."],"asset":{"type":"speech","turns":[{"who":"연호","text":"출처가 적혀 있으면 그건 다 맞는 말이야."},{"who":"하경","text":"이름만 적어 놓은 걸 수도 있잖아. 어떤 곳인지 봐야지."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L05_basic#1','kor',3,2,'u3','L05','g3_2_kor_u3_L05_basic','lesson_basic','K3-2-u3-C9',1,'mc','auto','「우리 학교 텃밭」은 무엇을 설명하는 글인가요?',ARRAY['K3-2-u3-X08']::text[],false,'{"seq":1,"concept":"K3-2-u3-C9","difficulty":1,"kind":"mc","stem":"「우리 학교 텃밭」은 무엇을 설명하는 글인가요?","options":[{"t":"학교 텃밭을 가꾸는 일","correct":true},{"t":"운동장에서 하는 놀이","mis":"K3-2-u3-X08"},{"t":"급식실에서 지킬 것","mis":"K3-2-u3-X08"},{"t":"상추로 요리하는 방법","mis":"K3-2-u3-X08"}],"explanation":["제목과 첫 줄을 봐요.","텃밭에서 무엇을 어떻게 가꾸는지예요.","텃밭 가꾸기를 설명해요."],"asset":{"type":"passage","lines":["우리 학교 운동장 옆에는 작은 텃밭이 있습니다.","이 텃밭에서 무엇을 어떻게 가꾸는지 알아봅시다.","텃밭 앞에 서 있는 「텃밭 안내판」을 보면","어느 칸에 무엇을 심었는지 알 수 있습니다.","봄에는 상추와 방울토마토를 심었습니다.","씨를 뿌린 뒤에는 싹이 납니다.","싹이 나면 잎이 넓어지고 줄기가 길어집니다."],"title":"설명하는 글 「우리 학교 텃밭」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L05_basic#2','kor',3,2,'u3','L05','g3_2_kor_u3_L05_basic','lesson_basic','K3-2-u3-C9',1,'mc','auto','상추 잎을 다 뜯지 않고 몇 장 남겨 두면 어떻게 되나요?',ARRAY['K3-2-u3-X08']::text[],false,'{"seq":2,"concept":"K3-2-u3-C9","difficulty":1,"kind":"mc","stem":"상추 잎을 다 뜯지 않고 몇 장 남겨 두면 어떻게 되나요?","options":[{"t":"잎이 다시 자란다","correct":true},{"t":"더는 자라지 않는다","mis":"K3-2-u3-X08"},{"t":"바로 꽃이 핀다","mis":"K3-2-u3-X08"},{"t":"줄기가 짧아진다","mis":"K3-2-u3-X08"}],"explanation":["상추가 나오는 줄을 찾아요.","몇 장을 남겨 두라고 했어요.","잎이 다시 자라요."],"asset":{"type":"passage","lines":["교실 뒤에 붙여 둔 「물 주는 차례표」에 따르면,","우리 반은 목요일에 텃밭을 맡습니다. 흙이 말랐을 때 물을 줍니다.","[그림] 물뿌리개로 텃밭에 물을 주는 모습을 그린 그림","■ 출처: 「물 주는 차례표」, 교실 뒤 게시판.","상추는 잎을 뜯어 먹습니다. 다 뜯지 않고 몇 장을 남겨 두면 잎이 다시 자랍니다.","[그림] 상추 잎을 뜯는 손을 그린 그림","텃밭을 가꾸려면 물뿌리개와 모종삽을 마련해야 합니다.","작은 텃밭이지만 손이 가는 곳입니다."],"title":"설명하는 글 「우리 학교 텃밭」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L05_basic#3','kor',3,2,'u3','L05','g3_2_kor_u3_L05_basic','lesson_basic','K3-2-u3-C10',1,'match','auto','글에 나온 낱말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K3-2-u3-C10","difficulty":1,"kind":"match","stem":"글에 나온 낱말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"가꾸다","r":"잘 자라도록 보살피다"},{"l":"차례","r":"순서에 따라 돌아오는 것"},{"l":"마련하다","r":"필요한 것을 준비해 갖추다"}],"mis":"K3-2-u3-X15","explanation":["그 낱말이 든 문장을 떠올려요.","텃밭을 가꾸고, 물 주는 차례가 있어요.","물뿌리개를 마련해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L05_basic#4','kor',3,2,'u3','L05','g3_2_kor_u3_L05_basic','lesson_basic','K3-2-u3-C11',1,'ox','auto','출처가 알맞은지 확인하려면 적혀 있는 곳에 직접 가 보거나 누리집에 들어가 볼 수 있어요.',ARRAY['K3-2-u3-X14']::text[],false,'{"seq":4,"concept":"K3-2-u3-C11","difficulty":1,"kind":"ox","stem":"출처가 알맞은지 확인하려면 적혀 있는 곳에 직접 가 보거나 누리집에 들어가 볼 수 있어요.","answer":"O","reason_options":[{"t":"확인은 직접 가서 보는 것이기 때문에","correct":true},{"t":"출처 이름이 길면 따로 확인하지 않아도 되기 때문에","mis":"K3-2-u3-X14"}],"mis":"K3-2-u3-X14","explanation":["내가 직접 해 볼 수 있는 일이에요.","가서 보면 확인돼요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L05_basic#5','kor',3,2,'u3','L05','g3_2_kor_u3_L05_basic','lesson_basic','K3-2-u3-C9',2,'mc','auto','어느 칸에 무엇을 심었는지 알려 준 자료의 출처는 무엇인가요?',ARRAY['K3-2-u3-X09','K3-2-u3-X03']::text[],false,'{"seq":5,"concept":"K3-2-u3-C9","difficulty":2,"kind":"mc","stem":"어느 칸에 무엇을 심었는지 알려 준 자료의 출처는 무엇인가요?","options":[{"t":"「텃밭 안내판」","correct":true},{"t":"「물 주는 차례표」","mis":"K3-2-u3-X09"},{"t":"학교 누리집","mis":"K3-2-u3-X09"},{"t":"글쓴이 이름","mis":"K3-2-u3-X03"}],"explanation":["그 내용이 나온 줄을 찾아요.","「텃밭 안내판」을 보면 안다고 했어요.","그것이 출처예요."],"asset":{"type":"passage","lines":["우리 학교 운동장 옆에는 작은 텃밭이 있습니다.","이 텃밭에서 무엇을 어떻게 가꾸는지 알아봅시다.","텃밭 앞에 서 있는 「텃밭 안내판」을 보면","어느 칸에 무엇을 심었는지 알 수 있습니다.","봄에는 상추와 방울토마토를 심었습니다.","씨를 뿌린 뒤에는 싹이 납니다.","싹이 나면 잎이 넓어지고 줄기가 길어집니다."],"title":"설명하는 글 「우리 학교 텃밭」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L05_basic#6','kor',3,2,'u3','L05','g3_2_kor_u3_L05_basic','lesson_basic','K3-2-u3-C9',2,'mc','auto','우리 반이 텃밭을 맡는 날을 알려 준 자료의 출처는 무엇인가요?',ARRAY['K3-2-u3-X09']::text[],false,'{"seq":6,"concept":"K3-2-u3-C9","difficulty":2,"kind":"mc","stem":"우리 반이 텃밭을 맡는 날을 알려 준 자료의 출처는 무엇인가요?","options":[{"t":"「물 주는 차례표」, 교실 뒤 게시판","correct":true},{"t":"「텃밭 안내판」, 텃밭 앞","mis":"K3-2-u3-X09"},{"t":"보건실 안내장","mis":"K3-2-u3-X09"},{"t":"적혀 있지 않음","mis":"K3-2-u3-X09"}],"explanation":["「…에 따르면」을 찾아요.","첫 줄에 차례표가 나와요.","교실 뒤 게시판에 있어요."],"asset":{"type":"passage","lines":["교실 뒤에 붙여 둔 「물 주는 차례표」에 따르면,","우리 반은 목요일에 텃밭을 맡습니다. 흙이 말랐을 때 물을 줍니다.","[그림] 물뿌리개로 텃밭에 물을 주는 모습을 그린 그림","■ 출처: 「물 주는 차례표」, 교실 뒤 게시판.","상추는 잎을 뜯어 먹습니다. 다 뜯지 않고 몇 장을 남겨 두면 잎이 다시 자랍니다.","[그림] 상추 잎을 뜯는 손을 그린 그림","텃밭을 가꾸려면 물뿌리개와 모종삽을 마련해야 합니다.","작은 텃밭이지만 손이 가는 곳입니다."],"title":"설명하는 글 「우리 학교 텃밭」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L05_basic#7','kor',3,2,'u3','L05','g3_2_kor_u3_L05_basic','lesson_basic','K3-2-u3-C10',2,'mc','auto','「텃밭을 가꾸려면 물뿌리개와 모종삽을 마련해야 합니다.」에서 「마련해야」 자리에 넣어도 뜻이 통하는 말은 무엇인가요?',ARRAY['K3-2-u3-X15']::text[],false,'{"seq":7,"concept":"K3-2-u3-C10","difficulty":2,"kind":"mc","stem":"「텃밭을 가꾸려면 물뿌리개와 모종삽을 마련해야 합니다.」에서 「마련해야」 자리에 넣어도 뜻이 통하는 말은 무엇인가요?","options":[{"t":"준비해야","correct":true},{"t":"보살펴야","mis":"K3-2-u3-X15"},{"t":"돌아와야","mis":"K3-2-u3-X15"},{"t":"버려야","mis":"K3-2-u3-X15"}],"explanation":["바꾸어 넣어 읽어 봐요.","물뿌리개를 갖추어야 해요.","준비해야가 통해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L05_basic#8','kor',3,2,'u3','L05','g3_2_kor_u3_L05_basic','lesson_basic','K3-2-u3-C11',2,'mc','auto','「텃밭 안내판」이 알맞은 출처인지 확인하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X14','K3-2-u3-X12']::text[],false,'{"seq":8,"concept":"K3-2-u3-C11","difficulty":2,"kind":"mc","stem":"「텃밭 안내판」이 알맞은 출처인지 확인하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"텃밭 앞에 가서 안내판을 직접 본다","correct":true},{"t":"안내판 이름이 기니까 믿는다","mis":"K3-2-u3-X14"},{"t":"글씨가 크게 적혀 있으니 믿는다","mis":"K3-2-u3-X14"},{"t":"출처가 있으니 확인하지 않는다","mis":"K3-2-u3-X12"}],"explanation":["확인은 가서 보는 거예요.","텃밭은 학교 안에 있어요.","직접 가서 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L05_basic#9','kor',3,2,'u3','L05','g3_2_kor_u3_L05_basic','lesson_basic','K3-2-u3-C9',2,'ox','auto','「상추 잎을 뜯는 손을 그린 그림」에는 출처가 적혀 있어요.',ARRAY['K3-2-u3-X09']::text[],false,'{"seq":9,"concept":"K3-2-u3-C9","difficulty":2,"kind":"ox","stem":"「상추 잎을 뜯는 손을 그린 그림」에는 출처가 적혀 있어요.","answer":"X","reason_options":[{"t":"그림 아래에 가져온 곳이 적혀 있지 않기 때문에","correct":true},{"t":"그림은 언제나 출처가 있는 자료이기 때문에","mis":"K3-2-u3-X09"}],"mis":"K3-2-u3-X09","explanation":["그림 바로 아래를 봐요.","「■ 출처」가 없어요.","그래서 X예요."],"asset":{"type":"passage","lines":["교실 뒤에 붙여 둔 「물 주는 차례표」에 따르면,","우리 반은 목요일에 텃밭을 맡습니다. 흙이 말랐을 때 물을 줍니다.","[그림] 물뿌리개로 텃밭에 물을 주는 모습을 그린 그림","■ 출처: 「물 주는 차례표」, 교실 뒤 게시판.","상추는 잎을 뜯어 먹습니다. 다 뜯지 않고 몇 장을 남겨 두면 잎이 다시 자랍니다.","[그림] 상추 잎을 뜯는 손을 그린 그림","텃밭을 가꾸려면 물뿌리개와 모종삽을 마련해야 합니다.","작은 텃밭이지만 손이 가는 곳입니다."],"title":"설명하는 글 「우리 학교 텃밭」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L05_basic#10','kor',3,2,'u3','L05','g3_2_kor_u3_L05_basic','lesson_basic','K3-2-u3-C11',3,'error','auto','출처가 알맞은지 확인하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X14']::text[],false,'{"seq":10,"concept":"K3-2-u3-C11","difficulty":3,"kind":"error","stem":"출처가 알맞은지 확인하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「「물 주는 차례표」라는 이름이 그럴듯하니 확인 안 해도 돼.」","correct":true,"mis_target":"K3-2-u3-X14"},{"t":"친구 가 — 「교실 뒤 게시판에 가서 차례표를 직접 볼래.」","mis":"K3-2-u3-X14"},{"t":"친구 나 — 「텃밭 안내판이 어떤 곳에 있는지 알아볼래.」","mis":"K3-2-u3-X14"}],"explanation":["그럴듯한 이름은 확인이 아니에요.","가서 보거나 알아봐요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L05_challenge#1','kor',3,2,'u3','L05','g3_2_kor_u3_L05_challenge','lesson_challenge','K3-2-u3-C10',2,'sa','auto','「잘 자라도록 보살피다」라는 뜻의 낱말을 「우리 학교 텃밭」에서 찾아 「-다」로 끝나게 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u3-C10","difficulty":2,"kind":"sa","stem":"「잘 자라도록 보살피다」라는 뜻의 낱말을 「우리 학교 텃밭」에서 찾아 「-다」로 끝나게 쓰세요.","answer":["가꾸다"],"explanation":["둘째 줄을 봐요.","「어떻게 가꾸는지」가 나와요.","가꾸다예요."],"asset":{"type":"passage","lines":["우리 학교 운동장 옆에는 작은 텃밭이 있습니다.","이 텃밭에서 무엇을 어떻게 가꾸는지 알아봅시다.","텃밭 앞에 서 있는 「텃밭 안내판」을 보면","어느 칸에 무엇을 심었는지 알 수 있습니다.","봄에는 상추와 방울토마토를 심었습니다.","씨를 뿌린 뒤에는 싹이 납니다.","싹이 나면 잎이 넓어지고 줄기가 길어집니다."],"title":"설명하는 글 「우리 학교 텃밭」 ①"},"mis":"K3-2-u3-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L05_challenge#2','kor',3,2,'u3','L05','g3_2_kor_u3_L05_challenge','lesson_challenge','K3-2-u3-C9',2,'mc','auto','「우리 학교 텃밭」에서 싹이 나면 어떻게 된다고 했나요?',ARRAY['K3-2-u3-X08']::text[],false,'{"seq":2,"concept":"K3-2-u3-C9","difficulty":2,"kind":"mc","stem":"「우리 학교 텃밭」에서 싹이 나면 어떻게 된다고 했나요?","options":[{"t":"잎이 넓어지고 줄기가 길어진다","correct":true},{"t":"바로 상추를 뜯어 먹는다","mis":"K3-2-u3-X08"},{"t":"흙이 말라 버린다","mis":"K3-2-u3-X08"},{"t":"방울토마토가 열린다","mis":"K3-2-u3-X08"}],"explanation":["마지막 줄을 봐요.","잎과 줄기가 나와요.","넓어지고 길어져요."],"asset":{"type":"passage","lines":["우리 학교 운동장 옆에는 작은 텃밭이 있습니다.","이 텃밭에서 무엇을 어떻게 가꾸는지 알아봅시다.","텃밭 앞에 서 있는 「텃밭 안내판」을 보면","어느 칸에 무엇을 심었는지 알 수 있습니다.","봄에는 상추와 방울토마토를 심었습니다.","씨를 뿌린 뒤에는 싹이 납니다.","싹이 나면 잎이 넓어지고 줄기가 길어집니다."],"title":"설명하는 글 「우리 학교 텃밭」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L05_challenge#3','kor',3,2,'u3','L05','g3_2_kor_u3_L05_challenge','lesson_challenge','K3-2-u3-C9',3,'mc','auto','「물 주는 차례표」는 이 글에서 출처를 두 번 밝혔어요. 밝힌 두 곳을 바르게 고른 것은 무엇인가요?',ARRAY['K3-2-u3-X04','K3-2-u3-X03','K3-2-u3-X09']::text[],false,'{"seq":3,"concept":"K3-2-u3-C9","difficulty":3,"kind":"mc","stem":"「물 주는 차례표」는 이 글에서 출처를 두 번 밝혔어요. 밝힌 두 곳을 바르게 고른 것은 무엇인가요?","options":[{"t":"글 속 문장 「…에 따르면」 · 그림 아래 「■ 출처」","correct":true},{"t":"글 제목 · 맨 끝 문장","mis":"K3-2-u3-X04"},{"t":"글쓴이 이름 · 쓴 날짜","mis":"K3-2-u3-X03"},{"t":"상추 그림 아래 · 모종삽 문장","mis":"K3-2-u3-X09"}],"explanation":["표시가 없어도 스스로 찾아요.","첫 줄 문장 안에 있어요.","물 주는 그림 아래에도 있어요."],"asset":{"type":"passage","lines":["교실 뒤에 붙여 둔 「물 주는 차례표」에 따르면,","우리 반은 목요일에 텃밭을 맡습니다. 흙이 말랐을 때 물을 줍니다.","[그림] 물뿌리개로 텃밭에 물을 주는 모습을 그린 그림","■ 출처: 「물 주는 차례표」, 교실 뒤 게시판.","상추는 잎을 뜯어 먹습니다. 다 뜯지 않고 몇 장을 남겨 두면 잎이 다시 자랍니다.","[그림] 상추 잎을 뜯는 손을 그린 그림","텃밭을 가꾸려면 물뿌리개와 모종삽을 마련해야 합니다.","작은 텃밭이지만 손이 가는 곳입니다."],"title":"설명하는 글 「우리 학교 텃밭」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L05_challenge#4','kor',3,2,'u3','L05','g3_2_kor_u3_L05_challenge','lesson_challenge','K3-2-u3-C11',3,'mc','auto','출처가 알맞은지 확인하는 방법 두 가지를 알맞게 짝지은 것은 무엇인가요?',ARRAY['K3-2-u3-X14','K3-2-u3-X06','K3-2-u3-X12']::text[],false,'{"seq":4,"concept":"K3-2-u3-C11","difficulty":3,"kind":"mc","stem":"출처가 알맞은지 확인하는 방법 두 가지를 알맞게 짝지은 것은 무엇인가요?","options":[{"t":"학교 누리집에 들어가 본다 · 그곳이 어떤 곳인지 알아본다","correct":true},{"t":"이름이 긴지 본다 · 글씨가 큰지 본다","mis":"K3-2-u3-X14"},{"t":"출처를 지운다 · 내 이름을 쓴다","mis":"K3-2-u3-X06"},{"t":"있으면 믿는다 · 없으면 버린다","mis":"K3-2-u3-X12"}],"explanation":["내가 직접 해 볼 일이에요.","들어가 보거나 알아봐요.","이름 길이는 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L05_challenge#5','kor',3,2,'u3','L05','g3_2_kor_u3_L05_challenge','lesson_challenge','K3-2-u3-C8',3,'mc','auto','「우리 학교 텃밭」에 쓰인 자료를 대하는 알맞은 태도는 무엇인가요?',ARRAY['K3-2-u3-X12','K3-2-u3-X13','K3-2-u3-X09']::text[],false,'{"seq":5,"concept":"K3-2-u3-C8","difficulty":3,"kind":"mc","stem":"「우리 학교 텃밭」에 쓰인 자료를 대하는 알맞은 태도는 무엇인가요?","options":[{"t":"어디에서 온 자료인지 살펴보며 읽는다","correct":true},{"t":"글에 있는 자료는 다 맞는 말이다","mis":"K3-2-u3-X12"},{"t":"글에 있는 자료는 믿지 않는다","mis":"K3-2-u3-X13"},{"t":"출처가 없는 그림이 가장 믿을 만하다","mis":"K3-2-u3-X09"}],"explanation":["3~4차시의 연호와 하경이를 떠올려요.","함부로 믿지도 의심하지도 않아요.","살펴보며 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L05_challenge#6','kor',3,2,'u3','L05','g3_2_kor_u3_L05_challenge','lesson_challenge','K3-2-u3-C9',3,'match','auto','「우리 학교 텃밭」에서 가져온 자료와 그 출처를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K3-2-u3-C9","difficulty":3,"kind":"match","stem":"「우리 학교 텃밭」에서 가져온 자료와 그 출처를 알맞게 이으세요.","pairs":[{"l":"어느 칸에 무엇을 심었는지","r":"「텃밭 안내판」, 텃밭 앞"},{"l":"우리 반이 텃밭을 맡는 날","r":"「물 주는 차례표」, 교실 뒤 게시판"},{"l":"상추 잎을 뜯는 그림","r":"적혀 있지 않음"}],"mis":"K3-2-u3-X09","explanation":["자료가 나온 줄을 찾아요.","안내판과 차례표가 있어요.","그림 하나는 출처가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L05_challenge#7','kor',3,2,'u3','L05','g3_2_kor_u3_L05_challenge','lesson_challenge','K3-2-u3-C10',3,'error','auto','글에 나온 낱말의 뜻을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X15']::text[],false,'{"seq":7,"concept":"K3-2-u3-C10","difficulty":3,"kind":"error","stem":"글에 나온 낱말의 뜻을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「「물 주는 차례표」의 「차례」는 필요한 것을 준비한다는 뜻이야.」","correct":true,"mis_target":"K3-2-u3-X15"},{"t":"친구 가 — 「「가꾸다」는 잘 자라도록 보살핀다는 뜻이야.」","mis":"K3-2-u3-X15"},{"t":"친구 다 — 「「마련하다」는 필요한 것을 갖춘다는 뜻이야.」","mis":"K3-2-u3-X15"}],"explanation":["차례는 순서에 따라 돌아오는 것이에요.","준비하는 것은 마련하다예요.","친구 나가 섞었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L05_challenge#8','kor',3,2,'u3','L05','g3_2_kor_u3_L05_challenge','lesson_challenge','K3-2-u3-C11',4,'mc','auto','친구가 「「텃밭 안내판」에 상추는 겨울에 심는다고 적혀 있대.」라고 했어요. 이 말을 확인하는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X12','K3-2-u3-X13','K3-2-u3-X14']::text[],false,'{"seq":8,"concept":"K3-2-u3-C11","difficulty":4,"kind":"mc","stem":"친구가 「「텃밭 안내판」에 상추는 겨울에 심는다고 적혀 있대.」라고 했어요. 이 말을 확인하는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"텃밭 앞에 가서 안내판에 정말 그렇게 적혀 있는지 직접 본다","correct":true},{"t":"안내판이라고 했으니 그대로 믿는다","mis":"K3-2-u3-X12"},{"t":"친구가 말했으니 무조건 틀렸다고 여긴다","mis":"K3-2-u3-X13"},{"t":"「텃밭 안내판」이라는 이름이 그럴듯하니 믿는다","mis":"K3-2-u3-X14"}],"explanation":["출처가 말해졌어요.","그 출처는 학교 안에 있어요.","가서 직접 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L05_challenge#9','kor',3,2,'u3','L05','g3_2_kor_u3_L05_challenge','lesson_challenge','K3-2-u3-C9',4,'essay','teacher','「우리 학교 텃밭」에서 가져온 자료 셋을 찾아 출처를 쓰고(없으면 없다고 쓰기), 출처가 없는 자료는 무엇이 아쉬운지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u3-C9","difficulty":4,"kind":"essay","stem":"「우리 학교 텃밭」에서 가져온 자료 셋을 찾아 출처를 쓰고(없으면 없다고 쓰기), 출처가 없는 자료는 무엇이 아쉬운지 쓰세요.","answer_guide":{"answer":"예: 어느 칸에 무엇을 심었는지 — 「텃밭 안내판」, 텃밭 앞. 우리 반이 맡는 날 — 「물 주는 차례표」, 교실 뒤 게시판. 상추 잎을 뜯는 그림 — 출처가 적혀 있지 않다. 출처가 없는 그림은 어디에서 가져왔는지 알 수 없어 더 알고 싶어도 찾아볼 곳이 없다.","scoring_points":["자료 셋과 출처를 바르게 짝지었는가","출처가 없는 자료를 가려냈는가","출처가 없을 때의 아쉬움을 썼는가"]},"explanation":["표시가 없어도 스스로 찾아요.","「…에 따르면」과 「■ 출처」를 봐요.","없는 자료의 아쉬움도 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L05_challenge#10','kor',3,2,'u3','L05','g3_2_kor_u3_L05_challenge','lesson_challenge','K3-2-u3-C10',4,'essay','teacher','「가꾸다」와 「마련하다」 가운데 하나를 골라 글에서 쓰인 뜻을 쓰고, 그 낱말을 넣어 학교생활 문장을 하나 만드세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u3-C10","difficulty":4,"kind":"essay","stem":"「가꾸다」와 「마련하다」 가운데 하나를 골라 글에서 쓰인 뜻을 쓰고, 그 낱말을 넣어 학교생활 문장을 하나 만드세요.","answer_guide":{"answer":"예: 마련하다 — 필요한 것을 준비해 갖춘다는 뜻이다. 문장: 미술 시간 전에 색연필과 도화지를 마련해 두었다.","scoring_points":["낱말 하나를 골랐는가","글에서 쓰인 뜻을 바르게 썼는가","그 뜻에 맞는 학교생활 문장을 만들었는가"]},"explanation":["낱말이 든 문장을 다시 읽어요.","뜻을 짐작해 써요.","내 문장에 넣어 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L07_basic#1','kor',3,2,'u3','L07','g3_2_kor_u3_L07_basic','lesson_basic','K3-2-u3-C12',1,'mc','auto','「비 오는 날 체육 시간」에서 앞 문장과 뒤 문장을 이어 주는 말은 무엇인가요?',ARRAY['K3-2-u3-X17']::text[],false,'{"seq":1,"concept":"K3-2-u3-C12","difficulty":1,"kind":"mc","stem":"「비 오는 날 체육 시간」에서 앞 문장과 뒤 문장을 이어 주는 말은 무엇인가요?","options":[{"t":"그러나","correct":true},{"t":"목요일","mis":"K3-2-u3-X17"},{"t":"체육관에서","mis":"K3-2-u3-X17"},{"t":"이어달리기","mis":"K3-2-u3-X17"}],"explanation":["문장 맨 앞에 놓인 말을 찾아요.","앞 내용과 이어 주는 말이에요.","그러나가 이어 줘요."],"asset":{"type":"passage","lines":["목요일 아침이었습니다. 채호는 체육 시간을 손꼽아 기다렸습니다.","오늘은 이어달리기를 하기로 한 날이었습니다.","그러나 아침부터 비가 내렸습니다. 운동장에는 물웅덩이가 생겼습니다.","그래서 우리 반은 체육관에서 수업을 하기로 했습니다.","채호는 조금 서운했습니다.","선생님께서는 체육관에서 할 수 있는 놀이를 알려 주셨습니다.","그리고 차례를 정하는 방법도 알려 주셨습니다.","채호는 놀이를 하면서 크게 웃었습니다. 비 오는 날에도 즐거울 수 있었습니다."],"title":"이야기 「비 오는 날 체육 시간」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L07_basic#2','kor',3,2,'u3','L07','g3_2_kor_u3_L07_basic','lesson_basic','K3-2-u3-C12',1,'mc','auto','「비 오는 날 체육 시간」에서 「그러나」의 앞과 뒤는 어떤 관계인가요?',ARRAY['K3-2-u3-X16','K3-2-u3-X19']::text[],false,'{"seq":2,"concept":"K3-2-u3-C12","difficulty":1,"kind":"mc","stem":"「비 오는 날 체육 시간」에서 「그러나」의 앞과 뒤는 어떤 관계인가요?","options":[{"t":"앞과 반대되는 내용이 이어진다","correct":true},{"t":"앞과 비슷한 내용이 이어진다","mis":"K3-2-u3-X16"},{"t":"앞이 뒤의 까닭이 된다","mis":"K3-2-u3-X16"},{"t":"앞과 뒤는 아무 관계가 없다","mis":"K3-2-u3-X19"}],"explanation":["채호가 바라던 일을 봐요.","실제로는 비가 내렸어요.","반대되는 일이 이어졌어요."],"asset":{"type":"passage","lines":["목요일 아침이었습니다. 채호는 체육 시간을 손꼽아 기다렸습니다.","오늘은 이어달리기를 하기로 한 날이었습니다.","그러나 아침부터 비가 내렸습니다. 운동장에는 물웅덩이가 생겼습니다.","그래서 우리 반은 체육관에서 수업을 하기로 했습니다.","채호는 조금 서운했습니다.","선생님께서는 체육관에서 할 수 있는 놀이를 알려 주셨습니다.","그리고 차례를 정하는 방법도 알려 주셨습니다.","채호는 놀이를 하면서 크게 웃었습니다. 비 오는 날에도 즐거울 수 있었습니다."],"title":"이야기 「비 오는 날 체육 시간」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L07_basic#3','kor',3,2,'u3','L07','g3_2_kor_u3_L07_basic','lesson_basic','K3-2-u3-C12',1,'blank','auto','「아침부터 비가 내렸습니다. (　　　) 다안이는 우산을 챙겼습니다.」의 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u3-X16','K3-2-u3-X17']::text[],false,'{"seq":3,"concept":"K3-2-u3-C12","difficulty":1,"kind":"blank","stem":"「아침부터 비가 내렸습니다. (　　　) 다안이는 우산을 챙겼습니다.」의 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"그래서","correct":true},{"t":"그러나","mis":"K3-2-u3-X16"},{"t":"그리고","mis":"K3-2-u3-X16"},{"t":"목요일에","mis":"K3-2-u3-X17"}],"explanation":["우산을 챙긴 까닭을 찾아요.","앞 문장에 비가 있어요.","앞이 까닭이니 그래서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L07_basic#4','kor',3,2,'u3','L07','g3_2_kor_u3_L07_basic','lesson_basic','K3-2-u3-C13',1,'ox','auto','이어 주는 말은 문장마다 빠짐없이 넣을수록 좋은 글이 돼요.',ARRAY['K3-2-u3-X18']::text[],false,'{"seq":4,"concept":"K3-2-u3-C13","difficulty":1,"kind":"ox","stem":"이어 주는 말은 문장마다 빠짐없이 넣을수록 좋은 글이 돼요.","answer":"X","reason_options":[{"t":"앞뒤 뜻이 어떻게 이어지는지에 맞을 때 써야 하기 때문에","correct":true},{"t":"이어 주는 말이 많을수록 글이 길어져 좋기 때문에","mis":"K3-2-u3-X18"}],"mis":"K3-2-u3-X18","explanation":["개수가 정해 주지 않아요.","앞뒤 뜻의 관계가 정해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L07_basic#5','kor',3,2,'u3','L07','g3_2_kor_u3_L07_basic','lesson_basic','K3-2-u3-C12',2,'match','auto','이어 주는 말과 그 쓰임을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u3-C12","difficulty":2,"kind":"match","stem":"이어 주는 말과 그 쓰임을 알맞게 이으세요.","pairs":[{"l":"그리고","r":"앞과 비슷한 내용이 이어질 때"},{"l":"그러나","r":"앞과 반대되는 내용이 이어질 때"},{"l":"그래서","r":"앞의 내용이 뒤의 까닭이 될 때"}],"mis":"K3-2-u3-X16","explanation":["이야기에서 놓였던 곳을 떠올려요.","비슷함·반대·까닭이에요.","스스로 찾은 규칙이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L07_basic#6','kor',3,2,'u3','L07','g3_2_kor_u3_L07_basic','lesson_basic','K3-2-u3-C12',2,'mc','auto','「운동장에 물웅덩이가 생겼습니다. 그래서 체육관으로 갔습니다.」에서 앞 문장은 뒤 문장의 무엇인가요?',ARRAY['K3-2-u3-X16','K3-2-u3-X17']::text[],false,'{"seq":6,"concept":"K3-2-u3-C12","difficulty":2,"kind":"mc","stem":"「운동장에 물웅덩이가 생겼습니다. 그래서 체육관으로 갔습니다.」에서 앞 문장은 뒤 문장의 무엇인가요?","options":[{"t":"까닭","correct":true},{"t":"반대되는 내용","mis":"K3-2-u3-X16"},{"t":"비슷한 내용","mis":"K3-2-u3-X16"},{"t":"때를 나타내는 말","mis":"K3-2-u3-X17"}],"explanation":["왜 체육관으로 갔을까요?","물웅덩이가 생겨서예요.","앞이 까닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L07_basic#7','kor',3,2,'u3','L07','g3_2_kor_u3_L07_basic','lesson_basic','K3-2-u3-C12',2,'blank','auto','「윤하는 그림을 그리고 싶었습니다. (　　　) 도화지가 없었습니다.」의 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u3-X16','K3-2-u3-X22']::text[],false,'{"seq":7,"concept":"K3-2-u3-C12","difficulty":2,"kind":"blank","stem":"「윤하는 그림을 그리고 싶었습니다. (　　　) 도화지가 없었습니다.」의 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"그러나","correct":true},{"t":"그래서","mis":"K3-2-u3-X16"},{"t":"그리고","mis":"K3-2-u3-X16"},{"t":"끝으로","mis":"K3-2-u3-X22"}],"explanation":["그리고 싶었는데 무엇이 없었나요?","바라던 것과 반대예요.","그러나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L07_basic#8','kor',3,2,'u3','L07','g3_2_kor_u3_L07_basic','lesson_basic','K3-2-u3-C12',2,'blank','auto','「도영이는 아침을 든든히 먹었습니다. (　　　) 물도 한 컵 마셨습니다.」의 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K3-2-u3-X16','K3-2-u3-X22']::text[],false,'{"seq":8,"concept":"K3-2-u3-C12","difficulty":2,"kind":"blank","stem":"「도영이는 아침을 든든히 먹었습니다. (　　　) 물도 한 컵 마셨습니다.」의 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"그리고","correct":true},{"t":"그러나","mis":"K3-2-u3-X16"},{"t":"그래서","mis":"K3-2-u3-X16"},{"t":"먼저","mis":"K3-2-u3-X22"}],"explanation":["먹은 일에 마신 일이 더해져요.","비슷한 내용이 이어져요.","그리고예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L07_basic#9','kor',3,2,'u3','L07','g3_2_kor_u3_L07_basic','lesson_basic','K3-2-u3-C13',2,'mc','auto','연호와 하선이의 말을 듣고, 이어 주는 말을 쓰는 알맞은 방법을 고르세요.',ARRAY['K3-2-u3-X18','K3-2-u3-X19']::text[],false,'{"seq":9,"concept":"K3-2-u3-C13","difficulty":2,"kind":"mc","stem":"연호와 하선이의 말을 듣고, 이어 주는 말을 쓰는 알맞은 방법을 고르세요.","options":[{"t":"앞뒤 뜻이 어떻게 이어지는지에 맞게 쓴다","correct":true},{"t":"문장마다 빠짐없이 넣는다","mis":"K3-2-u3-X18"},{"t":"하나도 쓰지 않는다","mis":"K3-2-u3-X19"},{"t":"가장 긴 말을 골라 쓴다","mis":"K3-2-u3-X18"}],"explanation":["연호는 너무 많이 넣었어요.","하선이는 하나도 안 넣었어요.","앞뒤 뜻에 맞게 써요."],"asset":{"type":"speech","turns":[{"who":"연호","text":"나는 문장마다 앞에 이어 주는 말을 넣었어. 많이 쓸수록 좋은 거 아니야?"},{"who":"하선","text":"나는 하나도 안 썼어. 없어도 말은 되던데."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L07_basic#10','kor',3,2,'u3','L07','g3_2_kor_u3_L07_basic','lesson_basic','K3-2-u3-C12',3,'error','auto','이어 주는 말을 넣어 문장을 이었어요. 알맞지 않게 이은 친구는 누구인가요?',ARRAY['K3-2-u3-X16']::text[],false,'{"seq":10,"concept":"K3-2-u3-C12","difficulty":3,"kind":"error","stem":"이어 주는 말을 넣어 문장을 이었어요. 알맞지 않게 이은 친구는 누구인가요?","options":[{"t":"친구 다 — 「채호는 체육 시간을 기다렸습니다. 그래서 비가 내렸습니다.」","correct":true,"mis_target":"K3-2-u3-X16"},{"t":"친구 가 — 「비가 내렸습니다. 그래서 체육관으로 갔습니다.」","mis":"K3-2-u3-X16"},{"t":"친구 나 — 「놀이를 알려 주셨습니다. 그리고 차례 정하는 방법도 알려 주셨습니다.」","mis":"K3-2-u3-X16"}],"explanation":["기다린 일이 비의 까닭일까요?","아니에요, 반대되는 일이에요.","친구 다가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L07_challenge#1','kor',3,2,'u3','L07','g3_2_kor_u3_L07_challenge','lesson_challenge','K3-2-u3-C12',2,'sa','auto','「어제 늦게 잤습니다. (　　　) 오늘 아침에 늦잠을 잤습니다.」의 빈칸에 알맞은 이어 주는 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u3-C12","difficulty":2,"kind":"sa","stem":"「어제 늦게 잤습니다. (　　　) 오늘 아침에 늦잠을 잤습니다.」의 빈칸에 알맞은 이어 주는 말을 쓰세요.","answer":["그래서"],"explanation":["늦잠을 잔 까닭을 찾아요.","늦게 잔 것이에요.","그래서예요."],"mis":"K3-2-u3-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L07_challenge#2','kor',3,2,'u3','L07','g3_2_kor_u3_L07_challenge','lesson_challenge','K3-2-u3-C12',2,'mc','auto','「비 오는 날 체육 시간」에서 찾은 이어 주는 말을 모두 바르게 고른 것은 무엇인가요?',ARRAY['K3-2-u3-X17']::text[],false,'{"seq":2,"concept":"K3-2-u3-C12","difficulty":2,"kind":"mc","stem":"「비 오는 날 체육 시간」에서 찾은 이어 주는 말을 모두 바르게 고른 것은 무엇인가요?","options":[{"t":"그러나 · 그래서 · 그리고","correct":true},{"t":"목요일 · 체육관에서 · 그리고","mis":"K3-2-u3-X17"},{"t":"그러나 · 이어달리기 · 놀이","mis":"K3-2-u3-X17"},{"t":"아침 · 비 · 웃음","mis":"K3-2-u3-X17"}],"explanation":["문장 맨 앞에 놓인 말을 찾아요.","때·곳을 나타내는 말은 빼요.","셋이에요."],"asset":{"type":"passage","lines":["목요일 아침이었습니다. 채호는 체육 시간을 손꼽아 기다렸습니다.","오늘은 이어달리기를 하기로 한 날이었습니다.","그러나 아침부터 비가 내렸습니다. 운동장에는 물웅덩이가 생겼습니다.","그래서 우리 반은 체육관에서 수업을 하기로 했습니다.","채호는 조금 서운했습니다.","선생님께서는 체육관에서 할 수 있는 놀이를 알려 주셨습니다.","그리고 차례를 정하는 방법도 알려 주셨습니다.","채호는 놀이를 하면서 크게 웃었습니다. 비 오는 날에도 즐거울 수 있었습니다."],"title":"이야기 「비 오는 날 체육 시간」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L07_challenge#3','kor',3,2,'u3','L07','g3_2_kor_u3_L07_challenge','lesson_challenge','K3-2-u3-C13',3,'mc','auto','「비가 왔습니다. 우리 반은 체육관으로 갔습니다.」 두 문장이 왜 붙어 있는지 드러나게 하려면 어떻게 하면 좋을까요?',ARRAY['K3-2-u3-X19','K3-2-u3-X16']::text[],false,'{"seq":3,"concept":"K3-2-u3-C13","difficulty":3,"kind":"mc","stem":"「비가 왔습니다. 우리 반은 체육관으로 갔습니다.」 두 문장이 왜 붙어 있는지 드러나게 하려면 어떻게 하면 좋을까요?","options":[{"t":"두 문장 사이에 「그래서」를 넣는다","correct":true},{"t":"두 문장을 그대로 둔다","mis":"K3-2-u3-X19"},{"t":"두 문장 끝에 느낌표를 붙인다","mis":"K3-2-u3-X19"},{"t":"두 문장 사이에 「그러나」를 넣는다","mis":"K3-2-u3-X16"}],"explanation":["틀린 말은 아니에요.","그런데 관계가 안 보여요.","앞이 까닭이니 그래서를 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L07_challenge#4','kor',3,2,'u3','L07','g3_2_kor_u3_L07_challenge','lesson_challenge','K3-2-u3-C13',3,'error','auto','연호와 하선이의 글을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X18','K3-2-u3-X16','K3-2-u3-X19']::text[],false,'{"seq":4,"concept":"K3-2-u3-C13","difficulty":3,"kind":"error","stem":"연호와 하선이의 글을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「연호처럼 문장마다 넣어야 글이 좋아져.」","correct":true,"mis_target":"K3-2-u3-X18"},{"t":"친구 가 — 「앞뒤 뜻이 반대일 때 「그러나」를 쓰면 돼.」","mis":"K3-2-u3-X16"},{"t":"친구 다 — 「하선이 글은 두 문장이 왜 붙어 있는지 잘 안 보일 수 있어.」","mis":"K3-2-u3-X19"}],"explanation":["많이 쓴다고 좋지 않아요.","하나도 안 쓰면 관계가 숨어요.","친구 나가 잘못 말했어요."],"asset":{"type":"speech","turns":[{"who":"연호","text":"나는 문장마다 앞에 이어 주는 말을 넣었어. 많이 쓸수록 좋은 거 아니야?"},{"who":"하선","text":"나는 하나도 안 썼어. 없어도 말은 되던데."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L07_challenge#5','kor',3,2,'u3','L07','g3_2_kor_u3_L07_challenge','lesson_challenge','K3-2-u3-C12',3,'ox','auto','「텃밭에 씨를 뿌렸습니다. 그래서 며칠 동안 싹이 나지 않았습니다.」는 이어 주는 말을 알맞게 썼어요.',ARRAY['K3-2-u3-X16']::text[],false,'{"seq":5,"concept":"K3-2-u3-C12","difficulty":3,"kind":"ox","stem":"「텃밭에 씨를 뿌렸습니다. 그래서 며칠 동안 싹이 나지 않았습니다.」는 이어 주는 말을 알맞게 썼어요.","answer":"X","reason_options":[{"t":"씨를 뿌린 것과 싹이 나지 않은 것은 반대되는 내용이라 「그러나」가 알맞기 때문에","correct":true},{"t":"앞 문장이 있으면 언제나 「그래서」를 쓰기 때문에","mis":"K3-2-u3-X16"}],"mis":"K3-2-u3-X16","explanation":["씨를 뿌리면 싹을 바라요.","그런데 싹이 나지 않았어요.","반대라서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L07_challenge#6','kor',3,2,'u3','L07','g3_2_kor_u3_L07_challenge','lesson_challenge','K3-2-u3-C12',3,'mc','auto','「비 오는 날 체육 시간」을 이어 주는 말로 바르게 간추린 것은 무엇인가요?',ARRAY['K3-2-u3-X16','K3-2-u3-X08']::text[],false,'{"seq":6,"concept":"K3-2-u3-C12","difficulty":3,"kind":"mc","stem":"「비 오는 날 체육 시간」을 이어 주는 말로 바르게 간추린 것은 무엇인가요?","options":[{"t":"이어달리기를 기다렸다 → 그러나 비가 내렸다 → 그래서 체육관에서 수업했다","correct":true},{"t":"놀이를 했다 → 그래서 비가 내렸다 → 그리고 이어달리기를 기다렸다","mis":"K3-2-u3-X16"},{"t":"체육관에서 수업했다 → 그래서 비가 내렸다 → 그러나 즐거웠다","mis":"K3-2-u3-X16"},{"t":"비가 내렸다 → 그리고 운동장에서 이어달리기를 했다","mis":"K3-2-u3-X08"}],"explanation":["일이 일어난 차례를 봐요.","기다림 → 비 → 체육관이에요.","이어 주는 말이 관계를 보여 줘요."],"asset":{"type":"passage","lines":["목요일 아침이었습니다. 채호는 체육 시간을 손꼽아 기다렸습니다.","오늘은 이어달리기를 하기로 한 날이었습니다.","그러나 아침부터 비가 내렸습니다. 운동장에는 물웅덩이가 생겼습니다.","그래서 우리 반은 체육관에서 수업을 하기로 했습니다.","채호는 조금 서운했습니다.","선생님께서는 체육관에서 할 수 있는 놀이를 알려 주셨습니다.","그리고 차례를 정하는 방법도 알려 주셨습니다.","채호는 놀이를 하면서 크게 웃었습니다. 비 오는 날에도 즐거울 수 있었습니다."],"title":"이야기 「비 오는 날 체육 시간」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L07_challenge#7','kor',3,2,'u3','L07','g3_2_kor_u3_L07_challenge','lesson_challenge','K3-2-u3-C12',3,'match','auto','앞 문장과 이어질 뒤 문장을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u3-C12","difficulty":3,"kind":"match","stem":"앞 문장과 이어질 뒤 문장을 알맞게 이으세요.","pairs":[{"l":"도서관에 새 책이 들어왔습니다.","r":"그러나 아직 빌릴 수 없었습니다."},{"l":"색연필이 다 닳았습니다.","r":"그래서 새 색연필을 꺼냈습니다."},{"l":"교실 바닥을 쓸었습니다.","r":"그리고 책상도 닦았습니다."}],"mis":"K3-2-u3-X16","explanation":["앞과 뒤의 관계를 따져요.","반대·까닭·더하기예요.","이어 주는 말이 관계를 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L07_challenge#8','kor',3,2,'u3','L07','g3_2_kor_u3_L07_challenge','lesson_challenge','K3-2-u3-C13',4,'mc','auto','연호가 쓴 글 「비가 왔습니다. 그래서 우산을 썼습니다. 그래서 신발이 젖지 않았습니다. 그래서 기분이 좋았습니다.」를 읽고 해 줄 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X18','K3-2-u3-X19','K3-2-u3-X16']::text[],false,'{"seq":8,"concept":"K3-2-u3-C13","difficulty":4,"kind":"mc","stem":"연호가 쓴 글 「비가 왔습니다. 그래서 우산을 썼습니다. 그래서 신발이 젖지 않았습니다. 그래서 기분이 좋았습니다.」를 읽고 해 줄 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“앞뒤 뜻은 맞지만 문장마다 넣을 필요는 없어. 꼭 필요한 곳에만 남기면 더 읽기 좋아.”","correct":true},{"t":"“이어 주는 말을 더 많이 넣으면 더 좋아질 거야.”","mis":"K3-2-u3-X18"},{"t":"“이어 주는 말을 모두 빼야 좋은 글이야.”","mis":"K3-2-u3-X19"},{"t":"“「그래서」를 모두 「그러나」로 바꿔야 해.”","mis":"K3-2-u3-X16"}],"explanation":["뜻은 틀리지 않았어요.","그런데 문장마다 들어 있어요.","필요한 곳에만 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L07_challenge#9','kor',3,2,'u3','L07','g3_2_kor_u3_L07_challenge','lesson_challenge','K3-2-u3-C12',4,'essay','teacher','「그리고」·「그러나」·「그래서」를 하나씩 넣어 학교생활 문장 짝을 세 개 만들고, 각각 앞뒤가 어떤 관계인지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u3-C12","difficulty":4,"kind":"essay","stem":"「그리고」·「그러나」·「그래서」를 하나씩 넣어 학교생활 문장 짝을 세 개 만들고, 각각 앞뒤가 어떤 관계인지 쓰세요.","answer_guide":{"answer":"예: 교실을 쓸었습니다. 그리고 창문도 닦았습니다. — 비슷한 내용이 이어진다. 공을 차고 싶었습니다. 그러나 공에 바람이 빠져 있었습니다. — 반대되는 내용이 이어진다. 아침에 일찍 일어났습니다. 그래서 학교에 일찍 도착했습니다. — 앞이 뒤의 까닭이 된다.","scoring_points":["세 말을 하나씩 넣어 문장 짝을 만들었는가","앞뒤 관계에 맞는 말을 골랐는가","관계(비슷함·반대·까닭)를 썼는가"]},"explanation":["학교에서 있었던 일을 떠올려요.","관계에 맞는 말을 골라요.","관계를 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L07_challenge#10','kor',3,2,'u3','L07','g3_2_kor_u3_L07_challenge','lesson_challenge','K3-2-u3-C13',4,'essay','teacher','연호와 하선이에게 이어 주는 말을 어떻게 쓰면 좋을지 한 가지씩 말해 주는 글을 쓰고, 그렇게 말한 까닭도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u3-C13","difficulty":4,"kind":"essay","stem":"연호와 하선이에게 이어 주는 말을 어떻게 쓰면 좋을지 한 가지씩 말해 주는 글을 쓰고, 그렇게 말한 까닭도 쓰세요.","answer_guide":{"answer":"예: 연호에게 — 문장마다 넣지 말고 앞뒤 뜻이 반대이거나 까닭일 때처럼 관계를 드러내야 할 곳에만 넣어 봐. 너무 많으면 읽기 어렵기 때문이야. 하선이에게 — 두 문장이 왜 붙어 있는지 잘 안 보이는 곳에는 알맞은 이어 주는 말을 넣어 봐. 앞뒤 관계가 드러나 읽는 사람이 더 잘 알 수 있기 때문이야.","scoring_points":["연호에게 할 말을 썼는가","하선이에게 할 말을 썼는가","앞뒤 뜻의 관계로 까닭을 썼는가"]},"explanation":["두 친구는 반대쪽 끝이에요.","많아도, 없어도 아쉬워요.","앞뒤 뜻으로 까닭을 써요."],"asset":{"type":"speech","turns":[{"who":"연호","text":"나는 문장마다 앞에 이어 주는 말을 넣었어. 많이 쓸수록 좋은 거 아니야?"},{"who":"하선","text":"나는 하나도 안 썼어. 없어도 말은 되던데."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L09_basic#1','kor',3,2,'u3','L09','g3_2_kor_u3_L09_basic','lesson_basic','K3-2-u3-C14',1,'mc','auto','설명하는 글을 쓰기 전에 먼저 생각할 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X20']::text[],false,'{"seq":1,"concept":"K3-2-u3-C14","difficulty":1,"kind":"mc","stem":"설명하는 글을 쓰기 전에 먼저 생각할 것으로 알맞은 것은 무엇인가요?","options":[{"t":"이 글을 읽을 사람","correct":true},{"t":"글씨의 색깔","mis":"K3-2-u3-X20"},{"t":"글자 수를 몇 자로 할지","mis":"K3-2-u3-X20"},{"t":"제목을 꾸밀 무늬","mis":"K3-2-u3-X20"}],"explanation":["쓰기 전에 정할 것이 있어요.","누가 읽을지, 왜 쓸지예요.","꾸미기는 나중이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L09_basic#2','kor',3,2,'u3','L09','g3_2_kor_u3_L09_basic','lesson_basic','K3-2-u3-C15',1,'mc','auto','다안이가 「“과습”이 무슨 말이야?」라고 한 까닭은 무엇인가요?',ARRAY['K3-2-u3-X01','K3-2-u3-X09','K3-2-u3-X20']::text[],false,'{"seq":2,"concept":"K3-2-u3-C15","difficulty":1,"kind":"mc","stem":"다안이가 「“과습”이 무슨 말이야?」라고 한 까닭은 무엇인가요?","options":[{"t":"이해하기 어려운 낱말이 있어서","correct":true},{"t":"일의 차례가 드러나지 않아서","mis":"K3-2-u3-X01"},{"t":"가져온 자료의 출처가 없어서","mis":"K3-2-u3-X09"},{"t":"제목이 적혀 있지 않아서","mis":"K3-2-u3-X20"}],"explanation":["다안이는 낱말을 물었어요.","과습은 어려운 말이에요.","쉬운 말로 풀어야 해요."],"asset":{"type":"speech","turns":[{"who":"다안","text":"“과습”이 무슨 말이야?"},{"who":"도영","text":"뭘 먼저 해야 하는지 모르겠어."},{"who":"윤하","text":"어디에서 알아낸 건지 안 적혀 있네."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L09_basic#3','kor',3,2,'u3','L09','g3_2_kor_u3_L09_basic','lesson_basic','K3-2-u3-C16',1,'ox','auto','책이나 안내판에서 알아낸 내용을 글에 썼다면 가져온 곳을 글 끝에 밝혀요.',ARRAY['K3-2-u3-X06']::text[],false,'{"seq":3,"concept":"K3-2-u3-C16","difficulty":1,"kind":"ox","stem":"책이나 안내판에서 알아낸 내용을 글에 썼다면 가져온 곳을 글 끝에 밝혀요.","answer":"O","reason_options":[{"t":"읽는 사람이 어디에서 알아낸 내용인지 알 수 있기 때문에","correct":true},{"t":"찾아본 내용은 내가 원래 알던 것처럼 써도 되기 때문에","mis":"K3-2-u3-X06"}],"mis":"K3-2-u3-X06","explanation":["읽을 때 확인하던 출처예요.","쓸 때는 내가 적어 줘요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L09_basic#4','kor',3,2,'u3','L09','g3_2_kor_u3_L09_basic','lesson_basic','K3-2-u3-C15',1,'mc','auto','차례를 알려 주는 말끼리 묶은 것은 무엇인가요?',ARRAY['K3-2-u3-X16','K3-2-u3-X17','K3-2-u3-X21']::text[],false,'{"seq":4,"concept":"K3-2-u3-C15","difficulty":1,"kind":"mc","stem":"차례를 알려 주는 말끼리 묶은 것은 무엇인가요?","options":[{"t":"먼저 · 다음으로 · 끝으로","correct":true},{"t":"그러나 · 그래서 · 그리고","mis":"K3-2-u3-X16"},{"t":"흙 · 잎 · 물받이","mis":"K3-2-u3-X17"},{"t":"과습 · 화분 · 물","mis":"K3-2-u3-X21"}],"explanation":["무엇을 먼저 할지 알려 주는 말이에요.","첫째·둘째·셋째도 돼요.","먼저·다음으로·끝으로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L09_basic#5','kor',3,2,'u3','L09','g3_2_kor_u3_L09_basic','lesson_basic','K3-2-u3-C15',2,'match','auto','하경이가 고친 곳과 좋아진 점을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u3-C15","difficulty":2,"kind":"match","stem":"하경이가 고친 곳과 좋아진 점을 알맞게 이으세요.","pairs":[{"l":"“과습” 대신 쉬운 말로 풀어 씀","r":"읽는 사람이 뜻을 바로 알 수 있다"},{"l":"먼저·다음으로·끝으로를 넣음","r":"무엇을 먼저 할지 알 수 있다"},{"l":"글 끝에 출처를 적음","r":"어디에서 알아낸 내용인지 알 수 있다"}],"mis":"K3-2-u3-X01","explanation":["세 친구가 한 말과 짝지어요.","낱말·차례·출처예요.","세 곳을 고쳤어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L09_basic#6','kor',3,2,'u3','L09','g3_2_kor_u3_L09_basic','lesson_basic','K3-2-u3-C14',2,'mc','auto','하경이가 학급 신문에 「교실 화분에 물 주는 방법」을 쓴 목적으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X21','K3-2-u3-X31']::text[],false,'{"seq":6,"concept":"K3-2-u3-C14","difficulty":2,"kind":"mc","stem":"하경이가 학급 신문에 「교실 화분에 물 주는 방법」을 쓴 목적으로 알맞은 것은 무엇인가요?","options":[{"t":"우리 반 친구들에게 교실 화분에 물 주는 방법을 알려 주려고","correct":true},{"t":"화분을 사 달라고 부탁하려고","mis":"K3-2-u3-X21"},{"t":"화분이 예쁘다고 자랑하려고","mis":"K3-2-u3-X31"},{"t":"어려운 낱말을 알려 주려고","mis":"K3-2-u3-X21"}],"explanation":["하경이는 방법을 알려 주고 싶었어요.","읽을 사람은 우리 반 친구들이에요.","알려 주려는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L09_basic#7','kor',3,2,'u3','L09','g3_2_kor_u3_L09_basic','lesson_basic','K3-2-u3-C15',2,'mc','auto','하경이가 고쳐 쓴 글에서 「다음으로」 할 일은 무엇인가요?',ARRAY['K3-2-u3-X22','K3-2-u3-X08']::text[],false,'{"seq":7,"concept":"K3-2-u3-C15","difficulty":2,"kind":"mc","stem":"하경이가 고쳐 쓴 글에서 「다음으로」 할 일은 무엇인가요?","options":[{"t":"잎이 아니라 흙 쪽으로 천천히 붓는다","correct":true},{"t":"흙을 손끝으로 만져 본다","mis":"K3-2-u3-X22"},{"t":"물받이에 고인 물을 비운다","mis":"K3-2-u3-X22"},{"t":"잎에 물을 붓는다","mis":"K3-2-u3-X08"}],"explanation":["「다음으로」가 붙은 줄을 찾아요.","만지기 다음이에요.","흙 쪽으로 부어요."],"asset":{"type":"passage","lines":["교실 화분은 물을 너무 자주 주면 오히려 잘 자라지 못합니다.","물을 주는 방법을 알아봅시다.","먼저, 흙을 손끝으로 만져 봅니다. 흙이 말라 있으면 물을 줍니다.","다음으로, 잎이 아니라 흙 쪽으로 천천히 붓습니다.","끝으로, 화분 아래 물받이에 고인 물을 비웁니다.","이대로 하면 우리 반 화분을 잘 가꿀 수 있습니다.","■ 출처: 「텃밭 안내판」, 학교 텃밭 앞."],"title":"하경이가 고쳐 쓴 글 「교실 화분에 물 주는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L09_basic#8','kor',3,2,'u3','L09','g3_2_kor_u3_L09_basic','lesson_basic','K3-2-u3-C16',2,'mc','auto','하경이가 고쳐 쓴 글의 출처는 어디에 적혀 있나요?',ARRAY['K3-2-u3-X04','K3-2-u3-X09']::text[],false,'{"seq":8,"concept":"K3-2-u3-C16","difficulty":2,"kind":"mc","stem":"하경이가 고쳐 쓴 글의 출처는 어디에 적혀 있나요?","options":[{"t":"글의 맨 끝","correct":true},{"t":"글의 제목 옆","mis":"K3-2-u3-X04"},{"t":"「먼저」 문장 안","mis":"K3-2-u3-X04"},{"t":"적혀 있지 않다","mis":"K3-2-u3-X09"}],"explanation":["「■ 출처」를 찾아요.","마지막 줄에 있어요.","글 끝에 밝혔어요."],"asset":{"type":"passage","lines":["교실 화분은 물을 너무 자주 주면 오히려 잘 자라지 못합니다.","물을 주는 방법을 알아봅시다.","먼저, 흙을 손끝으로 만져 봅니다. 흙이 말라 있으면 물을 줍니다.","다음으로, 잎이 아니라 흙 쪽으로 천천히 붓습니다.","끝으로, 화분 아래 물받이에 고인 물을 비웁니다.","이대로 하면 우리 반 화분을 잘 가꿀 수 있습니다.","■ 출처: 「텃밭 안내판」, 학교 텃밭 앞."],"title":"하경이가 고쳐 쓴 글 「교실 화분에 물 주는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L09_basic#9','kor',3,2,'u3','L09','g3_2_kor_u3_L09_basic','lesson_basic','K3-2-u3-C15',2,'ox','auto','순서나 방법을 설명하는 글에는 어려운 낱말을 많이 써야 좋아요.',ARRAY['K3-2-u3-X21']::text[],false,'{"seq":9,"concept":"K3-2-u3-C15","difficulty":2,"kind":"ox","stem":"순서나 방법을 설명하는 글에는 어려운 낱말을 많이 써야 좋아요.","answer":"X","reason_options":[{"t":"읽는 사람이 뜻을 바로 알아야 따라 할 수 있기 때문에","correct":true},{"t":"어려운 낱말이 많을수록 글이 훌륭해 보이기 때문에","mis":"K3-2-u3-X21"}],"mis":"K3-2-u3-X21","explanation":["다안이는 과습을 몰랐어요.","모르면 따라 할 수 없어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L09_basic#10','kor',3,2,'u3','L09','g3_2_kor_u3_L09_basic','lesson_basic','K3-2-u3-C16',3,'error','auto','찾아본 내용을 글에 쓸 때를 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X07','K3-2-u3-X06']::text[],false,'{"seq":10,"concept":"K3-2-u3-C16","difficulty":3,"kind":"error","stem":"찾아본 내용을 글에 쓸 때를 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「안내판에서 찾은 내용은 빼고 내가 아는 것만 써야 해.」","correct":true,"mis_target":"K3-2-u3-X07"},{"t":"친구 가 — 「찾은 곳을 글 끝에 밝히면 써도 돼.」","mis":"K3-2-u3-X06"},{"t":"친구 다 — 「내가 원래 알던 것처럼 쓰면 안 돼.」","mis":"K3-2-u3-X06"}],"explanation":["찾아본 내용도 쓸 수 있어요.","가져온 곳을 밝히면 돼요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L09_challenge#1','kor',3,2,'u3','L09','g3_2_kor_u3_L09_challenge','lesson_challenge','K3-2-u3-C15',2,'sa','auto','하경이가 고쳐 쓴 글에서 「먼저」·「다음으로」 뒤에 마지막 차례를 알려 주는 말을 찾아 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u3-C15","difficulty":2,"kind":"sa","stem":"하경이가 고쳐 쓴 글에서 「먼저」·「다음으로」 뒤에 마지막 차례를 알려 주는 말을 찾아 쓰세요.","answer":["끝으로"],"explanation":["물받이 문장을 봐요.","맨 앞에 놓인 말이에요.","끝으로예요."],"asset":{"type":"passage","lines":["교실 화분은 물을 너무 자주 주면 오히려 잘 자라지 못합니다.","물을 주는 방법을 알아봅시다.","먼저, 흙을 손끝으로 만져 봅니다. 흙이 말라 있으면 물을 줍니다.","다음으로, 잎이 아니라 흙 쪽으로 천천히 붓습니다.","끝으로, 화분 아래 물받이에 고인 물을 비웁니다.","이대로 하면 우리 반 화분을 잘 가꿀 수 있습니다.","■ 출처: 「텃밭 안내판」, 학교 텃밭 앞."],"title":"하경이가 고쳐 쓴 글 「교실 화분에 물 주는 방법」"},"mis":"K3-2-u3-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L09_challenge#2','kor',3,2,'u3','L09','g3_2_kor_u3_L09_challenge','lesson_challenge','K3-2-u3-C14',2,'mc','auto','글을 쓰기 전에 생각할 것 셋을 바르게 고른 것은 무엇인가요?',ARRAY['K3-2-u3-X20','K3-2-u3-X21']::text[],false,'{"seq":2,"concept":"K3-2-u3-C14","difficulty":2,"kind":"mc","stem":"글을 쓰기 전에 생각할 것 셋을 바르게 고른 것은 무엇인가요?","options":[{"t":"읽을 사람 · 쓰는 목적 · 꼭 들어가야 할 내용","correct":true},{"t":"글씨 색 · 글자 수 · 제목 무늬","mis":"K3-2-u3-X20"},{"t":"읽을 사람 · 글씨 색 · 글자 수","mis":"K3-2-u3-X20"},{"t":"어려운 낱말 · 긴 문장 · 느낌표","mis":"K3-2-u3-X21"}],"explanation":["누가, 왜, 무엇을이에요.","꾸미는 것은 다 쓴 뒤예요.","세 가지를 먼저 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L09_challenge#3','kor',3,2,'u3','L09','g3_2_kor_u3_L09_challenge','lesson_challenge','K3-2-u3-C15',3,'error','auto','세 친구의 말을 듣고 고칠 곳을 정했어요. 잘못 정한 친구는 누구인가요?',ARRAY['K3-2-u3-X21','K3-2-u3-X01']::text[],false,'{"seq":3,"concept":"K3-2-u3-C15","difficulty":3,"kind":"error","stem":"세 친구의 말을 듣고 고칠 곳을 정했어요. 잘못 정한 친구는 누구인가요?","options":[{"t":"친구 다 — 「윤하 말대로 하려면 낱말을 더 어렵게 바꾸자.」","correct":true,"mis_target":"K3-2-u3-X21"},{"t":"친구 가 — 「도영이 말대로 먼저·다음으로를 넣자.」","mis":"K3-2-u3-X01"},{"t":"친구 나 — 「다안이 말대로 과습을 쉬운 말로 풀자.」","mis":"K3-2-u3-X21"}],"explanation":["윤하는 출처가 없다고 했어요.","낱말과는 상관없어요.","친구 다가 잘못 정했어요."],"asset":{"type":"speech","turns":[{"who":"다안","text":"“과습”이 무슨 말이야?"},{"who":"도영","text":"뭘 먼저 해야 하는지 모르겠어."},{"who":"윤하","text":"어디에서 알아낸 건지 안 적혀 있네."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L09_challenge#4','kor',3,2,'u3','L09','g3_2_kor_u3_L09_challenge','lesson_challenge','K3-2-u3-C16',3,'mc','auto','윤하가 「어디에서 알아낸 건지 안 적혀 있네.」라고 하자 하경이는 어떻게 고쳤나요?',ARRAY['K3-2-u3-X07','K3-2-u3-X06','K3-2-u3-X23']::text[],false,'{"seq":4,"concept":"K3-2-u3-C16","difficulty":3,"kind":"mc","stem":"윤하가 「어디에서 알아낸 건지 안 적혀 있네.」라고 하자 하경이는 어떻게 고쳤나요?","options":[{"t":"글 끝에 「■ 출처: 「텃밭 안내판」, 학교 텃밭 앞.」을 적었다","correct":true},{"t":"찾아본 내용을 모두 뺐다","mis":"K3-2-u3-X07"},{"t":"내가 원래 알던 것처럼 고쳐 썼다","mis":"K3-2-u3-X06"},{"t":"그럴듯한 책 이름을 지어 적었다","mis":"K3-2-u3-X23"}],"explanation":["고쳐 쓴 글 마지막 줄을 봐요.","가져온 곳을 밝혔어요.","텃밭 안내판이에요."],"asset":{"type":"passage","lines":["교실 화분은 물을 너무 자주 주면 오히려 잘 자라지 못합니다.","물을 주는 방법을 알아봅시다.","먼저, 흙을 손끝으로 만져 봅니다. 흙이 말라 있으면 물을 줍니다.","다음으로, 잎이 아니라 흙 쪽으로 천천히 붓습니다.","끝으로, 화분 아래 물받이에 고인 물을 비웁니다.","이대로 하면 우리 반 화분을 잘 가꿀 수 있습니다.","■ 출처: 「텃밭 안내판」, 학교 텃밭 앞."],"title":"하경이가 고쳐 쓴 글 「교실 화분에 물 주는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L09_challenge#5','kor',3,2,'u3','L09','g3_2_kor_u3_L09_challenge','lesson_challenge','K3-2-u3-C15',3,'ox','auto','「흙을 만져 보고 주면 돼요.」보다 「먼저, 흙을 손끝으로 만져 봅니다.」처럼 쓰면 무엇을 먼저 할지 더 잘 알 수 있어요.',ARRAY['K3-2-u3-X22']::text[],false,'{"seq":5,"concept":"K3-2-u3-C15","difficulty":3,"kind":"ox","stem":"「흙을 만져 보고 주면 돼요.」보다 「먼저, 흙을 손끝으로 만져 봅니다.」처럼 쓰면 무엇을 먼저 할지 더 잘 알 수 있어요.","answer":"O","reason_options":[{"t":"차례를 나타내는 말이 일의 순서를 알려 주기 때문에","correct":true},{"t":"문장이 길어질수록 차례가 잘 드러나기 때문에","mis":"K3-2-u3-X22"}],"mis":"K3-2-u3-X22","explanation":["「먼저」가 붙었어요.","첫 번째로 할 일이 보여요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L09_challenge#6','kor',3,2,'u3','L09','g3_2_kor_u3_L09_challenge','lesson_challenge','K3-2-u3-C14',3,'mc','auto','하경이 글을 1학년 동생이 읽는다면 가장 먼저 더 신경 쓸 것은 무엇인가요?',ARRAY['K3-2-u3-X21','K3-2-u3-X20','K3-2-u3-X23']::text[],false,'{"seq":6,"concept":"K3-2-u3-C14","difficulty":3,"kind":"mc","stem":"하경이 글을 1학년 동생이 읽는다면 가장 먼저 더 신경 쓸 것은 무엇인가요?","options":[{"t":"동생도 알 수 있는 쉬운 말로 차례를 하나씩 쓰기","correct":true},{"t":"어려운 낱말을 더 넣어 똑똑해 보이기","mis":"K3-2-u3-X21"},{"t":"글씨 색을 알록달록하게 바꾸기","mis":"K3-2-u3-X20"},{"t":"출처를 지어서 하나 더 붙이기","mis":"K3-2-u3-X23"}],"explanation":["읽을 사람이 바뀌었어요.","동생이 알아들어야 해요.","쉬운 말과 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L09_challenge#7','kor',3,2,'u3','L09','g3_2_kor_u3_L09_challenge','lesson_challenge','K3-2-u3-C15',3,'match','auto','처음 쓴 글의 아쉬운 곳과 고치는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u3-C15","difficulty":3,"kind":"match","stem":"처음 쓴 글의 아쉬운 곳과 고치는 방법을 알맞게 이으세요.","pairs":[{"l":"이해하기 어려운 낱말","r":"쉬운 말로 풀어 쓴다"},{"l":"일의 차례가 드러나지 않음","r":"차례를 나타내는 말을 넣는다"},{"l":"가져온 자료의 출처가 없음","r":"글 끝에 출처를 적는다"}],"mis":"K3-2-u3-X01","explanation":["아쉬운 곳마다 고칠 방법이 있어요.","낱말은 풀고, 차례는 말로 보여요.","출처는 끝에 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L09_challenge#8','kor',3,2,'u3','L09','g3_2_kor_u3_L09_challenge','lesson_challenge','K3-2-u3-C15',4,'mc','auto','하경이가 고쳐 쓴 글에서 「먼저」 문장과 「끝으로」 문장의 차례를 바꾸면 어떤 문제가 생기나요?',ARRAY['K3-2-u3-X22','K3-2-u3-X01','K3-2-u3-X09']::text[],false,'{"seq":8,"concept":"K3-2-u3-C15","difficulty":4,"kind":"mc","stem":"하경이가 고쳐 쓴 글에서 「먼저」 문장과 「끝으로」 문장의 차례를 바꾸면 어떤 문제가 생기나요?","options":[{"t":"물받이를 먼저 비우고 물을 주게 되어, 물을 준 뒤 고인 물이 그대로 남는다","correct":true},{"t":"아무 문제가 없다 — 차례 말은 꾸밈말이라서","mis":"K3-2-u3-X22"},{"t":"글이 짧아져 문제가 된다","mis":"K3-2-u3-X01"},{"t":"출처가 사라진다","mis":"K3-2-u3-X09"}],"explanation":["차례대로 따라 해 봐요.","비운 뒤에 물을 주면 다시 고여요.","차례가 바뀌면 일이 어긋나요."],"asset":{"type":"passage","lines":["교실 화분은 물을 너무 자주 주면 오히려 잘 자라지 못합니다.","물을 주는 방법을 알아봅시다.","먼저, 흙을 손끝으로 만져 봅니다. 흙이 말라 있으면 물을 줍니다.","다음으로, 잎이 아니라 흙 쪽으로 천천히 붓습니다.","끝으로, 화분 아래 물받이에 고인 물을 비웁니다.","이대로 하면 우리 반 화분을 잘 가꿀 수 있습니다.","■ 출처: 「텃밭 안내판」, 학교 텃밭 앞."],"title":"하경이가 고쳐 쓴 글 「교실 화분에 물 주는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L09_challenge#9','kor',3,2,'u3','L09','g3_2_kor_u3_L09_challenge','lesson_challenge','K3-2-u3-C14',4,'essay','teacher','내가 설명하고 싶은 방법을 하나 고르고, 읽을 사람·쓰는 목적·꼭 들어가야 할 내용을 정해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u3-C14","difficulty":4,"kind":"essay","stem":"내가 설명하고 싶은 방법을 하나 고르고, 읽을 사람·쓰는 목적·꼭 들어가야 할 내용을 정해 쓰세요.","answer_guide":{"answer":"예: 고른 방법 — 실내화를 신발장에 넣는 방법. 읽을 사람 — 1학년 동생들. 목적 — 신발장을 깨끗하게 쓰도록 알려 주려고. 꼭 들어갈 내용 — 내 번호가 붙은 칸 찾기, 두 짝을 나란히 맞추어 넣기, 칸 안쪽까지 밀어 넣기.","scoring_points":["설명할 방법을 골랐는가","읽을 사람과 목적을 썼는가","꼭 들어갈 내용을 썼는가"]},"explanation":["내가 잘 아는 일을 골라요.","누가 왜 읽는지 정해요.","그러면 쓸 내용이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L09_challenge#10','kor',3,2,'u3','L09','g3_2_kor_u3_L09_challenge','lesson_challenge','K3-2-u3-C16',4,'essay','teacher','하경이가 처음 쓴 글에 출처가 없는 점을 고쳐야 하는 까닭을 쓰고, 출처를 밝히지 않으면 읽는 사람에게 어떤 일이 생길지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u3-C16","difficulty":4,"kind":"essay","stem":"하경이가 처음 쓴 글에 출처가 없는 점을 고쳐야 하는 까닭을 쓰고, 출처를 밝히지 않으면 읽는 사람에게 어떤 일이 생길지 쓰세요.","answer_guide":{"answer":"예: 하경이는 텃밭 안내판에서 알아낸 내용을 썼으니 가져온 곳을 밝혀야 한다. 출처가 없으면 읽는 친구가 더 알고 싶어도 어디에서 찾아볼지 알 수 없고, 믿을 만한 내용인지 살펴볼 수도 없다. 또 안내판을 만든 곳의 것을 내가 생각해 낸 것처럼 쓴 셈이 된다.","scoring_points":["찾아본 내용이라 출처를 밝혀야 한다고 썼는가","읽는 사람에게 생길 일을 썼는가","만든 곳을 존중한다는 점을 썼는가"]},"explanation":["읽을 때 확인하던 출처예요.","쓸 때는 내가 밝혀요.","읽는 사람 쪽에서 생각해요."],"asset":{"type":"passage","lines":["화분은 과습이 되지 않게 해야 해요. 흙을 만져 보고 주면 돼요.","잎에 붓지 말고요. 물받이도 있어요.","우리 모두 화분을 잘 돌봐요."],"title":"하경이가 처음 쓴 글 「교실 화분에 물 주는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L10_basic#1','kor',3,2,'u3','L10','g3_2_kor_u3_L10_basic','lesson_basic','K3-2-u3-C17',1,'mc','auto','쓸 내용을 정할 때 가장 먼저 생각할 것은 무엇인가요?',ARRAY['K3-2-u3-X20','K3-2-u3-X21']::text[],false,'{"seq":1,"concept":"K3-2-u3-C17","difficulty":1,"kind":"mc","stem":"쓸 내용을 정할 때 가장 먼저 생각할 것은 무엇인가요?","options":[{"t":"이 글을 읽을 사람이 누구인지","correct":true},{"t":"제목을 예쁘게 꾸미는 방법","mis":"K3-2-u3-X20"},{"t":"글을 몇 줄로 맞출지","mis":"K3-2-u3-X20"},{"t":"어려운 낱말을 몇 개 넣을지","mis":"K3-2-u3-X21"}],"explanation":["1학년 동생과 우리 반 친구는 달라요.","읽을 사람이 정해져야 해요.","그래야 얼마나 자세히 쓸지 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L10_basic#2','kor',3,2,'u3','L10','g3_2_kor_u3_L10_basic','lesson_basic','K3-2-u3-C17',1,'match','auto','문장과 그 문장이 들어갈 부분을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K3-2-u3-C17","difficulty":1,"kind":"match","stem":"문장과 그 문장이 들어갈 부분을 알맞게 이으세요.","pairs":[{"l":"“사물함을 정리하는 방법을 알아봅시다.”","r":"처음"},{"l":"“먼저, 물건을 종류에 따라 나눕니다.”","r":"가운데"},{"l":"“이렇게 하면 필요한 물건을 쉽게 찾을 수 있습니다.”","r":"끝"}],"mis":"K3-2-u3-X25","explanation":["처음에는 무엇을 설명할지 밝혀요.","가운데에는 차례와 방법이에요.","끝에는 간추려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L10_basic#3','kor',3,2,'u3','L10','g3_2_kor_u3_L10_basic','lesson_basic','K3-2-u3-C16',1,'ox','auto','내가 이미 해 보아서 아는 방법을 쓸 때에는 출처가 없어도 돼요.',ARRAY['K3-2-u3-X24']::text[],false,'{"seq":3,"concept":"K3-2-u3-C16","difficulty":1,"kind":"ox","stem":"내가 이미 해 보아서 아는 방법을 쓸 때에는 출처가 없어도 돼요.","answer":"O","reason_options":[{"t":"내가 해 본 일이라 다른 곳에서 가져온 자료가 아니기 때문에","correct":true},{"t":"설명하는 글에는 무엇이든 꼭 출처를 붙여야 하기 때문에","mis":"K3-2-u3-X24"}],"mis":"K3-2-u3-X24","explanation":["글에 들어가는 내용은 두 갈래예요.","내가 아는 것과 찾아본 것이에요.","내가 아는 것은 출처가 없어도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L10_basic#4','kor',3,2,'u3','L10','g3_2_kor_u3_L10_basic','lesson_basic','K3-2-u3-C18',1,'mc','auto','세연이 글에서 일의 차례가 가장 잘 드러난 문장은 무엇인가요?',ARRAY['K3-2-u3-X25']::text[],false,'{"seq":4,"concept":"K3-2-u3-C18","difficulty":1,"kind":"mc","stem":"세연이 글에서 일의 차례가 가장 잘 드러난 문장은 무엇인가요?","options":[{"t":"“먼저, 사물함에 든 물건을 모두 꺼내 종류에 따라 나눕니다.”","correct":true},{"t":"“사물함이 잘 정리되어 있으면 필요한 물건을 빨리 찾을 수 있습니다.”","mis":"K3-2-u3-X25"},{"t":"“제가 하는 방법을 알려 드리겠습니다.”","mis":"K3-2-u3-X25"},{"t":"“이 차례대로 하면 사물함을 오래 깨끗하게 쓸 수 있습니다.”","mis":"K3-2-u3-X25"}],"explanation":["「먼저」가 있는 문장을 찾아요.","무엇부터 할지 바로 알아요.","첫 번째 할 일이에요."],"asset":{"type":"passage","lines":["사물함이 잘 정리되어 있으면 필요한 물건을 빨리 찾을 수 있습니다.","제가 하는 방법을 알려 드리겠습니다.","먼저, 사물함에 든 물건을 모두 꺼내 종류에 따라 나눕니다.","다음으로, 교과서와 공책은 세워서 꽂습니다.","그리고 작은 물건은 바구니에 모아 담습니다.","끝으로, 자주 쓰는 것을 앞쪽에 둡니다.","안쪽에 두면 꺼내기 어렵기 때문입니다.","이 차례대로 하면 사물함을 오래 깨끗하게 쓸 수 있습니다."],"title":"세연이가 쓴 글 「사물함을 정리하는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L10_basic#5','kor',3,2,'u3','L10','g3_2_kor_u3_L10_basic','lesson_basic','K3-2-u3-C16',2,'mc','auto','찾아본 곳이 기억나지 않으면 어떻게 해야 할까요?',ARRAY['K3-2-u3-X23','K3-2-u3-X06']::text[],false,'{"seq":5,"concept":"K3-2-u3-C16","difficulty":2,"kind":"mc","stem":"찾아본 곳이 기억나지 않으면 어떻게 해야 할까요?","options":[{"t":"다시 확인해 적거나, 그 내용은 쓰지 않는다","correct":true},{"t":"그럴듯한 이름을 지어서 적는다","mis":"K3-2-u3-X23"},{"t":"출처 칸을 아무 말이나 써서 채운다","mis":"K3-2-u3-X23"},{"t":"내가 원래 알던 것처럼 쓴다","mis":"K3-2-u3-X06"}],"explanation":["출처는 지어내는 것이 아니에요.","확인하는 것이에요.","확인할 수 없으면 쓰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L10_basic#6','kor',3,2,'u3','L10','g3_2_kor_u3_L10_basic','lesson_basic','K3-2-u3-C17',2,'mc','auto','설명하는 글의 가운데 부분에 들어갈 내용은 무엇인가요?',ARRAY['K3-2-u3-X25','K3-2-u3-X20']::text[],false,'{"seq":6,"concept":"K3-2-u3-C17","difficulty":2,"kind":"mc","stem":"설명하는 글의 가운데 부분에 들어갈 내용은 무엇인가요?","options":[{"t":"일의 차례와 방법을 자세히","correct":true},{"t":"무엇을 설명할 글인지 밝히기","mis":"K3-2-u3-X25"},{"t":"설명한 내용을 간추리기","mis":"K3-2-u3-X25"},{"t":"글씨 색 정하기","mis":"K3-2-u3-X20"}],"explanation":["글은 세 부분이에요.","처음·가운데·끝이에요.","가운데에 차례와 방법을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L10_basic#7','kor',3,2,'u3','L10','g3_2_kor_u3_L10_basic','lesson_basic','K3-2-u3-C18',2,'mc','auto','세연이가 「안쪽에 두면 꺼내기 어렵기 때문입니다.」를 덧붙인 까닭은 무엇인가요?',ARRAY['K3-2-u3-X05','K3-2-u3-X22','K3-2-u3-X24']::text[],false,'{"seq":7,"concept":"K3-2-u3-C18","difficulty":2,"kind":"mc","stem":"세연이가 「안쪽에 두면 꺼내기 어렵기 때문입니다.」를 덧붙인 까닭은 무엇인가요?","options":[{"t":"자주 쓰는 것을 앞쪽에 두는 까닭을 알려 주려고","correct":true},{"t":"글을 길게 보이려고","mis":"K3-2-u3-X05"},{"t":"차례를 바꾸려고","mis":"K3-2-u3-X22"},{"t":"출처를 밝히려고","mis":"K3-2-u3-X24"}],"explanation":["바로 앞 문장을 봐요.","앞쪽에 둔다고 했어요.","그 까닭을 알려 줬어요."],"asset":{"type":"passage","lines":["사물함이 잘 정리되어 있으면 필요한 물건을 빨리 찾을 수 있습니다.","제가 하는 방법을 알려 드리겠습니다.","먼저, 사물함에 든 물건을 모두 꺼내 종류에 따라 나눕니다.","다음으로, 교과서와 공책은 세워서 꽂습니다.","그리고 작은 물건은 바구니에 모아 담습니다.","끝으로, 자주 쓰는 것을 앞쪽에 둡니다.","안쪽에 두면 꺼내기 어렵기 때문입니다.","이 차례대로 하면 사물함을 오래 깨끗하게 쓸 수 있습니다."],"title":"세연이가 쓴 글 「사물함을 정리하는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L10_basic#8','kor',3,2,'u3','L10','g3_2_kor_u3_L10_basic','lesson_basic','K3-2-u3-C18',2,'ox','auto','세연이처럼 종류에 따라 나눈 글만 알맞은 글이에요.',ARRAY['K3-2-u3-X27']::text[],false,'{"seq":8,"concept":"K3-2-u3-C18","difficulty":2,"kind":"ox","stem":"세연이처럼 종류에 따라 나눈 글만 알맞은 글이에요.","answer":"X","reason_options":[{"t":"방법이 달라도 차례와 까닭이 드러나면 둘 다 알맞은 글이기 때문에","correct":true},{"t":"같은 일을 설명하는 방법은 하나뿐이기 때문에","mis":"K3-2-u3-X27"}],"mis":"K3-2-u3-X27","explanation":["다안이는 다르게 나눠요.","둘 다 따라 할 수 있어요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"세연","text":"나는 종류에 따라 나눠. 책은 책끼리, 학용품은 학용품끼리."},{"who":"다안","text":"나는 자주 쓰는지로 나눠. 매일 쓰는 건 앞쪽, 가끔 쓰는 건 안쪽."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L10_basic#9','kor',3,2,'u3','L10','g3_2_kor_u3_L10_basic','lesson_basic','K3-2-u3-C18',2,'mc','auto','쓴 글을 스스로 점검할 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X26','K3-2-u3-X27']::text[],false,'{"seq":9,"concept":"K3-2-u3-C18","difficulty":2,"kind":"mc","stem":"쓴 글을 스스로 점검할 것으로 알맞은 것은 무엇인가요?","options":[{"t":"이어 주는 말을 알맞게 썼는가","correct":true},{"t":"점검표 칸이 모두 채워졌는가","mis":"K3-2-u3-X26"},{"t":"점수가 몇 점인가","mis":"K3-2-u3-X26"},{"t":"친구 글과 똑같은가","mis":"K3-2-u3-X27"}],"explanation":["점검은 고치려고 해요.","차례·궁금한 내용·이어 주는 말·출처를 봐요.","이어 주는 말이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L10_basic#10','kor',3,2,'u3','L10','g3_2_kor_u3_L10_basic','lesson_basic','K3-2-u3-C15',3,'error','auto','이어 주는 말과 차례 말을 넣어 문장을 썼어요. 알맞지 않게 쓴 친구는 누구인가요?',ARRAY['K3-2-u3-X22','K3-2-u3-X16']::text[],false,'{"seq":10,"concept":"K3-2-u3-C15","difficulty":3,"kind":"error","stem":"이어 주는 말과 차례 말을 넣어 문장을 썼어요. 알맞지 않게 쓴 친구는 누구인가요?","options":[{"t":"친구 다 — 「끝으로 물건을 꺼냅니다. 먼저 정리를 마칩니다.」","correct":true,"mis_target":"K3-2-u3-X22"},{"t":"친구 가 — 「안쪽에 두면 꺼내기 어렵습니다. 그래서 앞쪽에 둡니다.」","mis":"K3-2-u3-X16"},{"t":"친구 나 — 「먼저 물건을 나눕니다. 다음으로 자리를 정합니다.」","mis":"K3-2-u3-X22"}],"explanation":["차례 말은 순서대로 써요.","「끝으로」 뒤에 「먼저」가 왔어요.","친구 다가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L10_challenge#1','kor',3,2,'u3','L10','g3_2_kor_u3_L10_challenge','lesson_challenge','K3-2-u3-C17',2,'sa','auto','설명하는 글의 세 부분 가운데 「설명한 내용을 간추리는」 부분은 어디인가요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u3-C17","difficulty":2,"kind":"sa","stem":"설명하는 글의 세 부분 가운데 「설명한 내용을 간추리는」 부분은 어디인가요? 한 글자로 쓰세요.","answer":["끝"],"explanation":["처음·가운데·끝이에요.","마지막에 간추려요.","끝이에요."],"mis":"K3-2-u3-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L10_challenge#2','kor',3,2,'u3','L10','g3_2_kor_u3_L10_challenge','lesson_challenge','K3-2-u3-C12',2,'mc','auto','세연이 글에서 「그리고」 앞뒤는 어떤 관계인가요?',ARRAY['K3-2-u3-X16','K3-2-u3-X25']::text[],false,'{"seq":2,"concept":"K3-2-u3-C12","difficulty":2,"kind":"mc","stem":"세연이 글에서 「그리고」 앞뒤는 어떤 관계인가요?","options":[{"t":"앞과 비슷한 내용(정리하는 방법 하나 더)이 이어진다","correct":true},{"t":"앞과 반대되는 내용이 이어진다","mis":"K3-2-u3-X16"},{"t":"앞이 뒤의 까닭이 된다","mis":"K3-2-u3-X16"},{"t":"글을 마무리한다","mis":"K3-2-u3-X25"}],"explanation":["세워 꽂고, 그리고 바구니에 담아요.","방법이 하나 더 붙어요.","비슷한 내용이 이어져요."],"asset":{"type":"passage","lines":["사물함이 잘 정리되어 있으면 필요한 물건을 빨리 찾을 수 있습니다.","제가 하는 방법을 알려 드리겠습니다.","먼저, 사물함에 든 물건을 모두 꺼내 종류에 따라 나눕니다.","다음으로, 교과서와 공책은 세워서 꽂습니다.","그리고 작은 물건은 바구니에 모아 담습니다.","끝으로, 자주 쓰는 것을 앞쪽에 둡니다.","안쪽에 두면 꺼내기 어렵기 때문입니다.","이 차례대로 하면 사물함을 오래 깨끗하게 쓸 수 있습니다."],"title":"세연이가 쓴 글 「사물함을 정리하는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L10_challenge#3','kor',3,2,'u3','L10','g3_2_kor_u3_L10_challenge','lesson_challenge','K3-2-u3-C16',3,'error','auto','세연이가 글을 쓰며 혼잣말을 했어요. 알맞지 않게 생각한 것은 무엇인가요?',ARRAY['K3-2-u3-X23','K3-2-u3-X24','K3-2-u3-X06']::text[],false,'{"seq":3,"concept":"K3-2-u3-C16","difficulty":3,"kind":"error","stem":"세연이가 글을 쓰며 혼잣말을 했어요. 알맞지 않게 생각한 것은 무엇인가요?","options":[{"t":"「바구니에 담으면 좋다는 걸 어디서 읽었는데 기억이 안 나. 「정리 박사」라고 적어 두자.」","correct":true,"mis_target":"K3-2-u3-X23"},{"t":"「교과서를 세워 꽂는 건 내가 늘 하는 방법이니 출처는 없어도 돼.」","mis":"K3-2-u3-X24"},{"t":"「보건실 안내장에서 본 내용은 가져온 곳을 끝에 적을게.」","mis":"K3-2-u3-X06"}],"explanation":["기억나지 않는 출처를 지어냈어요.","읽는 친구는 찾아갈 수 없어요.","첫 번째가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L10_challenge#4','kor',3,2,'u3','L10','g3_2_kor_u3_L10_challenge','lesson_challenge','K3-2-u3-C17',3,'mc','auto','1학년 동생에게 알려 줄 때와 우리 반 친구에게 알려 줄 때 글이 달라지는 까닭은 무엇인가요?',ARRAY['K3-2-u3-X20','K3-2-u3-X21','K3-2-u3-X27']::text[],false,'{"seq":4,"concept":"K3-2-u3-C17","difficulty":3,"kind":"mc","stem":"1학년 동생에게 알려 줄 때와 우리 반 친구에게 알려 줄 때 글이 달라지는 까닭은 무엇인가요?","options":[{"t":"읽을 사람에 따라 어디까지 자세히 쓸지가 달라지기 때문에","correct":true},{"t":"제목 꾸미는 방법이 달라지기 때문에","mis":"K3-2-u3-X20"},{"t":"동생에게는 어려운 낱말을 더 써야 하기 때문에","mis":"K3-2-u3-X21"},{"t":"글은 언제나 똑같아야 하기 때문에","mis":"K3-2-u3-X27"}],"explanation":["읽을 사람이 달라요.","아는 것도 달라요.","자세한 정도가 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L10_challenge#5','kor',3,2,'u3','L10','g3_2_kor_u3_L10_challenge','lesson_challenge','K3-2-u3-C18',3,'ox','auto','쓴 글을 점검하는 것은 점검표 칸을 다 채웠는지 확인하려는 거예요.',ARRAY['K3-2-u3-X26']::text[],false,'{"seq":5,"concept":"K3-2-u3-C18","difficulty":3,"kind":"ox","stem":"쓴 글을 점검하는 것은 점검표 칸을 다 채웠는지 확인하려는 거예요.","answer":"X","reason_options":[{"t":"채우려는 것이 아니라 고치려고 살펴보는 것이기 때문에","correct":true},{"t":"점검표에 빈칸이 없으면 좋은 글이기 때문에","mis":"K3-2-u3-X26"}],"mis":"K3-2-u3-X26","explanation":["점검표는 채우려고 보지 않아요.","고칠 곳을 찾으려고 봐요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L10_challenge#6','kor',3,2,'u3','L10','g3_2_kor_u3_L10_challenge','lesson_challenge','K3-2-u3-C18',3,'mc','auto','세연이와 다안이의 글 가운데 어느 쪽이 알맞은 글인가요?',ARRAY['K3-2-u3-X27']::text[],false,'{"seq":6,"concept":"K3-2-u3-C18","difficulty":3,"kind":"mc","stem":"세연이와 다안이의 글 가운데 어느 쪽이 알맞은 글인가요?","options":[{"t":"둘 다 알맞다 — 차례와 까닭이 드러나면 된다","correct":true},{"t":"종류에 따라 나눈 세연이 글만 알맞다","mis":"K3-2-u3-X27"},{"t":"자주 쓰는지로 나눈 다안이 글만 알맞다","mis":"K3-2-u3-X27"},{"t":"둘 다 알맞지 않다 — 방법이 서로 달라서","mis":"K3-2-u3-X27"}],"explanation":["설명하는 글에서 중요한 것을 떠올려요.","읽는 사람이 따라 할 수 있는지예요.","둘 다 알맞아요."],"asset":{"type":"speech","turns":[{"who":"세연","text":"나는 종류에 따라 나눠. 책은 책끼리, 학용품은 학용품끼리."},{"who":"다안","text":"나는 자주 쓰는지로 나눠. 매일 쓰는 건 앞쪽, 가끔 쓰는 건 안쪽."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L10_challenge#7','kor',3,2,'u3','L10','g3_2_kor_u3_L10_challenge','lesson_challenge','K3-2-u3-C18',3,'match','auto','점검할 것과 그에 맞게 고치는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u3-C18","difficulty":3,"kind":"match","stem":"점검할 것과 그에 맞게 고치는 방법을 알맞게 이으세요.","pairs":[{"l":"일의 차례와 방법이 드러났는가","r":"먼저·다음으로를 넣는다"},{"l":"이어 주는 말을 알맞게 썼는가","r":"앞뒤 관계에 맞는 말로 바꾼다"},{"l":"가져온 자료의 출처를 밝혔는가","r":"가져온 곳을 끝에 적는다"}],"mis":"K3-2-u3-X26","explanation":["점검은 고치려고 해요.","살펴본 것마다 고칠 방법이 있어요.","차례·이어 주는 말·출처예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L10_challenge#8','kor',3,2,'u3','L10','g3_2_kor_u3_L10_challenge','lesson_challenge','K3-2-u3-C17',4,'mc','auto','세연이 글의 첫 두 문장 「사물함이 잘 정리되어 있으면 … 알려 드리겠습니다.」를 지우면 어떤 점이 아쉬워지나요?',ARRAY['K3-2-u3-X25','K3-2-u3-X24']::text[],false,'{"seq":8,"concept":"K3-2-u3-C17","difficulty":4,"kind":"mc","stem":"세연이 글의 첫 두 문장 「사물함이 잘 정리되어 있으면 … 알려 드리겠습니다.」를 지우면 어떤 점이 아쉬워지나요?","options":[{"t":"처음 부분이 없어져, 무엇을 왜 설명하는 글인지 모른 채 차례부터 읽게 된다","correct":true},{"t":"아무 문제 없다 — 차례만 있으면 된다","mis":"K3-2-u3-X25"},{"t":"끝 부분이 없어져 간추린 내용을 모른다","mis":"K3-2-u3-X25"},{"t":"출처가 사라진다","mis":"K3-2-u3-X24"}],"explanation":["첫 두 문장은 처음 부분이에요.","무엇을 왜 설명할지 밝혀요.","없으면 바로 차례부터 나와요."],"asset":{"type":"passage","lines":["사물함이 잘 정리되어 있으면 필요한 물건을 빨리 찾을 수 있습니다.","제가 하는 방법을 알려 드리겠습니다.","먼저, 사물함에 든 물건을 모두 꺼내 종류에 따라 나눕니다.","다음으로, 교과서와 공책은 세워서 꽂습니다.","그리고 작은 물건은 바구니에 모아 담습니다.","끝으로, 자주 쓰는 것을 앞쪽에 둡니다.","안쪽에 두면 꺼내기 어렵기 때문입니다.","이 차례대로 하면 사물함을 오래 깨끗하게 쓸 수 있습니다."],"title":"세연이가 쓴 글 「사물함을 정리하는 방법」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L10_challenge#9','kor',3,2,'u3','L10','g3_2_kor_u3_L10_challenge','lesson_challenge','K3-2-u3-C17',4,'essay','teacher','내가 잘 아는 방법 하나를 골라 처음·가운데·끝으로 나누어 짧게 쓰세요. 가운데에는 차례를 나타내는 말을 두 개 넣으세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u3-C17","difficulty":4,"kind":"essay","stem":"내가 잘 아는 방법 하나를 골라 처음·가운데·끝으로 나누어 짧게 쓰세요. 가운데에는 차례를 나타내는 말을 두 개 넣으세요.","answer_guide":{"answer":"예: 처음 — 칠판을 깨끗하게 지우는 방법을 알려 드리겠습니다. 가운데 — 먼저, 칠판지우개로 위에서 아래로 지웁니다. 다음으로, 지우개를 털어 가루를 떨어냅니다. 끝 — 이 차례대로 하면 칠판을 깨끗하게 쓸 수 있습니다.","scoring_points":["처음·가운데·끝으로 나누었는가","가운데에 차례를 나타내는 말을 두 개 넣었는가","끝에 간추리는 말을 썼는가"]},"explanation":["이미 할 줄 아는 일이 좋아요.","가운데에 차례를 써요.","끝에서 간추려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L10_challenge#10','kor',3,2,'u3','L10','g3_2_kor_u3_L10_challenge','lesson_challenge','K3-2-u3-C16',4,'essay','teacher','찾아본 곳이 기억나지 않을 때 그럴듯한 이름을 지어 적으면 안 되는 까닭을 그 글을 읽은 친구에게 생길 일을 들어 쓰고, 어떻게 해야 하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u3-C16","difficulty":4,"kind":"essay","stem":"찾아본 곳이 기억나지 않을 때 그럴듯한 이름을 지어 적으면 안 되는 까닭을 그 글을 읽은 친구에게 생길 일을 들어 쓰고, 어떻게 해야 하는지 쓰세요.","answer_guide":{"answer":"예: 지어 적은 이름을 믿고 친구가 찾아가려 해도 그런 곳이 없어 찾을 수 없다. 또 친구는 사실이 아닌 것을 믿게 될 수 있다. 그래서 다시 확인해 정확한 출처를 적거나, 확인할 수 없으면 그 내용은 쓰지 않는다.","scoring_points":["읽는 친구가 찾아갈 수 없다고 썼는가","사실이 아닌 것을 믿게 될 수 있다고 썼는가","다시 확인하거나 쓰지 않는다고 썼는가"]},"explanation":["이 단원에서 가장 중요한 답이에요.","출처는 확인하는 것이에요.","지어내지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L12_basic#1','kor',3,2,'u3','L12','g3_2_kor_u3_L12_basic','lesson_basic','K3-2-u3-C12',1,'mc','auto','「학교 도서관에 새 책이 들어왔습니다. 그러나 …」 뒤에 이어질 문장으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X16']::text[],false,'{"seq":1,"concept":"K3-2-u3-C12","difficulty":1,"kind":"mc","stem":"「학교 도서관에 새 책이 들어왔습니다. 그러나 …」 뒤에 이어질 문장으로 알맞은 것은 무엇인가요?","options":[{"t":"아직 정리가 끝나지 않아 빌릴 수 없었습니다","correct":true},{"t":"바로 빌릴 수 있어 기뻤습니다","mis":"K3-2-u3-X16"},{"t":"책이 많아져 좋았습니다","mis":"K3-2-u3-X16"},{"t":"그래서 도서관에 갔습니다","mis":"K3-2-u3-X16"}],"explanation":["「그러나」 뒤에는 반대되는 일이 와요.","새 책이 들어와 좋았을 텐데요.","빌릴 수 없었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L12_basic#2','kor',3,2,'u3','L12','g3_2_kor_u3_L12_basic','lesson_basic','K3-2-u3-C12',1,'mc','auto','「아침에 늦게 일어났습니다. 그래서 …」 뒤에 이어질 문장으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X16']::text[],false,'{"seq":2,"concept":"K3-2-u3-C12","difficulty":1,"kind":"mc","stem":"「아침에 늦게 일어났습니다. 그래서 …」 뒤에 이어질 문장으로 알맞은 것은 무엇인가요?","options":[{"t":"서둘러 학교에 갔습니다","correct":true},{"t":"날씨가 맑았습니다","mis":"K3-2-u3-X16"},{"t":"일찍 잠자리에 들었습니다","mis":"K3-2-u3-X16"},{"t":"어제 저녁을 먹었습니다","mis":"K3-2-u3-X16"}],"explanation":["「그래서」 앞은 까닭이에요.","늦게 일어나서 생긴 일을 찾아요.","서둘러 갔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L12_basic#3','kor',3,2,'u3','L12','g3_2_kor_u3_L12_basic','lesson_basic','K3-2-u3-C20',1,'mc','auto','남에게 들은 말을 전할 때(…다고 해) 쓰는 말은 무엇인가요?',ARRAY['K3-2-u3-X29']::text[],false,'{"seq":3,"concept":"K3-2-u3-C20","difficulty":1,"kind":"mc","stem":"남에게 들은 말을 전할 때(…다고 해) 쓰는 말은 무엇인가요?","options":[{"t":"‘-대’","correct":true},{"t":"‘-데’","mis":"K3-2-u3-X29"},{"t":"‘-고’","mis":"K3-2-u3-X29"},{"t":"아무거나 써도 된다","mis":"K3-2-u3-X29"}],"explanation":["‘-대’는 「…다고 해」예요.","남의 말을 전해요.","내가 겪은 것은 ‘-데’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L12_basic#4','kor',3,2,'u3','L12','g3_2_kor_u3_L12_basic','lesson_basic','K3-2-u3-C19',1,'ox','auto','이용 설명서에 사진을 가져와 썼다면 사진 아래에 가져온 곳을 적어요.',ARRAY['K3-2-u3-X28']::text[],false,'{"seq":4,"concept":"K3-2-u3-C19","difficulty":1,"kind":"ox","stem":"이용 설명서에 사진을 가져와 썼다면 사진 아래에 가져온 곳을 적어요.","answer":"O","reason_options":[{"t":"자료의 종류가 달라도 가져온 곳은 똑같이 적기 때문에","correct":true},{"t":"사진은 글이 아니라 출처가 필요 없기 때문에","mis":"K3-2-u3-X28"}],"mis":"K3-2-u3-X28","explanation":["자료의 종류는 여러 가지예요.","사진도 가져온 자료예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L12_basic#5','kor',3,2,'u3','L12','g3_2_kor_u3_L12_basic','lesson_basic','K3-2-u3-C19',2,'match','auto','이용 설명서의 문단과 쓸 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u3-C19","difficulty":2,"kind":"match","stem":"이용 설명서의 문단과 쓸 내용을 알맞게 이으세요.","pairs":[{"l":"첫째 문단","r":"그곳이 어떤 곳이고 언제 쓸 수 있는지"},{"l":"둘째 문단","r":"들어가서 이용하는 차례"},{"l":"셋째 문단","r":"그곳에서 지킬 것"}],"mis":"K3-2-u3-X25","explanation":["읽는 사람이 궁금해할 차례예요.","어떤 곳 → 차례 → 지킬 것이에요.","한 사람이 한 덩어리씩 맡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L12_basic#6','kor',3,2,'u3','L12','g3_2_kor_u3_L12_basic','lesson_basic','K3-2-u3-C20',2,'mc','auto','‘-대’와 ‘-데’를 바르게 쓴 문장은 무엇인가요?',ARRAY['K3-2-u3-X29']::text[],false,'{"seq":6,"concept":"K3-2-u3-C20","difficulty":2,"kind":"mc","stem":"‘-대’와 ‘-데’를 바르게 쓴 문장은 무엇인가요?","options":[{"t":"언니가 그러는데 오늘 도서관이 문을 닫는대.","correct":true},{"t":"어제 가 보니 도서관이 아주 넓대.","mis":"K3-2-u3-X29"},{"t":"내가 먹어 보니 텃밭 상추가 맛있대.","mis":"K3-2-u3-X29"},{"t":"친구에게 들어 보니 그 책이 재미있데.","mis":"K3-2-u3-X29"}],"explanation":["겪었는지 들었는지 봐요.","언니에게 들은 말은 ‘-대’예요.","내가 겪은 것은 ‘-데’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L12_basic#7','kor',3,2,'u3','L12','g3_2_kor_u3_L12_basic','lesson_basic','K3-2-u3-C21',2,'match','auto','「도서관」 낱말 그물에서 떠오른 말과 그렇게 떠오른 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u3-C21","difficulty":2,"kind":"match","stem":"「도서관」 낱말 그물에서 떠오른 말과 그렇게 떠오른 까닭을 알맞게 이으세요.","pairs":[{"l":"책","r":"도서관에 있는 것"},{"l":"빌리기","r":"도서관에서 하는 일"},{"l":"조용히","r":"도서관에서 지킬 것"}],"mis":"K3-2-u3-X30","explanation":["그 말이 무엇을 가리키는지 봐요.","있는 것·하는 일·지킬 것이에요.","한 낱말도 여러 갈래예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L12_basic#8','kor',3,2,'u3','L12','g3_2_kor_u3_L12_basic','lesson_basic','K3-2-u3-C19',2,'mc','auto','모둠 설명서를 만들 때 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X02','K3-2-u3-X23','K3-2-u3-X28']::text[],false,'{"seq":8,"concept":"K3-2-u3-C19","difficulty":2,"kind":"mc","stem":"모둠 설명서를 만들 때 알맞은 것은 무엇인가요?","options":[{"t":"문 앞 안내판을 보고 적고, 출처에 안내판 이름을 쓴다","correct":true},{"t":"확인하지 않은 내용을 그럴듯하게 지어 쓴다","mis":"K3-2-u3-X02"},{"t":"출처 칸에는 아무 이름이나 적어 둔다","mis":"K3-2-u3-X23"},{"t":"사진은 가져온 곳을 적지 않는다","mis":"K3-2-u3-X28"}],"explanation":["확인한 것만 적어요.","가져온 곳도 적어요.","이 단원의 약속이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L12_basic#9','kor',3,2,'u3','L12','g3_2_kor_u3_L12_basic','lesson_basic','K3-2-u3-C20',2,'ox','auto','「친구에게 들어 보니 그 책이 아주 재미있대.」는 바르게 쓴 문장이에요.',ARRAY['K3-2-u3-X29']::text[],false,'{"seq":9,"concept":"K3-2-u3-C20","difficulty":2,"kind":"ox","stem":"「친구에게 들어 보니 그 책이 아주 재미있대.」는 바르게 쓴 문장이에요.","answer":"O","reason_options":[{"t":"친구에게 들은 말을 전하는 것이라 ‘-대’를 쓰기 때문에","correct":true},{"t":"‘보니’가 붙으면 언제나 ‘-데’를 써야 하기 때문에","mis":"K3-2-u3-X29"}],"mis":"K3-2-u3-X29","explanation":["‘보니’가 붙었어요.","그래도 친구에게 들은 말이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L12_basic#10','kor',3,2,'u3','L12','g3_2_kor_u3_L12_basic','lesson_basic','K3-2-u3-C19',3,'error','auto','모둠 글을 하나로 모으며 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X28','K3-2-u3-X16','K3-2-u3-X25']::text[],false,'{"seq":10,"concept":"K3-2-u3-C19","difficulty":3,"kind":"error","stem":"모둠 글을 하나로 모으며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「사진은 글이 아니니 가져온 곳을 안 적어도 돼.」","correct":true,"mis_target":"K3-2-u3-X28"},{"t":"친구 가 — 「문단 사이를 이어 주는 말로 이어 보자.」","mis":"K3-2-u3-X16"},{"t":"친구 나 — 「빠진 차례가 없는지 보고 출처는 끝에 모아 적자.」","mis":"K3-2-u3-X25"}],"explanation":["종류가 달라도 출처를 적어요.","사진도 가져온 자료예요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L12_challenge#1','kor',3,2,'u3','L12','g3_2_kor_u3_L12_challenge','lesson_challenge','K3-2-u3-C20',2,'sa','auto','「어제 텃밭에 가 보니 상추가 많이 자랐(　).」 빈칸에 ‘대’와 ‘데’ 가운데 알맞은 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u3-C20","difficulty":2,"kind":"sa","stem":"「어제 텃밭에 가 보니 상추가 많이 자랐(　).」 빈칸에 ‘대’와 ‘데’ 가운데 알맞은 글자를 쓰세요.","answer":["데"],"explanation":["누가 텃밭에 갔나요?","내가 가서 직접 봤어요.","‘데’예요."],"mis":"K3-2-u3-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L12_challenge#2','kor',3,2,'u3','L12','g3_2_kor_u3_L12_challenge','lesson_challenge','K3-2-u3-C21',2,'mc','auto','낱말 그물에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X30','K3-2-u3-X17']::text[],false,'{"seq":2,"concept":"K3-2-u3-C21","difficulty":2,"kind":"mc","stem":"낱말 그물에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"한 낱말에서 떠오르는 말이 여러 갈래로 뻗을 수 있다","correct":true},{"t":"한 낱말에서는 한 가지 말만 떠올려야 한다","mis":"K3-2-u3-X30"},{"t":"떠오른 까닭은 모두 같아야 한다","mis":"K3-2-u3-X30"},{"t":"낱말 그물에는 이어 주는 말만 쓴다","mis":"K3-2-u3-X17"}],"explanation":["도서관에서 책·빌리기·조용히가 나왔어요.","까닭이 저마다 달랐어요.","여러 갈래로 뻗어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L12_challenge#3','kor',3,2,'u3','L12','g3_2_kor_u3_L12_challenge','lesson_challenge','K3-2-u3-C20',3,'error','auto','‘-데’와 ‘-대’를 가르는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X29']::text[],false,'{"seq":3,"concept":"K3-2-u3-C20","difficulty":3,"kind":"error","stem":"‘-데’와 ‘-대’를 가르는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「‘보니’가 나오면 언제나 ‘-데’를 쓰면 돼.」","correct":true,"mis_target":"K3-2-u3-X29"},{"t":"친구 가 — 「내가 직접 겪어 안 것이면 ‘-데’야.」","mis":"K3-2-u3-X29"},{"t":"친구 나 — 「남에게 들은 말을 전하면 ‘-대’야.」","mis":"K3-2-u3-X29"}],"explanation":["‘들어 보니’도 있어요.","들은 말이면 ‘-대’예요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L12_challenge#4','kor',3,2,'u3','L12','g3_2_kor_u3_L12_challenge','lesson_challenge','K3-2-u3-C19',3,'mc','auto','「체육관 이용 설명서」를 1학년 동생도 알 수 있게 만들 때, 둘째 문단(이용하는 차례)에 들어갈 문장으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X25','K3-2-u3-X21']::text[],false,'{"seq":4,"concept":"K3-2-u3-C19","difficulty":3,"kind":"mc","stem":"「체육관 이용 설명서」를 1학년 동생도 알 수 있게 만들 때, 둘째 문단(이용하는 차례)에 들어갈 문장으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“먼저, 선생님과 함께 줄을 서서 들어갑니다.”","correct":true},{"t":"“체육관은 넓고 지붕이 있는 곳입니다.”","mis":"K3-2-u3-X25"},{"t":"“이 차례대로 하면 체육관을 안전하게 쓸 수 있습니다.”","mis":"K3-2-u3-X25"},{"t":"“체육관에서 노는 것이 가장 재미있습니다.”","mis":"K3-2-u3-X21"}],"explanation":["둘째 문단은 이용하는 차례예요.","「먼저」로 시작해요.","들어가는 차례를 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L12_challenge#5','kor',3,2,'u3','L12','g3_2_kor_u3_L12_challenge','lesson_challenge','K3-2-u3-C19',3,'ox','auto','이용 설명서를 모둠이 함께 만들 때에는 문단을 나누어 한 사람이 한 덩어리씩 맡을 수 있어요.',ARRAY['K3-2-u3-X28']::text[],false,'{"seq":5,"concept":"K3-2-u3-C19","difficulty":3,"kind":"ox","stem":"이용 설명서를 모둠이 함께 만들 때에는 문단을 나누어 한 사람이 한 덩어리씩 맡을 수 있어요.","answer":"O","reason_options":[{"t":"문단을 나누면 맡을 내용이 분명해지기 때문에","correct":true},{"t":"문단을 나누면 출처를 적지 않아도 되기 때문에","mis":"K3-2-u3-X28"}],"mis":"K3-2-u3-X28","explanation":["문단은 내용 덩어리예요.","나누면 맡기 쉬워요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L12_challenge#6','kor',3,2,'u3','L12','g3_2_kor_u3_L12_challenge','lesson_challenge','K3-2-u3-C12',3,'mc','auto','「새 책이 들어왔습니다. (　) 정리가 끝나지 않아 빌릴 수 없었습니다. (　) 다음 주에 다시 오기로 했습니다.」 빈칸에 알맞은 말을 차례대로 짝지은 것은 무엇인가요?',ARRAY['K3-2-u3-X16','K3-2-u3-X18']::text[],false,'{"seq":6,"concept":"K3-2-u3-C12","difficulty":3,"kind":"mc","stem":"「새 책이 들어왔습니다. (　) 정리가 끝나지 않아 빌릴 수 없었습니다. (　) 다음 주에 다시 오기로 했습니다.」 빈칸에 알맞은 말을 차례대로 짝지은 것은 무엇인가요?","options":[{"t":"그러나 · 그래서","correct":true},{"t":"그래서 · 그러나","mis":"K3-2-u3-X16"},{"t":"그리고 · 그리고","mis":"K3-2-u3-X18"},{"t":"그러나 · 그러나","mis":"K3-2-u3-X16"}],"explanation":["새 책과 못 빌림은 반대예요.","못 빌린 것이 다시 올 까닭이에요.","그러나 · 그래서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L12_challenge#7','kor',3,2,'u3','L12','g3_2_kor_u3_L12_challenge','lesson_challenge','K3-2-u3-C20',3,'match','auto','문장과 빈칸에 들어갈 알맞은 말을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u3-C20","difficulty":3,"kind":"match","stem":"문장과 빈칸에 들어갈 알맞은 말을 이으세요.","pairs":[{"l":"어제 가 보니 운동장이 아주 넓(　).","r":"넓데"},{"l":"짝이 그러는데 내일 비가 온(　).","r":"온대"},{"l":"친구에게 들어 보니 그 책이 재미있(　).","r":"재미있대"}],"mis":"K3-2-u3-X29","explanation":["겪었는지 들었는지 봐요.","‘들어 보니’는 들은 말이에요.","‘가 보니’는 내가 겪은 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L12_challenge#8','kor',3,2,'u3','L12','g3_2_kor_u3_L12_challenge','lesson_challenge','K3-2-u3-C21',4,'mc','auto','「텃밭」이라는 낱말로 낱말 그물을 만들었어요. 떠오른 말과 까닭을 가장 알맞게 짝지은 것은 무엇인가요?',ARRAY['K3-2-u3-X30','K3-2-u3-X17']::text[],false,'{"seq":8,"concept":"K3-2-u3-C21","difficulty":4,"kind":"mc","stem":"「텃밭」이라는 낱말로 낱말 그물을 만들었어요. 떠오른 말과 까닭을 가장 알맞게 짝지은 것은 무엇인가요?","options":[{"t":"물뿌리개 — 텃밭에서 쓰는 것 · 물 주기 — 텃밭에서 하는 일 · 상추 — 텃밭에서 가꾸는 것","correct":true},{"t":"물뿌리개 — 텃밭에서 하는 일 · 물 주기 — 텃밭에서 쓰는 것 · 상추 — 텃밭에서 지킬 것","mis":"K3-2-u3-X30"},{"t":"상추 · 상추 · 상추 — 한 갈래로만 떠올렸다","mis":"K3-2-u3-X30"},{"t":"그러나 — 이어 주는 말 · 그래서 — 까닭","mis":"K3-2-u3-X17"}],"explanation":["그 말이 무엇을 가리키는지 봐요.","쓰는 것·하는 일·가꾸는 것이에요.","여러 갈래로 뻗어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L12_challenge#9','kor',3,2,'u3','L12','g3_2_kor_u3_L12_challenge','lesson_challenge','K3-2-u3-C19',4,'essay','teacher','우리 학교에서 여러 반이 함께 쓰는 곳 하나를 골라, 1학년 동생을 위한 이용 설명서를 세 문단으로 어떻게 나눌지 쓰고, 자료를 가져온다면 출처를 어떻게 적을지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u3-C19","difficulty":4,"kind":"essay","stem":"우리 학교에서 여러 반이 함께 쓰는 곳 하나를 골라, 1학년 동생을 위한 이용 설명서를 세 문단으로 어떻게 나눌지 쓰고, 자료를 가져온다면 출처를 어떻게 적을지 쓰세요.","answer_guide":{"answer":"예: 고른 곳 — 도서관. 첫째 문단 — 도서관이 어떤 곳이고 언제 쓸 수 있는지. 둘째 문단 — 들어가서 책을 고르고 빌리는 차례. 셋째 문단 — 도서관에서 지킬 것(조용히 하기, 책을 제자리에 꽂기). 문 앞 안내판을 보고 적었다면 글 끝에 「■ 출처: 「이용 안내」, 도서관 앞 안내판」처럼 적겠다.","scoring_points":["함께 쓰는 곳을 골랐는가","세 문단에 들어갈 내용을 나누었는가","가져온 자료의 출처를 적는 방법을 썼는가"]},"explanation":["어떤 곳 → 차례 → 지킬 것이에요.","동생이 알 수 있게 써요.","확인한 것만, 출처와 함께요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_L12_challenge#10','kor',3,2,'u3','L12','g3_2_kor_u3_L12_challenge','lesson_challenge','K3-2-u3-C20',4,'essay','teacher','‘-데’와 ‘-대’를 하나씩 넣어 학교생활 문장을 만들고, 왜 그 말을 썼는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u3-C20","difficulty":4,"kind":"essay","stem":"‘-데’와 ‘-대’를 하나씩 넣어 학교생활 문장을 만들고, 왜 그 말을 썼는지 쓰세요.","answer_guide":{"answer":"예: 오늘 급식에 나온 국을 먹어 보니 맛있데. — 내가 직접 먹어 보고 안 것이라 ‘-데’를 썼다. 짝이 그러는데 내일 미술 시간에 찰흙을 쓴대. — 짝에게 들은 말을 전하는 것이라 ‘-대’를 썼다.","scoring_points":["‘-데’를 넣은 문장을 바르게 썼는가","‘-대’를 넣은 문장을 바르게 썼는가","겪은 것·들은 것으로 까닭을 썼는가"]},"explanation":["내가 겪은 일 하나를 떠올려요.","남에게 들은 말 하나를 떠올려요.","까닭으로 갈라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#1','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C1',1,'mc','auto','서진이의 글 「식판 정리하는 방법」은 어떤 글인가요?',ARRAY['K3-2-u3-X31','K3-2-u3-X21']::text[],false,'{"seq":1,"concept":"K3-2-u3-C1","difficulty":1,"kind":"mc","stem":"서진이의 글 「식판 정리하는 방법」은 어떤 글인가요?","options":[{"t":"식판을 정리하는 차례를 알려 주는 설명하는 글","correct":true},{"t":"급식이 맛있었던 느낌을 쓴 글","mis":"K3-2-u3-X31"},{"t":"있었던 일을 꾸며 쓴 이야기","mis":"K3-2-u3-X31"},{"t":"식판을 사 달라고 부탁하는 글","mis":"K3-2-u3-X21"}],"explanation":["무엇을 알려 주는지 봐요.","먼저·다음으로·끝으로가 있어요.","차례를 알려 주는 설명하는 글이에요."],"asset":{"type":"passage","lines":["급식을 다 먹은 뒤 식판을 정리하는 방법을 알려 드리겠습니다.","먼저, 남은 음식을 한쪽으로 모아 정해진 통에 덜어 냅니다.","다음으로, 숟가락과 젓가락을 수저 통에 넣습니다.","끝으로, 빈 식판을 정해진 곳에 포개어 놓습니다.","식판을 놓는 곳은 「급식실 이용 안내」에 그림으로 나와 있습니다.","이 차례대로 하면 급식실을 깨끗하게 쓸 수 있습니다.","■ 출처: 「급식실 이용 안내」, 학교 누리집."],"title":"학급 신문 「식판 정리하는 방법」 — 글 서진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#2','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C3',1,'mc','auto','출처는 무엇을 알려 주나요?',ARRAY['K3-2-u3-X03']::text[],false,'{"seq":2,"concept":"K3-2-u3-C3","difficulty":1,"kind":"mc","stem":"출처는 무엇을 알려 주나요?","options":[{"t":"자료를 가져온 곳","correct":true},{"t":"글을 쓴 날짜","mis":"K3-2-u3-X03"},{"t":"글이 몇 쪽인지","mis":"K3-2-u3-X03"},{"t":"글을 쓴 사람의 나이","mis":"K3-2-u3-X03"}],"explanation":["출처는 자료가 온 곳이에요.","만든 곳이나 자료 이름이에요.","날짜·쪽수가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#3','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C5',1,'mc','auto','출처를 밝히지 않고 책에서 찾은 내용을 쓰면 어떤 문제가 생기나요?',ARRAY['K3-2-u3-X05','K3-2-u3-X01']::text[],false,'{"seq":3,"concept":"K3-2-u3-C5","difficulty":1,"kind":"mc","stem":"출처를 밝히지 않고 책에서 찾은 내용을 쓰면 어떤 문제가 생기나요?","options":[{"t":"책을 만든 사람의 것을 내 것처럼 쓴 셈이 된다","correct":true},{"t":"글이 너무 짧아진다","mis":"K3-2-u3-X05"},{"t":"글씨가 작아진다","mis":"K3-2-u3-X01"},{"t":"글이 어려워진다","mis":"K3-2-u3-X05"}],"explanation":["책을 만든 사람이 있어요.","밝히지 않으면 내 것처럼 보여요.","그래서 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#4','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C6',1,'mc','auto','민결이가 하고 싶은 말은 무엇인가요?',ARRAY['K3-2-u3-X08']::text[],false,'{"seq":4,"concept":"K3-2-u3-C6","difficulty":1,"kind":"mc","stem":"민결이가 하고 싶은 말은 무엇인가요?","options":[{"t":"놀이 기구는 차례를 지켜 타자","correct":true},{"t":"놀이 기구를 타지 말자","mis":"K3-2-u3-X08"},{"t":"놀이 기구는 빨리 타자","mis":"K3-2-u3-X08"},{"t":"미끄럼틀만 타자","mis":"K3-2-u3-X08"}],"explanation":["마지막 줄을 다시 읽어요.","차례를 지켜 타자고 했어요.","그것이 의견이에요."],"asset":{"type":"passage","lines":["놀이 기구를 탈 때에는 차례를 지켜야 합니다. 한꺼번에 몰리면 부딪치기 쉽기 때문입니다.","㉮ 옆 반 친구에게 들으니 미끄럼틀 앞에서 다툰 일이 있었다고 합니다.","㉯ 운동장 앞 「놀이 기구 이용 안내」 안내판에 따르면,","한 사람씩 차례대로 타야 한다고 합니다.","㉰ [그림] 미끄럼틀 앞에 한 줄로 서 있는 모습을 그린 그림","㉱ [그림] 그네 둘레에 그어 둔 선을 나타낸 그림","■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","우리 모두 놀이 기구는 차례를 지켜 타요."],"title":"주장하는 글 「놀이 기구는 차례를 지켜 타요」 — 글 민결"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#5','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C8',1,'mc','auto','민결이 글에서 「놀이 기구 이용 안내」라는 출처가 적힌 ㉯를 읽는 알맞은 태도는 무엇인가요?',ARRAY['K3-2-u3-X12','K3-2-u3-X13','K3-2-u3-X10']::text[],false,'{"seq":5,"concept":"K3-2-u3-C8","difficulty":1,"kind":"mc","stem":"민결이 글에서 「놀이 기구 이용 안내」라는 출처가 적힌 ㉯를 읽는 알맞은 태도는 무엇인가요?","options":[{"t":"운동장 앞 안내판이 어떤 곳인지 살펴보고 생각하며 읽는다","correct":true},{"t":"출처가 있으니 더 볼 것 없이 믿는다","mis":"K3-2-u3-X12"},{"t":"출처가 있어도 거짓일 수 있으니 믿지 않는다","mis":"K3-2-u3-X13"},{"t":"출처는 읽지 않고 넘어간다","mis":"K3-2-u3-X10"}],"explanation":["출처가 있다고 다 맞지는 않아요.","다 틀린 것도 아니에요.","살펴보고 생각해요."],"asset":{"type":"passage","lines":["놀이 기구를 탈 때에는 차례를 지켜야 합니다. 한꺼번에 몰리면 부딪치기 쉽기 때문입니다.","㉮ 옆 반 친구에게 들으니 미끄럼틀 앞에서 다툰 일이 있었다고 합니다.","㉯ 운동장 앞 「놀이 기구 이용 안내」 안내판에 따르면,","한 사람씩 차례대로 타야 한다고 합니다.","㉰ [그림] 미끄럼틀 앞에 한 줄로 서 있는 모습을 그린 그림","㉱ [그림] 그네 둘레에 그어 둔 선을 나타낸 그림","■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","우리 모두 놀이 기구는 차례를 지켜 타요."],"title":"주장하는 글 「놀이 기구는 차례를 지켜 타요」 — 글 민결"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#6','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C12',1,'blank','auto','이야기 「모둠 화분」의 ㉠에 알맞은 이어 주는 말은 무엇인가요?',ARRAY['K3-2-u3-X16','K3-2-u3-X17']::text[],false,'{"seq":6,"concept":"K3-2-u3-C12","difficulty":1,"kind":"blank","stem":"이야기 「모둠 화분」의 ㉠에 알맞은 이어 주는 말은 무엇인가요?","options":[{"t":"그러나","correct":true},{"t":"그래서","mis":"K3-2-u3-X16"},{"t":"그리고","mis":"K3-2-u3-X16"},{"t":"금요일에는","mis":"K3-2-u3-X17"}],"explanation":["아침마다 하기로 했어요.","그런데 잊었어요.","반대라서 그러나예요."],"asset":{"type":"passage","lines":["다올이네 모둠은 교실 화분을 맡았습니다.","모둠 친구들은 아침마다 흙을 만져 보기로 했습니다.","( ㉠ ) 금요일에는 모두 깜빡 잊고 말았습니다.","( ㉡ ) 월요일 아침, 흙이 바싹 말라 있었습니다.","다올이는 잎이 아니라 흙 쪽으로 천천히 물을 주었습니다.","( ㉢ ) 물받이에 고인 물도 비웠습니다.","며칠 뒤, 처졌던 잎이 다시 고개를 들었습니다."],"title":"이야기 「모둠 화분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#7','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C14',1,'mc','auto','「식판 정리하는 방법」을 쓰기 전에 서진이가 먼저 정했을 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X20']::text[],false,'{"seq":7,"concept":"K3-2-u3-C14","difficulty":1,"kind":"mc","stem":"「식판 정리하는 방법」을 쓰기 전에 서진이가 먼저 정했을 것으로 알맞은 것은 무엇인가요?","options":[{"t":"읽을 사람과 쓰는 목적","correct":true},{"t":"글씨 색깔","mis":"K3-2-u3-X20"},{"t":"글자 수","mis":"K3-2-u3-X20"},{"t":"제목 무늬","mis":"K3-2-u3-X20"}],"explanation":["쓰기 전에 정할 것이 있어요.","누가 왜 읽을지예요.","꾸미기는 나중이에요."],"asset":{"type":"passage","lines":["급식을 다 먹은 뒤 식판을 정리하는 방법을 알려 드리겠습니다.","먼저, 남은 음식을 한쪽으로 모아 정해진 통에 덜어 냅니다.","다음으로, 숟가락과 젓가락을 수저 통에 넣습니다.","끝으로, 빈 식판을 정해진 곳에 포개어 놓습니다.","식판을 놓는 곳은 「급식실 이용 안내」에 그림으로 나와 있습니다.","이 차례대로 하면 급식실을 깨끗하게 쓸 수 있습니다.","■ 출처: 「급식실 이용 안내」, 학교 누리집."],"title":"학급 신문 「식판 정리하는 방법」 — 글 서진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#8','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C20',1,'mc','auto','내가 직접 겪어 안 것을 말할 때 쓰는 말은 무엇인가요?',ARRAY['K3-2-u3-X29']::text[],false,'{"seq":8,"concept":"K3-2-u3-C20","difficulty":1,"kind":"mc","stem":"내가 직접 겪어 안 것을 말할 때 쓰는 말은 무엇인가요?","options":[{"t":"‘-데’","correct":true},{"t":"‘-대’","mis":"K3-2-u3-X29"},{"t":"‘-고’","mis":"K3-2-u3-X29"},{"t":"‘-요’","mis":"K3-2-u3-X29"}],"explanation":["‘-데’는 내가 겪은 것이에요.","‘-대’는 들은 말이에요.","‘-데’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#9','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C4',2,'mc','auto','민결이 글에서 출처를 글 속 문장 안에 밝힌 자료는 무엇인가요?',ARRAY['K3-2-u3-X09','K3-2-u3-X04']::text[],false,'{"seq":9,"concept":"K3-2-u3-C4","difficulty":2,"kind":"mc","stem":"민결이 글에서 출처를 글 속 문장 안에 밝힌 자료는 무엇인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"K3-2-u3-X09"},{"t":"㉰","mis":"K3-2-u3-X09"},{"t":"㉱","mis":"K3-2-u3-X04"}],"explanation":["「…에 따르면」을 찾아요.","㉯ 줄에 있어요.","㉱는 그림 아래예요."],"asset":{"type":"passage","lines":["놀이 기구를 탈 때에는 차례를 지켜야 합니다. 한꺼번에 몰리면 부딪치기 쉽기 때문입니다.","㉮ 옆 반 친구에게 들으니 미끄럼틀 앞에서 다툰 일이 있었다고 합니다.","㉯ 운동장 앞 「놀이 기구 이용 안내」 안내판에 따르면,","한 사람씩 차례대로 타야 한다고 합니다.","㉰ [그림] 미끄럼틀 앞에 한 줄로 서 있는 모습을 그린 그림","㉱ [그림] 그네 둘레에 그어 둔 선을 나타낸 그림","■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","우리 모두 놀이 기구는 차례를 지켜 타요."],"title":"주장하는 글 「놀이 기구는 차례를 지켜 타요」 — 글 민결"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#10','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C6',2,'mc','auto','민결이 글에서 출처가 있는 자료를 바르게 고른 것은 무엇인가요?',ARRAY['K3-2-u3-X09']::text[],false,'{"seq":10,"concept":"K3-2-u3-C6","difficulty":2,"kind":"mc","stem":"민결이 글에서 출처가 있는 자료를 바르게 고른 것은 무엇인가요?","options":[{"t":"㉯와 ㉱","correct":true},{"t":"㉮와 ㉰","mis":"K3-2-u3-X09"},{"t":"㉮와 ㉯","mis":"K3-2-u3-X09"},{"t":"㉰와 ㉱","mis":"K3-2-u3-X09"}],"explanation":["가져온 곳이 적혀 있는지 봐요.","㉯는 안내판, ㉱는 안내장이에요.","㉮·㉰는 없어요."],"asset":{"type":"passage","lines":["놀이 기구를 탈 때에는 차례를 지켜야 합니다. 한꺼번에 몰리면 부딪치기 쉽기 때문입니다.","㉮ 옆 반 친구에게 들으니 미끄럼틀 앞에서 다툰 일이 있었다고 합니다.","㉯ 운동장 앞 「놀이 기구 이용 안내」 안내판에 따르면,","한 사람씩 차례대로 타야 한다고 합니다.","㉰ [그림] 미끄럼틀 앞에 한 줄로 서 있는 모습을 그린 그림","㉱ [그림] 그네 둘레에 그어 둔 선을 나타낸 그림","■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","우리 모두 놀이 기구는 차례를 지켜 타요."],"title":"주장하는 글 「놀이 기구는 차례를 지켜 타요」 — 글 민결"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#11','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C7',2,'mc','auto','민결이 글의 ㉰처럼 출처가 없는 그림의 아쉬운 점은 무엇인가요?',ARRAY['K3-2-u3-X11']::text[],false,'{"seq":11,"concept":"K3-2-u3-C7","difficulty":2,"kind":"mc","stem":"민결이 글의 ㉰처럼 출처가 없는 그림의 아쉬운 점은 무엇인가요?","options":[{"t":"어디에서 가져왔는지 몰라 더 알고 싶어도 찾아볼 곳이 없다","correct":true},{"t":"그림이 작아진다","mis":"K3-2-u3-X11"},{"t":"글이 짧아진다","mis":"K3-2-u3-X11"},{"t":"낱말이 어려워진다","mis":"K3-2-u3-X11"}],"explanation":["㉰ 아래에는 아무 글도 없어요.","어디서 왔는지 몰라요.","찾아볼 곳이 없어요."],"asset":{"type":"passage","lines":["놀이 기구를 탈 때에는 차례를 지켜야 합니다. 한꺼번에 몰리면 부딪치기 쉽기 때문입니다.","㉮ 옆 반 친구에게 들으니 미끄럼틀 앞에서 다툰 일이 있었다고 합니다.","㉯ 운동장 앞 「놀이 기구 이용 안내」 안내판에 따르면,","한 사람씩 차례대로 타야 한다고 합니다.","㉰ [그림] 미끄럼틀 앞에 한 줄로 서 있는 모습을 그린 그림","㉱ [그림] 그네 둘레에 그어 둔 선을 나타낸 그림","■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","우리 모두 놀이 기구는 차례를 지켜 타요."],"title":"주장하는 글 「놀이 기구는 차례를 지켜 타요」 — 글 민결"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#12','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C10',2,'mc','auto','「텃밭을 가꾸다」에서 「가꾸다」와 뜻이 가장 비슷한 말은 무엇인가요?',ARRAY['K3-2-u3-X15']::text[],false,'{"seq":12,"concept":"K3-2-u3-C10","difficulty":2,"kind":"mc","stem":"「텃밭을 가꾸다」에서 「가꾸다」와 뜻이 가장 비슷한 말은 무엇인가요?","options":[{"t":"보살피다","correct":true},{"t":"준비하다","mis":"K3-2-u3-X15"},{"t":"돌아오다","mis":"K3-2-u3-X15"},{"t":"뜯다","mis":"K3-2-u3-X15"}],"explanation":["잘 자라도록 해요.","돌보는 일이에요.","보살피다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#13','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C12',2,'mc','auto','「모둠 화분」에서 ㉡의 앞 문장과 뒤 문장은 어떤 관계인가요?',ARRAY['K3-2-u3-X16','K3-2-u3-X19']::text[],false,'{"seq":13,"concept":"K3-2-u3-C12","difficulty":2,"kind":"mc","stem":"「모둠 화분」에서 ㉡의 앞 문장과 뒤 문장은 어떤 관계인가요?","options":[{"t":"앞(모두 깜빡 잊음)이 뒤(흙이 바싹 마름)의 까닭이다","correct":true},{"t":"앞과 반대되는 내용이다","mis":"K3-2-u3-X16"},{"t":"앞과 비슷한 내용이다","mis":"K3-2-u3-X16"},{"t":"아무 관계가 없다","mis":"K3-2-u3-X19"}],"explanation":["흙이 왜 말랐을까요?","아무도 만져 보지 않았어요.","앞이 까닭이에요."],"asset":{"type":"passage","lines":["다올이네 모둠은 교실 화분을 맡았습니다.","모둠 친구들은 아침마다 흙을 만져 보기로 했습니다.","( ㉠ ) 금요일에는 모두 깜빡 잊고 말았습니다.","( ㉡ ) 월요일 아침, 흙이 바싹 말라 있었습니다.","다올이는 잎이 아니라 흙 쪽으로 천천히 물을 주었습니다.","( ㉢ ) 물받이에 고인 물도 비웠습니다.","며칠 뒤, 처졌던 잎이 다시 고개를 들었습니다."],"title":"이야기 「모둠 화분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#14','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C15',2,'mc','auto','서진이가 차례를 드러내려고 쓴 말끼리 묶은 것은 무엇인가요?',ARRAY['K3-2-u3-X16','K3-2-u3-X17','K3-2-u3-X04']::text[],false,'{"seq":14,"concept":"K3-2-u3-C15","difficulty":2,"kind":"mc","stem":"서진이가 차례를 드러내려고 쓴 말끼리 묶은 것은 무엇인가요?","options":[{"t":"먼저 · 다음으로 · 끝으로","correct":true},{"t":"그러나 · 그래서 · 그리고","mis":"K3-2-u3-X16"},{"t":"식판 · 수저 · 통","mis":"K3-2-u3-X17"},{"t":"급식 · 누리집 · 출처","mis":"K3-2-u3-X04"}],"explanation":["문장 맨 앞을 봐요.","무엇부터 할지 알려 줘요.","먼저·다음으로·끝으로예요."],"asset":{"type":"passage","lines":["급식을 다 먹은 뒤 식판을 정리하는 방법을 알려 드리겠습니다.","먼저, 남은 음식을 한쪽으로 모아 정해진 통에 덜어 냅니다.","다음으로, 숟가락과 젓가락을 수저 통에 넣습니다.","끝으로, 빈 식판을 정해진 곳에 포개어 놓습니다.","식판을 놓는 곳은 「급식실 이용 안내」에 그림으로 나와 있습니다.","이 차례대로 하면 급식실을 깨끗하게 쓸 수 있습니다.","■ 출처: 「급식실 이용 안내」, 학교 누리집."],"title":"학급 신문 「식판 정리하는 방법」 — 글 서진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#15','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C16',2,'mc','auto','서진이가 「식판 놓는 곳」을 「급식실 이용 안내」에서 알아냈어요. 알맞게 쓴 방법은 무엇인가요?',ARRAY['K3-2-u3-X06','K3-2-u3-X07','K3-2-u3-X23']::text[],false,'{"seq":15,"concept":"K3-2-u3-C16","difficulty":2,"kind":"mc","stem":"서진이가 「식판 놓는 곳」을 「급식실 이용 안내」에서 알아냈어요. 알맞게 쓴 방법은 무엇인가요?","options":[{"t":"그 내용을 쓰고 글 끝에 가져온 곳을 밝혔다","correct":true},{"t":"내가 원래 알던 것처럼 썼다","mis":"K3-2-u3-X06"},{"t":"찾아본 내용이라 뺐다","mis":"K3-2-u3-X07"},{"t":"그럴듯한 책 이름을 지어 적었다","mis":"K3-2-u3-X23"}],"explanation":["찾아본 내용도 쓸 수 있어요.","가져온 곳을 밝혀요.","글 끝에 밝혔어요."],"asset":{"type":"passage","lines":["급식을 다 먹은 뒤 식판을 정리하는 방법을 알려 드리겠습니다.","먼저, 남은 음식을 한쪽으로 모아 정해진 통에 덜어 냅니다.","다음으로, 숟가락과 젓가락을 수저 통에 넣습니다.","끝으로, 빈 식판을 정해진 곳에 포개어 놓습니다.","식판을 놓는 곳은 「급식실 이용 안내」에 그림으로 나와 있습니다.","이 차례대로 하면 급식실을 깨끗하게 쓸 수 있습니다.","■ 출처: 「급식실 이용 안내」, 학교 누리집."],"title":"학급 신문 「식판 정리하는 방법」 — 글 서진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#16','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C18',2,'mc','auto','쓴 글을 점검하는 까닭은 무엇인가요?',ARRAY['K3-2-u3-X26','K3-2-u3-X27']::text[],false,'{"seq":16,"concept":"K3-2-u3-C18","difficulty":2,"kind":"mc","stem":"쓴 글을 점검하는 까닭은 무엇인가요?","options":[{"t":"고칠 곳을 찾아 더 알기 쉬운 글로 만들려고","correct":true},{"t":"점검표 칸을 다 채우려고","mis":"K3-2-u3-X26"},{"t":"점수를 매기려고","mis":"K3-2-u3-X26"},{"t":"친구 글과 똑같게 만들려고","mis":"K3-2-u3-X27"}],"explanation":["채우려는 것이 아니에요.","고치려고 봐요.","알기 쉬운 글로 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#17','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C1',3,'error','auto','하선이의 딱지 접는 글을 고치는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X01']::text[],false,'{"seq":17,"concept":"K3-2-u3-C1","difficulty":3,"kind":"error","stem":"하선이의 딱지 접는 글을 고치는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「글씨를 크게 쓰면 도영이가 따라 할 수 있을 거야.」","correct":true,"mis_target":"K3-2-u3-X01"},{"t":"친구 가 — 「「먼저」·「다음으로」를 넣어 차례를 보이자.」","mis":"K3-2-u3-X01"},{"t":"친구 나 — 「「또 접어」를 어느 쪽으로 접는지 자세히 쓰자.」","mis":"K3-2-u3-X01"}],"explanation":["도영이는 차례를 몰랐어요.","글씨 크기는 상관없어요.","친구 다가 잘못 말했어요."],"asset":{"type":"speech","turns":[{"who":"하선","text":"“딱지 접는 방법을 알려 줄게. 색종이를 반으로 접어. 그리고 또 접어. 그다음에 끼우면 돼.”"},{"who":"도영","text":"읽어 봤는데 무엇을 먼저 해야 하는지 모르겠어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#18','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C8',3,'error','auto','민결이 글의 자료를 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X12','K3-2-u3-X14','K3-2-u3-X11']::text[],false,'{"seq":18,"concept":"K3-2-u3-C8","difficulty":3,"kind":"error","stem":"민결이 글의 자료를 두고 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「㉯는 안내판이라고 적혀 있으니 더 볼 것도 없이 맞아.」","correct":true,"mis_target":"K3-2-u3-X12"},{"t":"친구 가 — 「㉯는 운동장 앞에 가서 안내판을 확인해 볼 수 있어.」","mis":"K3-2-u3-X14"},{"t":"친구 다 — 「㉮는 들은 이야기라 어디서 확인할지 알 수 없어.」","mis":"K3-2-u3-X11"}],"explanation":["출처가 있다고 다 맞지 않아요.","살펴보고 생각해요.","친구 나가 알맞지 않아요."],"asset":{"type":"passage","lines":["놀이 기구를 탈 때에는 차례를 지켜야 합니다. 한꺼번에 몰리면 부딪치기 쉽기 때문입니다.","㉮ 옆 반 친구에게 들으니 미끄럼틀 앞에서 다툰 일이 있었다고 합니다.","㉯ 운동장 앞 「놀이 기구 이용 안내」 안내판에 따르면,","한 사람씩 차례대로 타야 한다고 합니다.","㉰ [그림] 미끄럼틀 앞에 한 줄로 서 있는 모습을 그린 그림","㉱ [그림] 그네 둘레에 그어 둔 선을 나타낸 그림","■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","우리 모두 놀이 기구는 차례를 지켜 타요."],"title":"주장하는 글 「놀이 기구는 차례를 지켜 타요」 — 글 민결"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#19','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C9',3,'mc','auto','「우리 학교 텃밭」처럼 출처에 밑줄이 없는 글에서 출처를 스스로 찾는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X03','K3-2-u3-X09']::text[],false,'{"seq":19,"concept":"K3-2-u3-C9","difficulty":3,"kind":"mc","stem":"「우리 학교 텃밭」처럼 출처에 밑줄이 없는 글에서 출처를 스스로 찾는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"「…에 따르면」이나 「■ 출처」처럼 가져온 곳을 밝힌 말을 찾는다","correct":true},{"t":"글쓴이 이름을 찾는다","mis":"K3-2-u3-X03"},{"t":"가장 긴 문장을 찾는다","mis":"K3-2-u3-X09"},{"t":"그림만 찾는다","mis":"K3-2-u3-X09"}],"explanation":["표시가 없어도 찾을 수 있어요.","가져온 곳을 밝힌 말이 있어요.","그 말을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#20','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C12',3,'error','auto','「모둠 화분」의 이어 주는 말을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X16']::text[],false,'{"seq":20,"concept":"K3-2-u3-C12","difficulty":3,"kind":"error","stem":"「모둠 화분」의 이어 주는 말을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「㉠에 「그래서」를 넣어도 뜻이 똑같아.」","correct":true,"mis_target":"K3-2-u3-X16"},{"t":"친구 가 — 「㉠은 아침마다 하기로 한 것과 반대되는 일이라 「그러나」야.」","mis":"K3-2-u3-X16"},{"t":"친구 나 — 「㉢은 물을 준 일에 비우는 일을 더하니 「그리고」야.」","mis":"K3-2-u3-X16"}],"explanation":["㉠ 앞뒤는 반대예요.","「그래서」는 까닭일 때 써요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["다올이네 모둠은 교실 화분을 맡았습니다.","모둠 친구들은 아침마다 흙을 만져 보기로 했습니다.","( ㉠ ) 금요일에는 모두 깜빡 잊고 말았습니다.","( ㉡ ) 월요일 아침, 흙이 바싹 말라 있었습니다.","다올이는 잎이 아니라 흙 쪽으로 천천히 물을 주었습니다.","( ㉢ ) 물받이에 고인 물도 비웠습니다.","며칠 뒤, 처졌던 잎이 다시 고개를 들었습니다."],"title":"이야기 「모둠 화분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#21','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C17',3,'mc','auto','서진이 글을 처음·가운데·끝으로 나눌 때 가운데에 들어가는 문장끼리 묶은 것은 무엇인가요?',ARRAY['K3-2-u3-X25']::text[],false,'{"seq":21,"concept":"K3-2-u3-C17","difficulty":3,"kind":"mc","stem":"서진이 글을 처음·가운데·끝으로 나눌 때 가운데에 들어가는 문장끼리 묶은 것은 무엇인가요?","options":[{"t":"「먼저…」·「다음으로…」·「끝으로…」 문장","correct":true},{"t":"첫 문장과 「이 차례대로 하면…」 문장","mis":"K3-2-u3-X25"},{"t":"「■ 출처」와 첫 문장","mis":"K3-2-u3-X25"},{"t":"「이 차례대로 하면…」 문장만","mis":"K3-2-u3-X25"}],"explanation":["가운데는 차례와 방법이에요.","차례 말이 붙은 문장이에요.","셋이 가운데예요."],"asset":{"type":"passage","lines":["급식을 다 먹은 뒤 식판을 정리하는 방법을 알려 드리겠습니다.","먼저, 남은 음식을 한쪽으로 모아 정해진 통에 덜어 냅니다.","다음으로, 숟가락과 젓가락을 수저 통에 넣습니다.","끝으로, 빈 식판을 정해진 곳에 포개어 놓습니다.","식판을 놓는 곳은 「급식실 이용 안내」에 그림으로 나와 있습니다.","이 차례대로 하면 급식실을 깨끗하게 쓸 수 있습니다.","■ 출처: 「급식실 이용 안내」, 학교 누리집."],"title":"학급 신문 「식판 정리하는 방법」 — 글 서진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#22','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C20',3,'error','auto','‘-데’와 ‘-대’를 넣어 문장을 썼어요. 잘못 쓴 친구는 누구인가요?',ARRAY['K3-2-u3-X29']::text[],false,'{"seq":22,"concept":"K3-2-u3-C20","difficulty":3,"kind":"error","stem":"‘-데’와 ‘-대’를 넣어 문장을 썼어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"친구 다 — 「내가 해 보니 식판 정리가 쉽대.」","correct":true,"mis_target":"K3-2-u3-X29"},{"t":"친구 가 — 「서진이가 그러는데 수저 통은 따로 있대.」","mis":"K3-2-u3-X29"},{"t":"친구 나 — 「어제 운동장에 가 보니 그네가 높데.」","mis":"K3-2-u3-X29"}],"explanation":["누가 겪었는지 봐요.","내가 해 본 것은 ‘-데’예요.","친구 다가 잘못 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#23','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C8',4,'mc','auto','민결이 글의 ㉯를 읽은 친구가 「안내판에 따르면 한 사람씩 탄대. 그런데 진짜일까?」라고 했어요. 이 친구에게 해 줄 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X12','K3-2-u3-X13','K3-2-u3-X14']::text[],false,'{"seq":23,"concept":"K3-2-u3-C8","difficulty":4,"kind":"mc","stem":"민결이 글의 ㉯를 읽은 친구가 「안내판에 따르면 한 사람씩 탄대. 그런데 진짜일까?」라고 했어요. 이 친구에게 해 줄 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“운동장 앞에 가서 안내판을 같이 살펴보자. 확인하면 알 수 있어.”","correct":true},{"t":"“출처가 있으니 의심하지 마.”","mis":"K3-2-u3-X12"},{"t":"“출처가 있어도 거짓일 수 있으니 믿지 마.”","mis":"K3-2-u3-X13"},{"t":"“안내판이라는 이름이 그럴듯하니 맞아.”","mis":"K3-2-u3-X14"}],"explanation":["친구는 살펴보려고 해요.","출처는 학교 안에 있어요.","함께 가서 확인해요."],"asset":{"type":"passage","lines":["놀이 기구를 탈 때에는 차례를 지켜야 합니다. 한꺼번에 몰리면 부딪치기 쉽기 때문입니다.","㉮ 옆 반 친구에게 들으니 미끄럼틀 앞에서 다툰 일이 있었다고 합니다.","㉯ 운동장 앞 「놀이 기구 이용 안내」 안내판에 따르면,","한 사람씩 차례대로 타야 한다고 합니다.","㉰ [그림] 미끄럼틀 앞에 한 줄로 서 있는 모습을 그린 그림","㉱ [그림] 그네 둘레에 그어 둔 선을 나타낸 그림","■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","우리 모두 놀이 기구는 차례를 지켜 타요."],"title":"주장하는 글 「놀이 기구는 차례를 지켜 타요」 — 글 민결"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#24','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C6',4,'essay','teacher','민결이 글의 자료 ㉮~㉱를 출처가 있는 것과 없는 것으로 나누고, 출처가 없는 자료를 어떻게 고치면 좋을지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u3-C6","difficulty":4,"kind":"essay","stem":"민결이 글의 자료 ㉮~㉱를 출처가 있는 것과 없는 것으로 나누고, 출처가 없는 자료를 어떻게 고치면 좋을지 쓰세요.","answer_guide":{"answer":"예: 출처가 있는 것 — ㉯(운동장 앞 「놀이 기구 이용 안내」 안내판), ㉱(「놀이터에서 지킬 것」, 보건실 안내장). 출처가 없는 것 — ㉮(옆 반 친구에게 들은 이야기), ㉰(한 줄로 선 그림). ㉰는 그림을 가져온 곳을 확인해 그림 아래에 적고, 내가 그린 그림이면 그렇다고 밝힌다. ㉮는 확인할 수 있는 안내판이나 안내장에서 같은 내용을 찾아 출처와 함께 쓰거나, 확인할 수 없으면 뺀다.","scoring_points":["출처가 있는 자료와 없는 자료를 바르게 나누었는가","출처가 없는 자료를 고치는 방법을 썼는가","확인할 수 없으면 빼거나 지어내지 않는다고 썼는가"]},"explanation":["자료마다 옆과 아래를 봐요.","있는 것과 없는 것을 갈라요.","없는 것은 확인하거나 빼요."],"asset":{"type":"passage","lines":["놀이 기구를 탈 때에는 차례를 지켜야 합니다. 한꺼번에 몰리면 부딪치기 쉽기 때문입니다.","㉮ 옆 반 친구에게 들으니 미끄럼틀 앞에서 다툰 일이 있었다고 합니다.","㉯ 운동장 앞 「놀이 기구 이용 안내」 안내판에 따르면,","한 사람씩 차례대로 타야 한다고 합니다.","㉰ [그림] 미끄럼틀 앞에 한 줄로 서 있는 모습을 그린 그림","㉱ [그림] 그네 둘레에 그어 둔 선을 나타낸 그림","■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","우리 모두 놀이 기구는 차례를 지켜 타요."],"title":"주장하는 글 「놀이 기구는 차례를 지켜 타요」 — 글 민결"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_a#25','kor',3,2,'u3','','g3_2_kor_u3_review_a','unit_review','K3-2-u3-C8',4,'essay','teacher','이 단원에서 두 번 만난 물음 「출처가 적혀 있는 자료는 어떻게 읽어야 할까요?」에 답하고, 민결이 글의 ㉯를 예로 들어 그렇게 읽는 방법을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u3-C8","difficulty":4,"kind":"essay","stem":"이 단원에서 두 번 만난 물음 「출처가 적혀 있는 자료는 어떻게 읽어야 할까요?」에 답하고, 민결이 글의 ㉯를 예로 들어 그렇게 읽는 방법을 쓰세요.","answer_guide":{"answer":"예: 출처가 적혀 있다고 다 맞는 것도, 다 거짓인 것도 아니니 어떤 곳에서 가져왔는지 살펴보고 생각하며 읽어야 한다. ㉯는 운동장 앞 「놀이 기구 이용 안내」 안내판이 출처라서, 운동장 앞에 가서 안내판에 정말 그렇게 적혀 있는지 보고 생각해 볼 수 있다.","scoring_points":["함부로 믿지도 의심하지도 않는다고 썼는가","어떤 곳인지 살펴보고 생각한다고 썼는가","㉯를 예로 들어 확인하는 방법을 썼는가"]},"explanation":["3~4차시와 14차시의 물음이에요.","출처는 살펴볼 수 있다는 표예요.","㉯는 가서 볼 수 있어요."],"asset":{"type":"passage","lines":["놀이 기구를 탈 때에는 차례를 지켜야 합니다. 한꺼번에 몰리면 부딪치기 쉽기 때문입니다.","㉮ 옆 반 친구에게 들으니 미끄럼틀 앞에서 다툰 일이 있었다고 합니다.","㉯ 운동장 앞 「놀이 기구 이용 안내」 안내판에 따르면,","한 사람씩 차례대로 타야 한다고 합니다.","㉰ [그림] 미끄럼틀 앞에 한 줄로 서 있는 모습을 그린 그림","㉱ [그림] 그네 둘레에 그어 둔 선을 나타낸 그림","■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","우리 모두 놀이 기구는 차례를 지켜 타요."],"title":"주장하는 글 「놀이 기구는 차례를 지켜 타요」 — 글 민결"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#1','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C1',1,'ox','auto','설명하는 글은 읽는 사람이 그대로 따라 할 수 있도록 써야 해요.',ARRAY['K3-2-u3-X31']::text[],false,'{"seq":1,"concept":"K3-2-u3-C1","difficulty":1,"kind":"ox","stem":"설명하는 글은 읽는 사람이 그대로 따라 할 수 있도록 써야 해요.","answer":"O","reason_options":[{"t":"설명하는 글은 일의 차례와 방법을 알려 주는 글이기 때문에","correct":true},{"t":"설명하는 글은 내 느낌을 자세히 쓰는 글이기 때문에","mis":"K3-2-u3-X31"}],"mis":"K3-2-u3-X31","explanation":["설명하는 글은 무엇을 알려 줘요.","읽는 사람이 해 볼 수 있어야 해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#2','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C3',1,'mc','auto','「식판 정리하는 방법」의 출처는 무엇인가요?',ARRAY['K3-2-u3-X03','K3-2-u3-X08']::text[],false,'{"seq":2,"concept":"K3-2-u3-C3","difficulty":1,"kind":"mc","stem":"「식판 정리하는 방법」의 출처는 무엇인가요?","options":[{"t":"「급식실 이용 안내」, 학교 누리집","correct":true},{"t":"서진","mis":"K3-2-u3-X03"},{"t":"학급 신문","mis":"K3-2-u3-X03"},{"t":"수저 통","mis":"K3-2-u3-X08"}],"explanation":["「■ 출처」를 찾아요.","서진이는 글쓴이예요.","학교 누리집의 안내예요."],"asset":{"type":"passage","lines":["급식을 다 먹은 뒤 식판을 정리하는 방법을 알려 드리겠습니다.","먼저, 남은 음식을 한쪽으로 모아 정해진 통에 덜어 냅니다.","다음으로, 숟가락과 젓가락을 수저 통에 넣습니다.","끝으로, 빈 식판을 정해진 곳에 포개어 놓습니다.","식판을 놓는 곳은 「급식실 이용 안내」에 그림으로 나와 있습니다.","이 차례대로 하면 급식실을 깨끗하게 쓸 수 있습니다.","■ 출처: 「급식실 이용 안내」, 학교 누리집."],"title":"학급 신문 「식판 정리하는 방법」 — 글 서진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#3','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C5',1,'ox','auto','출처를 밝히는 것은 다른 사람이 만든 것을 존중하는 일이에요.',ARRAY['K3-2-u3-X05']::text[],false,'{"seq":3,"concept":"K3-2-u3-C5","difficulty":1,"kind":"ox","stem":"출처를 밝히는 것은 다른 사람이 만든 것을 존중하는 일이에요.","answer":"O","reason_options":[{"t":"만든 사람의 것을 내 것처럼 쓰지 않았다는 뜻이기 때문에","correct":true},{"t":"출처를 밝히면 글이 길어져 훌륭해 보이기 때문에","mis":"K3-2-u3-X05"}],"mis":"K3-2-u3-X05","explanation":["만든 사람을 밝혀 줘요.","내 것처럼 쓰지 않아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#4','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C6',1,'mc','auto','민결이가 놀이 기구를 탈 때 차례를 지켜야 한다고 한 까닭은 무엇인가요?',ARRAY['K3-2-u3-X08']::text[],false,'{"seq":4,"concept":"K3-2-u3-C6","difficulty":1,"kind":"mc","stem":"민결이가 놀이 기구를 탈 때 차례를 지켜야 한다고 한 까닭은 무엇인가요?","options":[{"t":"한꺼번에 몰리면 부딪치기 쉬워서","correct":true},{"t":"옆 반 친구와 다투고 싶어서","mis":"K3-2-u3-X08"},{"t":"놀이 기구가 새것이라서","mis":"K3-2-u3-X08"},{"t":"그네가 하나뿐이라서","mis":"K3-2-u3-X08"}],"explanation":["첫 줄을 다시 읽어요.","「때문입니다」가 있어요.","부딪치기 쉬워서예요."],"asset":{"type":"passage","lines":["놀이 기구를 탈 때에는 차례를 지켜야 합니다. 한꺼번에 몰리면 부딪치기 쉽기 때문입니다.","㉮ 옆 반 친구에게 들으니 미끄럼틀 앞에서 다툰 일이 있었다고 합니다.","㉯ 운동장 앞 「놀이 기구 이용 안내」 안내판에 따르면,","한 사람씩 차례대로 타야 한다고 합니다.","㉰ [그림] 미끄럼틀 앞에 한 줄로 서 있는 모습을 그린 그림","㉱ [그림] 그네 둘레에 그어 둔 선을 나타낸 그림","■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","우리 모두 놀이 기구는 차례를 지켜 타요."],"title":"주장하는 글 「놀이 기구는 차례를 지켜 타요」 — 글 민결"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#5','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C8',1,'ox','auto','출처가 적혀 있는 자료는 무조건 믿지도, 무조건 의심하지도 말고 살펴보아야 해요.',ARRAY['K3-2-u3-X12']::text[],false,'{"seq":5,"concept":"K3-2-u3-C8","difficulty":1,"kind":"ox","stem":"출처가 적혀 있는 자료는 무조건 믿지도, 무조건 의심하지도 말고 살펴보아야 해요.","answer":"O","reason_options":[{"t":"출처는 맞다·틀리다를 정해 주는 것이 아니라 살펴볼 수 있게 해 주는 것이기 때문에","correct":true},{"t":"출처가 있으면 그 자료는 언제나 맞기 때문에","mis":"K3-2-u3-X12"}],"mis":"K3-2-u3-X12","explanation":["3~4차시 하경이 말을 떠올려요.","어떤 곳인지 봐야 해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#6','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C12',1,'blank','auto','이야기 「모둠 화분」의 ㉡에 알맞은 이어 주는 말은 무엇인가요?',ARRAY['K3-2-u3-X16','K3-2-u3-X17']::text[],false,'{"seq":6,"concept":"K3-2-u3-C12","difficulty":1,"kind":"blank","stem":"이야기 「모둠 화분」의 ㉡에 알맞은 이어 주는 말은 무엇인가요?","options":[{"t":"그래서","correct":true},{"t":"그러나","mis":"K3-2-u3-X16"},{"t":"그리고","mis":"K3-2-u3-X16"},{"t":"월요일","mis":"K3-2-u3-X17"}],"explanation":["흙이 왜 말랐을까요?","모두 잊었기 때문이에요.","까닭이라서 그래서예요."],"asset":{"type":"passage","lines":["다올이네 모둠은 교실 화분을 맡았습니다.","모둠 친구들은 아침마다 흙을 만져 보기로 했습니다.","( ㉠ ) 금요일에는 모두 깜빡 잊고 말았습니다.","( ㉡ ) 월요일 아침, 흙이 바싹 말라 있었습니다.","다올이는 잎이 아니라 흙 쪽으로 천천히 물을 주었습니다.","( ㉢ ) 물받이에 고인 물도 비웠습니다.","며칠 뒤, 처졌던 잎이 다시 고개를 들었습니다."],"title":"이야기 「모둠 화분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#7','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C17',1,'match','auto','설명하는 글의 부분과 들어갈 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u3-C17","difficulty":1,"kind":"match","stem":"설명하는 글의 부분과 들어갈 내용을 알맞게 이으세요.","pairs":[{"l":"처음","r":"무엇을 설명할 글인지 밝히기"},{"l":"가운데","r":"일의 차례와 방법을 자세히 쓰기"},{"l":"끝","r":"설명한 내용을 간추리기"}],"mis":"K3-2-u3-X25","explanation":["글은 세 부분이에요.","가운데에 차례를 써요.","끝에서 간추려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#8','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C20',1,'ox','auto','「어제 가 보니 운동장에 물웅덩이가 많대.」는 바르게 쓴 문장이에요.',ARRAY['K3-2-u3-X29']::text[],false,'{"seq":8,"concept":"K3-2-u3-C20","difficulty":1,"kind":"ox","stem":"「어제 가 보니 운동장에 물웅덩이가 많대.」는 바르게 쓴 문장이에요.","answer":"X","reason_options":[{"t":"내가 직접 가 보고 안 것이라 「많데」로 써야 하기 때문에","correct":true},{"t":"‘-대’와 ‘-데’는 아무거나 써도 되기 때문에","mis":"K3-2-u3-X29"}],"mis":"K3-2-u3-X29","explanation":["누가 운동장에 갔나요?","내가 가서 봤어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#9','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C4',2,'mc','auto','민결이 글에서 ㉱의 출처는 어디에 밝혔나요?',ARRAY['K3-2-u3-X04','K3-2-u3-X09']::text[],false,'{"seq":9,"concept":"K3-2-u3-C4","difficulty":2,"kind":"mc","stem":"민결이 글에서 ㉱의 출처는 어디에 밝혔나요?","options":[{"t":"그림 자료 바로 아래","correct":true},{"t":"글 속 문장 안","mis":"K3-2-u3-X04"},{"t":"글 제목 옆","mis":"K3-2-u3-X04"},{"t":"밝히지 않았다","mis":"K3-2-u3-X09"}],"explanation":["㉱는 그림이에요.","바로 아래 줄을 봐요.","「■ 출처」가 있어요."],"asset":{"type":"passage","lines":["놀이 기구를 탈 때에는 차례를 지켜야 합니다. 한꺼번에 몰리면 부딪치기 쉽기 때문입니다.","㉮ 옆 반 친구에게 들으니 미끄럼틀 앞에서 다툰 일이 있었다고 합니다.","㉯ 운동장 앞 「놀이 기구 이용 안내」 안내판에 따르면,","한 사람씩 차례대로 타야 한다고 합니다.","㉰ [그림] 미끄럼틀 앞에 한 줄로 서 있는 모습을 그린 그림","㉱ [그림] 그네 둘레에 그어 둔 선을 나타낸 그림","■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","우리 모두 놀이 기구는 차례를 지켜 타요."],"title":"주장하는 글 「놀이 기구는 차례를 지켜 타요」 — 글 민결"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#10','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C6',2,'match','auto','민결이 글의 자료와 그 출처를 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u3-C6","difficulty":2,"kind":"match","stem":"민결이 글의 자료와 그 출처를 알맞게 이으세요.","pairs":[{"l":"㉯ 한 사람씩 차례대로 탄다는 내용","r":"「놀이 기구 이용 안내」, 운동장 앞 안내판"},{"l":"㉱ 그네 둘레의 선 그림","r":"「놀이터에서 지킬 것」, 보건실 안내장"},{"l":"㉰ 한 줄로 선 그림","r":"적혀 있지 않음"}],"mis":"K3-2-u3-X09","explanation":["자료 옆이나 아래를 봐요.","㉯는 문장 안, ㉱는 그림 아래예요.","㉰는 출처가 없어요."],"asset":{"type":"passage","lines":["놀이 기구를 탈 때에는 차례를 지켜야 합니다. 한꺼번에 몰리면 부딪치기 쉽기 때문입니다.","㉮ 옆 반 친구에게 들으니 미끄럼틀 앞에서 다툰 일이 있었다고 합니다.","㉯ 운동장 앞 「놀이 기구 이용 안내」 안내판에 따르면,","한 사람씩 차례대로 타야 한다고 합니다.","㉰ [그림] 미끄럼틀 앞에 한 줄로 서 있는 모습을 그린 그림","㉱ [그림] 그네 둘레에 그어 둔 선을 나타낸 그림","■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","우리 모두 놀이 기구는 차례를 지켜 타요."],"title":"주장하는 글 「놀이 기구는 차례를 지켜 타요」 — 글 민결"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#11','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C7',2,'mc','auto','「놀이터에서 지킬 것」이라는 출처를 보고 더 알고 싶은 것이 생겼어요. 어떻게 하면 될까요?',ARRAY['K3-2-u3-X13','K3-2-u3-X12','K3-2-u3-X10']::text[],false,'{"seq":11,"concept":"K3-2-u3-C7","difficulty":2,"kind":"mc","stem":"「놀이터에서 지킬 것」이라는 출처를 보고 더 알고 싶은 것이 생겼어요. 어떻게 하면 될까요?","options":[{"t":"보건실에 가서 그 안내장을 찾아본다","correct":true},{"t":"민결이에게 무조건 틀렸다고 말한다","mis":"K3-2-u3-X13"},{"t":"출처가 있으니 더 알아보지 않는다","mis":"K3-2-u3-X12"},{"t":"글을 읽지 않고 그림만 본다","mis":"K3-2-u3-X10"}],"explanation":["출처는 다음 길을 알려 줘요.","보건실 안내장이라고 했어요.","가서 찾아봐요."],"asset":{"type":"passage","lines":["놀이 기구를 탈 때에는 차례를 지켜야 합니다. 한꺼번에 몰리면 부딪치기 쉽기 때문입니다.","㉮ 옆 반 친구에게 들으니 미끄럼틀 앞에서 다툰 일이 있었다고 합니다.","㉯ 운동장 앞 「놀이 기구 이용 안내」 안내판에 따르면,","한 사람씩 차례대로 타야 한다고 합니다.","㉰ [그림] 미끄럼틀 앞에 한 줄로 서 있는 모습을 그린 그림","㉱ [그림] 그네 둘레에 그어 둔 선을 나타낸 그림","■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","우리 모두 놀이 기구는 차례를 지켜 타요."],"title":"주장하는 글 「놀이 기구는 차례를 지켜 타요」 — 글 민결"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#12','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C11',2,'mc','auto','「놀이 기구 이용 안내」가 알맞은 출처인지 확인하는 방법은 무엇인가요?',ARRAY['K3-2-u3-X14','K3-2-u3-X12']::text[],false,'{"seq":12,"concept":"K3-2-u3-C11","difficulty":2,"kind":"mc","stem":"「놀이 기구 이용 안내」가 알맞은 출처인지 확인하는 방법은 무엇인가요?","options":[{"t":"운동장 앞에 가서 안내판을 직접 본다","correct":true},{"t":"이름이 길어서 믿는다","mis":"K3-2-u3-X14"},{"t":"글씨가 크다고 하니 믿는다","mis":"K3-2-u3-X14"},{"t":"민결이가 썼으니 믿는다","mis":"K3-2-u3-X12"}],"explanation":["확인은 가서 보는 거예요.","운동장 앞에 있다고 했어요.","직접 봐요."],"asset":{"type":"passage","lines":["놀이 기구를 탈 때에는 차례를 지켜야 합니다. 한꺼번에 몰리면 부딪치기 쉽기 때문입니다.","㉮ 옆 반 친구에게 들으니 미끄럼틀 앞에서 다툰 일이 있었다고 합니다.","㉯ 운동장 앞 「놀이 기구 이용 안내」 안내판에 따르면,","한 사람씩 차례대로 타야 한다고 합니다.","㉰ [그림] 미끄럼틀 앞에 한 줄로 서 있는 모습을 그린 그림","㉱ [그림] 그네 둘레에 그어 둔 선을 나타낸 그림","■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","우리 모두 놀이 기구는 차례를 지켜 타요."],"title":"주장하는 글 「놀이 기구는 차례를 지켜 타요」 — 글 민결"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#13','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C13',2,'ox','auto','「모둠 화분」에서 모든 문장 앞에 이어 주는 말을 넣으면 더 좋은 글이 돼요.',ARRAY['K3-2-u3-X18']::text[],false,'{"seq":13,"concept":"K3-2-u3-C13","difficulty":2,"kind":"ox","stem":"「모둠 화분」에서 모든 문장 앞에 이어 주는 말을 넣으면 더 좋은 글이 돼요.","answer":"X","reason_options":[{"t":"이어 주는 말은 앞뒤 뜻의 관계에 맞을 때 써야 하기 때문에","correct":true},{"t":"이어 주는 말이 많을수록 좋은 글이기 때문에","mis":"K3-2-u3-X18"}],"mis":"K3-2-u3-X18","explanation":["개수가 정해 주지 않아요.","앞뒤 뜻이 정해요.","그래서 X예요."],"asset":{"type":"passage","lines":["다올이네 모둠은 교실 화분을 맡았습니다.","모둠 친구들은 아침마다 흙을 만져 보기로 했습니다.","( ㉠ ) 금요일에는 모두 깜빡 잊고 말았습니다.","( ㉡ ) 월요일 아침, 흙이 바싹 말라 있었습니다.","다올이는 잎이 아니라 흙 쪽으로 천천히 물을 주었습니다.","( ㉢ ) 물받이에 고인 물도 비웠습니다.","며칠 뒤, 처졌던 잎이 다시 고개를 들었습니다."],"title":"이야기 「모둠 화분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#14','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C15',2,'mc','auto','서진이 글에서 「다음으로」 할 일은 무엇인가요?',ARRAY['K3-2-u3-X22','K3-2-u3-X08']::text[],false,'{"seq":14,"concept":"K3-2-u3-C15","difficulty":2,"kind":"mc","stem":"서진이 글에서 「다음으로」 할 일은 무엇인가요?","options":[{"t":"숟가락과 젓가락을 수저 통에 넣는다","correct":true},{"t":"남은 음식을 덜어 낸다","mis":"K3-2-u3-X22"},{"t":"빈 식판을 포개어 놓는다","mis":"K3-2-u3-X22"},{"t":"학교 누리집에 들어간다","mis":"K3-2-u3-X08"}],"explanation":["「다음으로」가 붙은 줄을 찾아요.","덜어 낸 다음이에요.","수저를 넣어요."],"asset":{"type":"passage","lines":["급식을 다 먹은 뒤 식판을 정리하는 방법을 알려 드리겠습니다.","먼저, 남은 음식을 한쪽으로 모아 정해진 통에 덜어 냅니다.","다음으로, 숟가락과 젓가락을 수저 통에 넣습니다.","끝으로, 빈 식판을 정해진 곳에 포개어 놓습니다.","식판을 놓는 곳은 「급식실 이용 안내」에 그림으로 나와 있습니다.","이 차례대로 하면 급식실을 깨끗하게 쓸 수 있습니다.","■ 출처: 「급식실 이용 안내」, 학교 누리집."],"title":"학급 신문 「식판 정리하는 방법」 — 글 서진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#15','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C16',2,'ox','auto','숟가락과 젓가락을 수저 통에 넣는 것처럼 늘 해 보아서 아는 방법에도 꼭 출처를 붙여야 해요.',ARRAY['K3-2-u3-X24']::text[],false,'{"seq":15,"concept":"K3-2-u3-C16","difficulty":2,"kind":"ox","stem":"숟가락과 젓가락을 수저 통에 넣는 것처럼 늘 해 보아서 아는 방법에도 꼭 출처를 붙여야 해요.","answer":"X","reason_options":[{"t":"내가 해 본 일은 다른 곳에서 가져온 자료가 아니기 때문에","correct":true},{"t":"설명하는 글의 모든 문장에는 출처가 있어야 하기 때문에","mis":"K3-2-u3-X24"}],"mis":"K3-2-u3-X24","explanation":["내가 아는 방법과 찾아본 내용은 달라요.","해 본 일은 출처가 없어도 돼요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#16','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C18',2,'ox','auto','서진이는 남은 음식을 먼저 덜고 수저를 넣었고, 친구는 수저를 먼저 넣고 음식을 덜었어요. 차례와 까닭이 드러나면 둘 다 알맞은 글일 수 있어요.',ARRAY['K3-2-u3-X27']::text[],false,'{"seq":16,"concept":"K3-2-u3-C18","difficulty":2,"kind":"ox","stem":"서진이는 남은 음식을 먼저 덜고 수저를 넣었고, 친구는 수저를 먼저 넣고 음식을 덜었어요. 차례와 까닭이 드러나면 둘 다 알맞은 글일 수 있어요.","answer":"O","reason_options":[{"t":"방법이 달라도 읽는 사람이 따라 할 수 있으면 알맞은 글이기 때문에","correct":true},{"t":"같은 일을 설명하는 방법은 하나뿐이기 때문에","mis":"K3-2-u3-X27"}],"mis":"K3-2-u3-X27","explanation":["세연이와 다안이를 떠올려요.","방법이 달라도 돼요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#17','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C2',3,'mc','auto','「놀이 기구 이용 설명서」에 그네를 탈 때 지킬 것을 넣으려는데 잘 몰라요. 가장 알맞은 방법은 무엇인가요?',ARRAY['K3-2-u3-X02','K3-2-u3-X06']::text[],false,'{"seq":17,"concept":"K3-2-u3-C2","difficulty":3,"kind":"mc","stem":"「놀이 기구 이용 설명서」에 그네를 탈 때 지킬 것을 넣으려는데 잘 몰라요. 가장 알맞은 방법은 무엇인가요?","options":[{"t":"운동장 앞 안내판이나 보건실 안내장을 보고 확인한 것을 쓴다","correct":true},{"t":"그럴 것 같은 대로 지어 쓴다","mis":"K3-2-u3-X02"},{"t":"친구 글을 내 것처럼 옮긴다","mis":"K3-2-u3-X06"},{"t":"모르는 것은 아무렇게나 짐작해 채운다","mis":"K3-2-u3-X02"}],"explanation":["모르는 것은 확인해요.","학교 안에 확인할 곳이 있어요.","확인한 것만 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#18','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C6',3,'mc','auto','민결이가 의견을 뒷받침하려고 쓴 자료 가운데 읽는 사람이 직접 찾아가 살펴볼 수 있는 것은 무엇인가요?',ARRAY['K3-2-u3-X09','K3-2-u3-X08']::text[],false,'{"seq":18,"concept":"K3-2-u3-C6","difficulty":3,"kind":"mc","stem":"민결이가 의견을 뒷받침하려고 쓴 자료 가운데 읽는 사람이 직접 찾아가 살펴볼 수 있는 것은 무엇인가요?","options":[{"t":"㉯ 「놀이 기구 이용 안내」 안내판","correct":true},{"t":"㉮ 옆 반 친구에게 들은 이야기","mis":"K3-2-u3-X09"},{"t":"㉰ 한 줄로 선 그림","mis":"K3-2-u3-X09"},{"t":"마지막 문장 「차례를 지켜 타요」","mis":"K3-2-u3-X08"}],"explanation":["찾아갈 곳이 적혀 있어야 해요.","안내판은 운동장 앞에 있어요.","㉯예요."],"asset":{"type":"passage","lines":["놀이 기구를 탈 때에는 차례를 지켜야 합니다. 한꺼번에 몰리면 부딪치기 쉽기 때문입니다.","㉮ 옆 반 친구에게 들으니 미끄럼틀 앞에서 다툰 일이 있었다고 합니다.","㉯ 운동장 앞 「놀이 기구 이용 안내」 안내판에 따르면,","한 사람씩 차례대로 타야 한다고 합니다.","㉰ [그림] 미끄럼틀 앞에 한 줄로 서 있는 모습을 그린 그림","㉱ [그림] 그네 둘레에 그어 둔 선을 나타낸 그림","■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","우리 모두 놀이 기구는 차례를 지켜 타요."],"title":"주장하는 글 「놀이 기구는 차례를 지켜 타요」 — 글 민결"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#19','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C11',3,'error','auto','「놀이터에서 지킬 것」이 알맞은 출처인지 확인하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X14']::text[],false,'{"seq":19,"concept":"K3-2-u3-C11","difficulty":3,"kind":"error","stem":"「놀이터에서 지킬 것」이 알맞은 출처인지 확인하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「안내장이라는 말이 붙었으니 확인할 필요 없어.」","correct":true,"mis_target":"K3-2-u3-X14"},{"t":"친구 나 — 「보건실에 가서 그 안내장이 있는지 볼래.」","mis":"K3-2-u3-X14"},{"t":"친구 다 — 「보건실이 어떤 곳인지 알아볼래.」","mis":"K3-2-u3-X14"}],"explanation":["이름은 확인이 아니에요.","가서 보거나 알아봐요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["놀이 기구를 탈 때에는 차례를 지켜야 합니다. 한꺼번에 몰리면 부딪치기 쉽기 때문입니다.","㉮ 옆 반 친구에게 들으니 미끄럼틀 앞에서 다툰 일이 있었다고 합니다.","㉯ 운동장 앞 「놀이 기구 이용 안내」 안내판에 따르면,","한 사람씩 차례대로 타야 한다고 합니다.","㉰ [그림] 미끄럼틀 앞에 한 줄로 서 있는 모습을 그린 그림","㉱ [그림] 그네 둘레에 그어 둔 선을 나타낸 그림","■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","우리 모두 놀이 기구는 차례를 지켜 타요."],"title":"주장하는 글 「놀이 기구는 차례를 지켜 타요」 — 글 민결"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#20','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C12',3,'mc','auto','「모둠 화분」의 ㉠에 「그래서」를 넣으면 어떻게 읽히나요?',ARRAY['K3-2-u3-X16','K3-2-u3-X18']::text[],false,'{"seq":20,"concept":"K3-2-u3-C12","difficulty":3,"kind":"mc","stem":"「모둠 화분」의 ㉠에 「그래서」를 넣으면 어떻게 읽히나요?","options":[{"t":"흙을 만져 보기로 한 것이 잊은 까닭인 것처럼 읽혀 뜻이 어색하다","correct":true},{"t":"뜻이 똑같다","mis":"K3-2-u3-X16"},{"t":"더 자연스럽다","mis":"K3-2-u3-X18"},{"t":"이야기의 차례가 더 잘 보인다","mis":"K3-2-u3-X18"}],"explanation":["「그래서」는 앞이 까닭일 때예요.","하기로 한 것이 잊은 까닭일까요?","아니라서 어색해요."],"asset":{"type":"passage","lines":["다올이네 모둠은 교실 화분을 맡았습니다.","모둠 친구들은 아침마다 흙을 만져 보기로 했습니다.","( ㉠ ) 금요일에는 모두 깜빡 잊고 말았습니다.","( ㉡ ) 월요일 아침, 흙이 바싹 말라 있었습니다.","다올이는 잎이 아니라 흙 쪽으로 천천히 물을 주었습니다.","( ㉢ ) 물받이에 고인 물도 비웠습니다.","며칠 뒤, 처졌던 잎이 다시 고개를 들었습니다."],"title":"이야기 「모둠 화분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#21','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C15',3,'error','auto','서진이 글을 1학년 동생이 읽기 좋게 고치려고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X21','K3-2-u3-X22']::text[],false,'{"seq":21,"concept":"K3-2-u3-C15","difficulty":3,"kind":"error","stem":"서진이 글을 1학년 동생이 읽기 좋게 고치려고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「「덜어 냅니다」를 더 어려운 말로 바꾸면 멋있어 보일 거야.」","correct":true,"mis_target":"K3-2-u3-X21"},{"t":"친구 가 — 「「포개어」가 어려우면 「겹쳐」로 바꿔 쓰자.」","mis":"K3-2-u3-X21"},{"t":"친구 나 — 「차례 말은 지금처럼 순서대로 두자.」","mis":"K3-2-u3-X22"}],"explanation":["읽을 사람은 1학년 동생이에요.","어려운 말은 풀어 써요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["급식을 다 먹은 뒤 식판을 정리하는 방법을 알려 드리겠습니다.","먼저, 남은 음식을 한쪽으로 모아 정해진 통에 덜어 냅니다.","다음으로, 숟가락과 젓가락을 수저 통에 넣습니다.","끝으로, 빈 식판을 정해진 곳에 포개어 놓습니다.","식판을 놓는 곳은 「급식실 이용 안내」에 그림으로 나와 있습니다.","이 차례대로 하면 급식실을 깨끗하게 쓸 수 있습니다.","■ 출처: 「급식실 이용 안내」, 학교 누리집."],"title":"학급 신문 「식판 정리하는 방법」 — 글 서진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#22','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C19',3,'mc','auto','「놀이 기구 이용 설명서」의 셋째 문단(지킬 것)에 넣기 알맞은 문장은 무엇인가요?',ARRAY['K3-2-u3-X25','K3-2-u3-X21']::text[],false,'{"seq":22,"concept":"K3-2-u3-C19","difficulty":3,"kind":"mc","stem":"「놀이 기구 이용 설명서」의 셋째 문단(지킬 것)에 넣기 알맞은 문장은 무엇인가요?","options":[{"t":"“놀이 기구는 한 사람씩 차례대로 탑니다.”","correct":true},{"t":"“운동장은 학교 건물 옆에 있습니다.”","mis":"K3-2-u3-X25"},{"t":"“먼저, 놀이 기구 앞에 줄을 섭니다.”","mis":"K3-2-u3-X25"},{"t":"“놀이 기구가 가장 재미있습니다.”","mis":"K3-2-u3-X21"}],"explanation":["셋째 문단은 지킬 것이에요.","어떤 곳·차례와 갈라요.","차례대로 타는 것이 지킬 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#23','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C12',4,'mc','auto','「모둠 화분」의 ㉠·㉡·㉢에 「그리고 · 그러나 · 그래서」를 이 차례대로 넣으면 어떤 점이 잘못되나요?',ARRAY['K3-2-u3-X16','K3-2-u3-X18','K3-2-u3-X19']::text[],false,'{"seq":23,"concept":"K3-2-u3-C12","difficulty":4,"kind":"mc","stem":"「모둠 화분」의 ㉠·㉡·㉢에 「그리고 · 그러나 · 그래서」를 이 차례대로 넣으면 어떤 점이 잘못되나요?","options":[{"t":"잊은 일·마른 일·비운 일의 앞뒤 관계(반대·까닭·더하기)와 말이 맞지 않아 이야기의 뜻이 어색해진다","correct":true},{"t":"잘못된 점이 없다 — 이어 주는 말은 아무 차례로 써도 된다","mis":"K3-2-u3-X16"},{"t":"이어 주는 말이 셋이나 있어 너무 많다","mis":"K3-2-u3-X18"},{"t":"이어 주는 말은 이야기에 쓰면 안 된다","mis":"K3-2-u3-X19"}],"explanation":["빈칸마다 앞뒤 관계가 달라요.","반대·까닭·더하기 차례예요.","말이 엇갈리면 뜻이 어색해요."],"asset":{"type":"passage","lines":["다올이네 모둠은 교실 화분을 맡았습니다.","모둠 친구들은 아침마다 흙을 만져 보기로 했습니다.","( ㉠ ) 금요일에는 모두 깜빡 잊고 말았습니다.","( ㉡ ) 월요일 아침, 흙이 바싹 말라 있었습니다.","다올이는 잎이 아니라 흙 쪽으로 천천히 물을 주었습니다.","( ㉢ ) 물받이에 고인 물도 비웠습니다.","며칠 뒤, 처졌던 잎이 다시 고개를 들었습니다."],"title":"이야기 「모둠 화분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#24','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C12',4,'essay','teacher','「모둠 화분」의 ㉠~㉢에 알맞은 이어 주는 말을 쓰고, 각각 앞뒤 문장이 어떤 관계라서 그 말을 골랐는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u3-C12","difficulty":4,"kind":"essay","stem":"「모둠 화분」의 ㉠~㉢에 알맞은 이어 주는 말을 쓰고, 각각 앞뒤 문장이 어떤 관계라서 그 말을 골랐는지 쓰세요.","answer_guide":{"answer":"예: ㉠ 그러나 — 아침마다 흙을 만져 보기로 했는데 금요일에는 잊었으니 반대되는 내용이다. ㉡ 그래서 — 모두 잊은 것이 흙이 바싹 마른 까닭이다. ㉢ 그리고 — 물을 준 일에 물받이를 비운 일이 더해지니 비슷한 내용이 이어진다.","scoring_points":["세 빈칸에 알맞은 말을 썼는가","빈칸마다 앞뒤 관계를 썼는가","관계와 고른 말이 맞는가"]},"explanation":["빈칸 앞뒤를 하나씩 따져요.","반대·까닭·더하기를 찾아요.","관계로 까닭을 써요."],"asset":{"type":"passage","lines":["다올이네 모둠은 교실 화분을 맡았습니다.","모둠 친구들은 아침마다 흙을 만져 보기로 했습니다.","( ㉠ ) 금요일에는 모두 깜빡 잊고 말았습니다.","( ㉡ ) 월요일 아침, 흙이 바싹 말라 있었습니다.","다올이는 잎이 아니라 흙 쪽으로 천천히 물을 주었습니다.","( ㉢ ) 물받이에 고인 물도 비웠습니다.","며칠 뒤, 처졌던 잎이 다시 고개를 들었습니다."],"title":"이야기 「모둠 화분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_b#25','kor',3,2,'u3','','g3_2_kor_u3_review_b','unit_review','K3-2-u3-C16',4,'essay','teacher','「찾아본 곳이 기억나지 않으면 그럴듯한 이름을 지어 적어도 될까?」에 대한 내 생각을 까닭과 함께 쓰고, 서진이 글을 예로 들어 어떻게 해야 하는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u3-C16","difficulty":4,"kind":"essay","stem":"「찾아본 곳이 기억나지 않으면 그럴듯한 이름을 지어 적어도 될까?」에 대한 내 생각을 까닭과 함께 쓰고, 서진이 글을 예로 들어 어떻게 해야 하는지 쓰세요.","answer_guide":{"answer":"예: 지어 적으면 안 된다. 그 이름을 믿고 찾아간 친구는 그런 곳을 찾을 수 없고, 사실이 아닌 것을 믿게 될 수도 있기 때문이다. 서진이가 식판 놓는 곳을 어디서 알았는지 잊었다면, 학교 누리집의 「급식실 이용 안내」에 다시 들어가 확인한 뒤 적고, 확인할 수 없으면 그 문장을 쓰지 않아야 한다.","scoring_points":["지어 적으면 안 된다고 썼는가","읽는 사람에게 생길 일로 까닭을 썼는가","다시 확인하거나 쓰지 않는다고 서진이 글로 썼는가"]},"explanation":["이 단원에서 가장 중요한 답이에요.","출처는 확인하는 것이에요.","서진이 글에 대어 봐요."],"asset":{"type":"passage","lines":["급식을 다 먹은 뒤 식판을 정리하는 방법을 알려 드리겠습니다.","먼저, 남은 음식을 한쪽으로 모아 정해진 통에 덜어 냅니다.","다음으로, 숟가락과 젓가락을 수저 통에 넣습니다.","끝으로, 빈 식판을 정해진 곳에 포개어 놓습니다.","식판을 놓는 곳은 「급식실 이용 안내」에 그림으로 나와 있습니다.","이 차례대로 하면 급식실을 깨끗하게 쓸 수 있습니다.","■ 출처: 「급식실 이용 안내」, 학교 누리집."],"title":"학급 신문 「식판 정리하는 방법」 — 글 서진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#1','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C1',1,'mc','auto','도영이가 「무엇을 먼저 해야 하는지 모르겠어.」라고 했어요. 하선이 글에 모자랐던 것은 무엇인가요?',ARRAY['K3-2-u3-X01','K3-2-u3-X22']::text[],false,'{"seq":1,"concept":"K3-2-u3-C1","difficulty":1,"kind":"mc","stem":"도영이가 「무엇을 먼저 해야 하는지 모르겠어.」라고 했어요. 하선이 글에 모자랐던 것은 무엇인가요?","options":[{"t":"일의 차례","correct":true},{"t":"큰 글씨","mis":"K3-2-u3-X01"},{"t":"예쁜 그림","mis":"K3-2-u3-X01"},{"t":"긴 문장","mis":"K3-2-u3-X22"}],"explanation":["도영이 말을 다시 읽어요.","먼저 할 일을 몰랐어요.","차례가 모자랐어요."],"asset":{"type":"speech","turns":[{"who":"하선","text":"“딱지 접는 방법을 알려 줄게. 색종이를 반으로 접어. 그리고 또 접어. 그다음에 끼우면 돼.”"},{"who":"도영","text":"읽어 봤는데 무엇을 먼저 해야 하는지 모르겠어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#2','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C3',1,'ox','auto','글을 쓴 사람의 이름은 그 글의 출처예요.',ARRAY['K3-2-u3-X03']::text[],false,'{"seq":2,"concept":"K3-2-u3-C3","difficulty":1,"kind":"ox","stem":"글을 쓴 사람의 이름은 그 글의 출처예요.","answer":"X","reason_options":[{"t":"출처는 글쓴이가 가져온 자료가 온 곳이기 때문에","correct":true},{"t":"글을 쓴 사람이 곧 자료를 만든 곳이기 때문에","mis":"K3-2-u3-X03"}],"mis":"K3-2-u3-X03","explanation":["글쓴이는 이 글을 쓴 사람이에요.","출처는 가져온 자료가 온 곳이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#3','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C5',1,'mc','auto','서진이가 글 끝에 「■ 출처」를 적은 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X05','K3-2-u3-X06']::text[],false,'{"seq":3,"concept":"K3-2-u3-C5","difficulty":1,"kind":"mc","stem":"서진이가 글 끝에 「■ 출처」를 적은 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"식판 놓는 곳을 어디에서 알아냈는지 알리려고","correct":true},{"t":"글을 길어 보이게 하려고","mis":"K3-2-u3-X05"},{"t":"글을 어려워 보이게 하려고","mis":"K3-2-u3-X05"},{"t":"「급식실 이용 안내」를 자기가 만든 것처럼 보이려고","mis":"K3-2-u3-X06"}],"explanation":["식판 놓는 곳은 찾아본 내용이에요.","어디서 알았는지 밝혀요.","알리려고 적었어요."],"asset":{"type":"passage","lines":["급식을 다 먹은 뒤 식판을 정리하는 방법을 알려 드리겠습니다.","먼저, 남은 음식을 한쪽으로 모아 정해진 통에 덜어 냅니다.","다음으로, 숟가락과 젓가락을 수저 통에 넣습니다.","끝으로, 빈 식판을 정해진 곳에 포개어 놓습니다.","식판을 놓는 곳은 「급식실 이용 안내」에 그림으로 나와 있습니다.","이 차례대로 하면 급식실을 깨끗하게 쓸 수 있습니다.","■ 출처: 「급식실 이용 안내」, 학교 누리집."],"title":"학급 신문 「식판 정리하는 방법」 — 글 서진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#4','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C6',1,'ox','auto','「놀이 기구는 차례를 지켜 타요」에서 글쓴이의 의견은 ㉮의 다툰 이야기예요.',ARRAY['K3-2-u3-X08']::text[],false,'{"seq":4,"concept":"K3-2-u3-C6","difficulty":1,"kind":"ox","stem":"「놀이 기구는 차례를 지켜 타요」에서 글쓴이의 의견은 ㉮의 다툰 이야기예요.","answer":"X","reason_options":[{"t":"㉮는 의견을 뒷받침하려고 가져온 자료이고, 의견은 「차례를 지켜 타요」이기 때문에","correct":true},{"t":"글에 처음 나온 이야기가 언제나 의견이기 때문에","mis":"K3-2-u3-X08"}],"mis":"K3-2-u3-X08","explanation":["의견은 글쓴이가 하고 싶은 말이에요.","㉮는 들은 이야기예요.","그래서 X예요."],"asset":{"type":"passage","lines":["놀이 기구를 탈 때에는 차례를 지켜야 합니다. 한꺼번에 몰리면 부딪치기 쉽기 때문입니다.","㉮ 옆 반 친구에게 들으니 미끄럼틀 앞에서 다툰 일이 있었다고 합니다.","㉯ 운동장 앞 「놀이 기구 이용 안내」 안내판에 따르면,","한 사람씩 차례대로 타야 한다고 합니다.","㉰ [그림] 미끄럼틀 앞에 한 줄로 서 있는 모습을 그린 그림","㉱ [그림] 그네 둘레에 그어 둔 선을 나타낸 그림","■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","우리 모두 놀이 기구는 차례를 지켜 타요."],"title":"주장하는 글 「놀이 기구는 차례를 지켜 타요」 — 글 민결"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#5','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C8',1,'mc','auto','「출처가 있어도 다 거짓일 수 있으니 하나도 믿지 말자.」라는 말에 대한 생각으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X13','K3-2-u3-X12','K3-2-u3-X14']::text[],false,'{"seq":5,"concept":"K3-2-u3-C8","difficulty":1,"kind":"mc","stem":"「출처가 있어도 다 거짓일 수 있으니 하나도 믿지 말자.」라는 말에 대한 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"다 틀린 것도 아니니 어떤 곳인지 살펴보고 판단해야 한다","correct":true},{"t":"맞는 말이다 — 출처는 믿을 수 없다","mis":"K3-2-u3-X13"},{"t":"출처가 있으면 다 맞으니 그대로 믿으면 된다","mis":"K3-2-u3-X12"},{"t":"글이 길면 믿고 짧으면 안 믿는다","mis":"K3-2-u3-X14"}],"explanation":["무조건 의심하는 말이에요.","그것도 알맞지 않아요.","살펴보고 판단해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#6','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C12',1,'blank','auto','이야기 「모둠 화분」의 ㉢에 알맞은 이어 주는 말은 무엇인가요?',ARRAY['K3-2-u3-X16','K3-2-u3-X17']::text[],false,'{"seq":6,"concept":"K3-2-u3-C12","difficulty":1,"kind":"blank","stem":"이야기 「모둠 화분」의 ㉢에 알맞은 이어 주는 말은 무엇인가요?","options":[{"t":"그리고","correct":true},{"t":"그러나","mis":"K3-2-u3-X16"},{"t":"그래서","mis":"K3-2-u3-X16"},{"t":"며칠 뒤","mis":"K3-2-u3-X17"}],"explanation":["물을 준 일에 일이 하나 더해져요.","물받이도 비웠어요.","그리고예요."],"asset":{"type":"passage","lines":["다올이네 모둠은 교실 화분을 맡았습니다.","모둠 친구들은 아침마다 흙을 만져 보기로 했습니다.","( ㉠ ) 금요일에는 모두 깜빡 잊고 말았습니다.","( ㉡ ) 월요일 아침, 흙이 바싹 말라 있었습니다.","다올이는 잎이 아니라 흙 쪽으로 천천히 물을 주었습니다.","( ㉢ ) 물받이에 고인 물도 비웠습니다.","며칠 뒤, 처졌던 잎이 다시 고개를 들었습니다."],"title":"이야기 「모둠 화분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#7','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C17',1,'mc','auto','「식판 정리하는 방법」에서 「끝」 부분에 해당하는 문장은 무엇인가요?',ARRAY['K3-2-u3-X25']::text[],false,'{"seq":7,"concept":"K3-2-u3-C17","difficulty":1,"kind":"mc","stem":"「식판 정리하는 방법」에서 「끝」 부분에 해당하는 문장은 무엇인가요?","options":[{"t":"「이 차례대로 하면 급식실을 깨끗하게 쓸 수 있습니다.」","correct":true},{"t":"「급식을 다 먹은 뒤 … 알려 드리겠습니다.」","mis":"K3-2-u3-X25"},{"t":"「먼저, 남은 음식을 … 덜어 냅니다.」","mis":"K3-2-u3-X25"},{"t":"「다음으로, 숟가락과 젓가락을 … 넣습니다.」","mis":"K3-2-u3-X25"}],"explanation":["끝은 간추리는 부분이에요.","「이 차례대로 하면」이 있어요.","그 문장이 끝이에요."],"asset":{"type":"passage","lines":["급식을 다 먹은 뒤 식판을 정리하는 방법을 알려 드리겠습니다.","먼저, 남은 음식을 한쪽으로 모아 정해진 통에 덜어 냅니다.","다음으로, 숟가락과 젓가락을 수저 통에 넣습니다.","끝으로, 빈 식판을 정해진 곳에 포개어 놓습니다.","식판을 놓는 곳은 「급식실 이용 안내」에 그림으로 나와 있습니다.","이 차례대로 하면 급식실을 깨끗하게 쓸 수 있습니다.","■ 출처: 「급식실 이용 안내」, 학교 누리집."],"title":"학급 신문 「식판 정리하는 방법」 — 글 서진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#8','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C21',1,'match','auto','「운동장」 낱말 그물에서 떠오른 말과 그렇게 떠오른 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u3-C21","difficulty":1,"kind":"match","stem":"「운동장」 낱말 그물에서 떠오른 말과 그렇게 떠오른 까닭을 알맞게 이으세요.","pairs":[{"l":"미끄럼틀","r":"운동장에 있는 것"},{"l":"이어달리기","r":"운동장에서 하는 일"},{"l":"차례 지키기","r":"운동장에서 지킬 것"}],"mis":"K3-2-u3-X30","explanation":["그 말이 무엇을 가리키나요?","있는 것·하는 일·지킬 것이에요.","여러 갈래로 뻗어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#9','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C3',2,'error','auto','「식판 정리하는 방법」의 출처를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X03','K3-2-u3-X04']::text[],false,'{"seq":9,"concept":"K3-2-u3-C3","difficulty":2,"kind":"error","stem":"「식판 정리하는 방법」의 출처를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「서진이가 쓴 글이니까 「서진」이 출처야.」","correct":true,"mis_target":"K3-2-u3-X03"},{"t":"친구 가 — 「「급식실 이용 안내」, 학교 누리집이 출처야.」","mis":"K3-2-u3-X04"},{"t":"친구 다 — 「글 맨 끝 「■ 출처」에 적혀 있어.」","mis":"K3-2-u3-X04"}],"explanation":["서진이는 글쓴이예요.","출처는 가져온 자료가 온 곳이에요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["급식을 다 먹은 뒤 식판을 정리하는 방법을 알려 드리겠습니다.","먼저, 남은 음식을 한쪽으로 모아 정해진 통에 덜어 냅니다.","다음으로, 숟가락과 젓가락을 수저 통에 넣습니다.","끝으로, 빈 식판을 정해진 곳에 포개어 놓습니다.","식판을 놓는 곳은 「급식실 이용 안내」에 그림으로 나와 있습니다.","이 차례대로 하면 급식실을 깨끗하게 쓸 수 있습니다.","■ 출처: 「급식실 이용 안내」, 학교 누리집."],"title":"학급 신문 「식판 정리하는 방법」 — 글 서진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#10','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C6',2,'ox','auto','민결이 글의 ㉮는 「옆 반 친구에게 들으니」라고 했으니 출처가 밝혀진 자료예요.',ARRAY['K3-2-u3-X09']::text[],false,'{"seq":10,"concept":"K3-2-u3-C6","difficulty":2,"kind":"ox","stem":"민결이 글의 ㉮는 「옆 반 친구에게 들으니」라고 했으니 출처가 밝혀진 자료예요.","answer":"X","reason_options":[{"t":"어느 친구인지, 어디에서 확인할지 알 수 없어 찾아갈 곳이 없기 때문에","correct":true},{"t":"들은 이야기는 모두 출처가 있는 자료이기 때문에","mis":"K3-2-u3-X09"}],"mis":"K3-2-u3-X09","explanation":["「어떤 형」과 같은 경우예요.","찾아갈 곳이 없어요.","그래서 X예요."],"asset":{"type":"passage","lines":["놀이 기구를 탈 때에는 차례를 지켜야 합니다. 한꺼번에 몰리면 부딪치기 쉽기 때문입니다.","㉮ 옆 반 친구에게 들으니 미끄럼틀 앞에서 다툰 일이 있었다고 합니다.","㉯ 운동장 앞 「놀이 기구 이용 안내」 안내판에 따르면,","한 사람씩 차례대로 타야 한다고 합니다.","㉰ [그림] 미끄럼틀 앞에 한 줄로 서 있는 모습을 그린 그림","㉱ [그림] 그네 둘레에 그어 둔 선을 나타낸 그림","■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","우리 모두 놀이 기구는 차례를 지켜 타요."],"title":"주장하는 글 「놀이 기구는 차례를 지켜 타요」 — 글 민결"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#11','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C7',2,'ox','auto','출처를 확인하며 읽으면 글을 읽지 않아도 내용을 알 수 있어요.',ARRAY['K3-2-u3-X10']::text[],false,'{"seq":11,"concept":"K3-2-u3-C7","difficulty":2,"kind":"ox","stem":"출처를 확인하며 읽으면 글을 읽지 않아도 내용을 알 수 있어요.","answer":"X","reason_options":[{"t":"출처는 내용을 대신하지 않고 자료가 어디서 왔는지 살피게 해 주는 것이기 때문에","correct":true},{"t":"출처에 글 내용이 모두 들어 있기 때문에","mis":"K3-2-u3-X10"}],"mis":"K3-2-u3-X10","explanation":["출처는 자료가 온 곳이에요.","내용은 글을 읽어야 알아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#12','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C11',2,'ox','auto','출처의 이름이 길고 그럴듯하면 따로 확인하지 않아도 믿을 만해요.',ARRAY['K3-2-u3-X14']::text[],false,'{"seq":12,"concept":"K3-2-u3-C11","difficulty":2,"kind":"ox","stem":"출처의 이름이 길고 그럴듯하면 따로 확인하지 않아도 믿을 만해요.","answer":"X","reason_options":[{"t":"확인은 직접 가 보거나 누리집에 들어가 보는 것이기 때문에","correct":true},{"t":"긴 이름은 언제나 믿을 만한 곳이기 때문에","mis":"K3-2-u3-X14"}],"mis":"K3-2-u3-X14","explanation":["이름 길이는 확인이 아니에요.","가서 보거나 들어가 봐요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#13','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C12',2,'match','auto','「모둠 화분」의 빈칸과 알맞은 이어 주는 말을 이으세요.','{}'::text[],false,'{"seq":13,"concept":"K3-2-u3-C12","difficulty":2,"kind":"match","stem":"「모둠 화분」의 빈칸과 알맞은 이어 주는 말을 이으세요.","pairs":[{"l":"㉠","r":"그러나"},{"l":"㉡","r":"그래서"},{"l":"㉢","r":"그리고"}],"mis":"K3-2-u3-X16","explanation":["㉠은 하기로 한 일과 반대예요.","㉡은 까닭이 앞에 있어요.","㉢은 일이 하나 더해져요."],"asset":{"type":"passage","lines":["다올이네 모둠은 교실 화분을 맡았습니다.","모둠 친구들은 아침마다 흙을 만져 보기로 했습니다.","( ㉠ ) 금요일에는 모두 깜빡 잊고 말았습니다.","( ㉡ ) 월요일 아침, 흙이 바싹 말라 있었습니다.","다올이는 잎이 아니라 흙 쪽으로 천천히 물을 주었습니다.","( ㉢ ) 물받이에 고인 물도 비웠습니다.","며칠 뒤, 처졌던 잎이 다시 고개를 들었습니다."],"title":"이야기 「모둠 화분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#14','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C15',2,'ox','auto','서진이 글에서 「먼저」 대신 「끝으로」를 맨 앞에 쓰면 읽는 사람이 차례를 헷갈릴 수 있어요.',ARRAY['K3-2-u3-X22']::text[],false,'{"seq":14,"concept":"K3-2-u3-C15","difficulty":2,"kind":"ox","stem":"서진이 글에서 「먼저」 대신 「끝으로」를 맨 앞에 쓰면 읽는 사람이 차례를 헷갈릴 수 있어요.","answer":"O","reason_options":[{"t":"차례를 나타내는 말은 일의 순서와 맞게 써야 하기 때문에","correct":true},{"t":"차례를 나타내는 말은 아무 순서로 써도 되기 때문에","mis":"K3-2-u3-X22"}],"mis":"K3-2-u3-X22","explanation":["「끝으로」는 마지막이에요.","맨 앞에 오면 어긋나요.","그래서 O예요."],"asset":{"type":"passage","lines":["급식을 다 먹은 뒤 식판을 정리하는 방법을 알려 드리겠습니다.","먼저, 남은 음식을 한쪽으로 모아 정해진 통에 덜어 냅니다.","다음으로, 숟가락과 젓가락을 수저 통에 넣습니다.","끝으로, 빈 식판을 정해진 곳에 포개어 놓습니다.","식판을 놓는 곳은 「급식실 이용 안내」에 그림으로 나와 있습니다.","이 차례대로 하면 급식실을 깨끗하게 쓸 수 있습니다.","■ 출처: 「급식실 이용 안내」, 학교 누리집."],"title":"학급 신문 「식판 정리하는 방법」 — 글 서진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#15','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C2',2,'error','auto','이용 설명서에 넣을 내용을 알아볼 곳을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u3-X02']::text[],false,'{"seq":15,"concept":"K3-2-u3-C2","difficulty":2,"kind":"error","stem":"이용 설명서에 넣을 내용을 알아볼 곳을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「모르는 건 그럴 것 같은 대로 짐작해서 쓰자.」","correct":true,"mis_target":"K3-2-u3-X02"},{"t":"친구 가 — 「도서관 앞 안내판을 보고 오자.」","mis":"K3-2-u3-X02"},{"t":"친구 나 — 「사서 선생님께 여쭈어보자.」","mis":"K3-2-u3-X02"}],"explanation":["알아볼 곳은 확인할 수 있는 곳이에요.","안내판과 선생님은 확인할 수 있어요.","친구 다는 짐작하자고 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#16','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C19',2,'mc','auto','「도서관 이용 설명서」를 모둠 글로 하나로 모을 때 할 일로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X28','K3-2-u3-X25','K3-2-u3-X02']::text[],false,'{"seq":16,"concept":"K3-2-u3-C19","difficulty":2,"kind":"mc","stem":"「도서관 이용 설명서」를 모둠 글로 하나로 모을 때 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"문단 사이를 이어 주는 말로 잇고 빠진 차례가 없는지 본다","correct":true},{"t":"가져온 자료의 출처는 지운다","mis":"K3-2-u3-X28"},{"t":"문단마다 똑같은 내용을 넣는다","mis":"K3-2-u3-X25"},{"t":"확인하지 않은 내용을 더 지어 넣는다","mis":"K3-2-u3-X02"}],"explanation":["모을 때 할 일이 있어요.","잇고, 빠진 것을 봐요.","출처는 끝에 모아 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#17','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C1',3,'ox','auto','「식판 정리하는 방법」은 차례를 나타내는 말이 있어 처음 급식을 먹는 1학년 동생도 따라 할 수 있어요.',ARRAY['K3-2-u3-X01']::text[],false,'{"seq":17,"concept":"K3-2-u3-C1","difficulty":3,"kind":"ox","stem":"「식판 정리하는 방법」은 차례를 나타내는 말이 있어 처음 급식을 먹는 1학년 동생도 따라 할 수 있어요.","answer":"O","reason_options":[{"t":"먼저·다음으로·끝으로가 무엇부터 할지 알려 주기 때문에","correct":true},{"t":"글이 길어서 누구나 따라 할 수 있기 때문에","mis":"K3-2-u3-X01"}],"mis":"K3-2-u3-X01","explanation":["차례 말이 셋 있어요.","무엇부터 할지 보여요.","그래서 O예요."],"asset":{"type":"passage","lines":["급식을 다 먹은 뒤 식판을 정리하는 방법을 알려 드리겠습니다.","먼저, 남은 음식을 한쪽으로 모아 정해진 통에 덜어 냅니다.","다음으로, 숟가락과 젓가락을 수저 통에 넣습니다.","끝으로, 빈 식판을 정해진 곳에 포개어 놓습니다.","식판을 놓는 곳은 「급식실 이용 안내」에 그림으로 나와 있습니다.","이 차례대로 하면 급식실을 깨끗하게 쓸 수 있습니다.","■ 출처: 「급식실 이용 안내」, 학교 누리집."],"title":"학급 신문 「식판 정리하는 방법」 — 글 서진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#18','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C8',3,'ox','auto','민결이 글의 ㉱는 출처가 있으니, 어떤 곳에서 가져왔는지 살펴보지 않아도 그대로 믿으면 돼요.',ARRAY['K3-2-u3-X12']::text[],false,'{"seq":18,"concept":"K3-2-u3-C8","difficulty":3,"kind":"ox","stem":"민결이 글의 ㉱는 출처가 있으니, 어떤 곳에서 가져왔는지 살펴보지 않아도 그대로 믿으면 돼요.","answer":"X","reason_options":[{"t":"출처가 있어도 어떤 곳인지 살펴보고 생각해야 하기 때문에","correct":true},{"t":"출처가 있는 자료는 언제나 맞기 때문에","mis":"K3-2-u3-X12"}],"mis":"K3-2-u3-X12","explanation":["연호의 말과 같아요.","하경이는 살펴보자고 했어요.","그래서 X예요."],"asset":{"type":"passage","lines":["놀이 기구를 탈 때에는 차례를 지켜야 합니다. 한꺼번에 몰리면 부딪치기 쉽기 때문입니다.","㉮ 옆 반 친구에게 들으니 미끄럼틀 앞에서 다툰 일이 있었다고 합니다.","㉯ 운동장 앞 「놀이 기구 이용 안내」 안내판에 따르면,","한 사람씩 차례대로 타야 한다고 합니다.","㉰ [그림] 미끄럼틀 앞에 한 줄로 서 있는 모습을 그린 그림","㉱ [그림] 그네 둘레에 그어 둔 선을 나타낸 그림","■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","우리 모두 놀이 기구는 차례를 지켜 타요."],"title":"주장하는 글 「놀이 기구는 차례를 지켜 타요」 — 글 민결"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#19','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C9',3,'mc','auto','「물 주는 차례표」에 따르면 우리 반은 언제 텃밭을 맡나요?',ARRAY['K3-2-u3-X08']::text[],false,'{"seq":19,"concept":"K3-2-u3-C9","difficulty":3,"kind":"mc","stem":"「물 주는 차례표」에 따르면 우리 반은 언제 텃밭을 맡나요?","options":[{"t":"목요일","correct":true},{"t":"봄","mis":"K3-2-u3-X08"},{"t":"흙이 마를 때마다 매일","mis":"K3-2-u3-X08"},{"t":"금요일","mis":"K3-2-u3-X08"}],"explanation":["「…에 따르면」 뒤를 읽어요.","맡는 날이 나와요.","목요일이에요."],"asset":{"type":"passage","lines":["교실 뒤에 붙여 둔 「물 주는 차례표」에 따르면,","우리 반은 목요일에 텃밭을 맡습니다. 흙이 말랐을 때 물을 줍니다.","[그림] 물뿌리개로 텃밭에 물을 주는 모습을 그린 그림","■ 출처: 「물 주는 차례표」, 교실 뒤 게시판.","상추는 잎을 뜯어 먹습니다. 다 뜯지 않고 몇 장을 남겨 두면 잎이 다시 자랍니다.","[그림] 상추 잎을 뜯는 손을 그린 그림","텃밭을 가꾸려면 물뿌리개와 모종삽을 마련해야 합니다.","작은 텃밭이지만 손이 가는 곳입니다."],"title":"설명하는 글 「우리 학교 텃밭」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#20','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C13',3,'mc','auto','「모둠 화분」을 문장마다 이어 주는 말을 넣어 다시 쓴 친구에게 해 줄 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X18','K3-2-u3-X19','K3-2-u3-X16']::text[],false,'{"seq":20,"concept":"K3-2-u3-C13","difficulty":3,"kind":"mc","stem":"「모둠 화분」을 문장마다 이어 주는 말을 넣어 다시 쓴 친구에게 해 줄 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“앞뒤 뜻이 이어지는 곳에만 남기면 더 읽기 좋아.”","correct":true},{"t":"“더 많이 넣으면 더 좋아.”","mis":"K3-2-u3-X18"},{"t":"“하나도 넣지 마.”","mis":"K3-2-u3-X19"},{"t":"“모두 「그러나」로 바꿔.”","mis":"K3-2-u3-X16"}],"explanation":["연호처럼 많이 넣었어요.","개수가 아니에요.","필요한 곳에만 남겨요."],"asset":{"type":"passage","lines":["다올이네 모둠은 교실 화분을 맡았습니다.","모둠 친구들은 아침마다 흙을 만져 보기로 했습니다.","( ㉠ ) 금요일에는 모두 깜빡 잊고 말았습니다.","( ㉡ ) 월요일 아침, 흙이 바싹 말라 있었습니다.","다올이는 잎이 아니라 흙 쪽으로 천천히 물을 주었습니다.","( ㉢ ) 물받이에 고인 물도 비웠습니다.","며칠 뒤, 처졌던 잎이 다시 고개를 들었습니다."],"title":"이야기 「모둠 화분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#21','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C17',3,'ox','auto','서진이 글의 첫 문장 「급식을 다 먹은 뒤 식판을 정리하는 방법을 알려 드리겠습니다.」는 처음 부분으로 알맞아요.',ARRAY['K3-2-u3-X25']::text[],false,'{"seq":21,"concept":"K3-2-u3-C17","difficulty":3,"kind":"ox","stem":"서진이 글의 첫 문장 「급식을 다 먹은 뒤 식판을 정리하는 방법을 알려 드리겠습니다.」는 처음 부분으로 알맞아요.","answer":"O","reason_options":[{"t":"무엇을 설명할 글인지 밝혀 주기 때문에","correct":true},{"t":"처음 부분에는 일의 차례를 자세히 써야 하기 때문에","mis":"K3-2-u3-X25"}],"mis":"K3-2-u3-X25","explanation":["처음에는 무엇을 설명할지 밝혀요.","첫 문장이 그 일을 해요.","그래서 O예요."],"asset":{"type":"passage","lines":["급식을 다 먹은 뒤 식판을 정리하는 방법을 알려 드리겠습니다.","먼저, 남은 음식을 한쪽으로 모아 정해진 통에 덜어 냅니다.","다음으로, 숟가락과 젓가락을 수저 통에 넣습니다.","끝으로, 빈 식판을 정해진 곳에 포개어 놓습니다.","식판을 놓는 곳은 「급식실 이용 안내」에 그림으로 나와 있습니다.","이 차례대로 하면 급식실을 깨끗하게 쓸 수 있습니다.","■ 출처: 「급식실 이용 안내」, 학교 누리집."],"title":"학급 신문 「식판 정리하는 방법」 — 글 서진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#22','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C16',3,'ox','auto','모둠 설명서에 사진을 가져왔는데 어디에서 가져온 것인지 확인할 수 없다면 그럴듯한 곳을 적어 두면 돼요.',ARRAY['K3-2-u3-X23']::text[],false,'{"seq":22,"concept":"K3-2-u3-C16","difficulty":3,"kind":"ox","stem":"모둠 설명서에 사진을 가져왔는데 어디에서 가져온 것인지 확인할 수 없다면 그럴듯한 곳을 적어 두면 돼요.","answer":"X","reason_options":[{"t":"출처는 지어내는 것이 아니라 확인하는 것이라, 확인할 수 없으면 쓰지 않기 때문에","correct":true},{"t":"출처 칸은 비워 두면 안 되니 무엇이든 적어야 하기 때문에","mis":"K3-2-u3-X23"}],"mis":"K3-2-u3-X23","explanation":["출처는 확인하는 것이에요.","확인할 수 없으면 쓰지 않아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#23','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C16',4,'mc','auto','서진이가 글을 다 쓴 뒤 「식판 놓는 곳」을 어디서 알아냈는지 기억나지 않는다면 가장 알맞은 행동은 무엇인가요?',ARRAY['K3-2-u3-X23','K3-2-u3-X06','K3-2-u3-X07']::text[],false,'{"seq":23,"concept":"K3-2-u3-C16","difficulty":4,"kind":"mc","stem":"서진이가 글을 다 쓴 뒤 「식판 놓는 곳」을 어디서 알아냈는지 기억나지 않는다면 가장 알맞은 행동은 무엇인가요?","options":[{"t":"학교 누리집에 다시 들어가 「급식실 이용 안내」에 정말 있는지 확인한 뒤 적고, 찾지 못하면 그 문장을 뺀다","correct":true},{"t":"「급식실 규칙집」처럼 그럴듯한 이름을 지어 적는다","mis":"K3-2-u3-X23"},{"t":"출처 없이 내가 아는 것처럼 둔다","mis":"K3-2-u3-X06"},{"t":"출처를 확인할 수 없으니 글 전체를 버린다","mis":"K3-2-u3-X07"}],"explanation":["출처는 지어내지 않아요.","다시 확인해요.","확인이 안 되면 그 내용만 빼요."],"asset":{"type":"passage","lines":["급식을 다 먹은 뒤 식판을 정리하는 방법을 알려 드리겠습니다.","먼저, 남은 음식을 한쪽으로 모아 정해진 통에 덜어 냅니다.","다음으로, 숟가락과 젓가락을 수저 통에 넣습니다.","끝으로, 빈 식판을 정해진 곳에 포개어 놓습니다.","식판을 놓는 곳은 「급식실 이용 안내」에 그림으로 나와 있습니다.","이 차례대로 하면 급식실을 깨끗하게 쓸 수 있습니다.","■ 출처: 「급식실 이용 안내」, 학교 누리집."],"title":"학급 신문 「식판 정리하는 방법」 — 글 서진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#24','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C17',4,'essay','teacher','우리 반 친구들에게 「실내화를 신발장에 넣는 방법」을 알려 주는 글을 처음·가운데·끝으로 나누어 쓰세요. 가운데에는 차례를 나타내는 말을 세 개 넣으세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u3-C17","difficulty":4,"kind":"essay","stem":"우리 반 친구들에게 「실내화를 신발장에 넣는 방법」을 알려 주는 글을 처음·가운데·끝으로 나누어 쓰세요. 가운데에는 차례를 나타내는 말을 세 개 넣으세요.","answer_guide":{"answer":"예: 처음 — 실내화를 신발장에 가지런히 넣는 방법을 알려 드리겠습니다. 가운데 — 먼저, 내 번호가 붙은 칸을 찾습니다. 다음으로, 실내화 두 짝을 나란히 맞춥니다. 끝으로, 칸 안쪽까지 밀어 넣습니다. 끝 — 이 차례대로 하면 신발장을 깔끔하게 쓸 수 있습니다.","scoring_points":["처음·가운데·끝으로 나누었는가","가운데에 차례를 나타내는 말 세 개를 순서대로 넣었는가","끝에 간추리는 말을 썼는가"]},"explanation":["내가 늘 하는 일이에요.","차례 말 셋을 순서대로 넣어요.","끝에서 간추려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_c#25','kor',3,2,'u3','','g3_2_kor_u3_review_c','unit_review','K3-2-u3-C13',4,'essay','teacher','이 단원에서 배운 이어 주는 말을 정리해 「그리고」·「그러나」·「그래서」의 쓰임을 쓰고, 이어 주는 말을 얼마나 쓰면 좋은지 내 생각을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u3-C13","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 이어 주는 말을 정리해 「그리고」·「그러나」·「그래서」의 쓰임을 쓰고, 이어 주는 말을 얼마나 쓰면 좋은지 내 생각을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 「그리고」는 앞과 비슷한 내용이 이어질 때, 「그러나」는 앞과 반대되는 내용이 이어질 때, 「그래서」는 앞이 뒤의 까닭이 될 때 쓴다. 이어 주는 말은 문장마다 넣을 필요도 없고 하나도 안 쓸 것도 아니다. 앞뒤 뜻의 관계를 드러내야 하는 곳에 알맞게 쓰면 읽는 사람이 글을 더 잘 이해하기 때문이다.","scoring_points":["세 말의 쓰임을 바르게 썼는가","많이 쓸수록 좋은 것도, 안 쓰는 것도 아니라고 썼는가","앞뒤 뜻의 관계로 까닭을 썼는가"]},"explanation":["비슷함·반대·까닭이에요.","연호와 하선이를 떠올려요.","앞뒤 뜻에 맞게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#1','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C1',1,'mc','auto','설명하는 글로 쓰기에 가장 알맞은 글감은 무엇인가요?',ARRAY['K3-2-u3-X31']::text[],false,'{"seq":1,"concept":"K3-2-u3-C1","difficulty":1,"kind":"mc","stem":"설명하는 글로 쓰기에 가장 알맞은 글감은 무엇인가요?","options":[{"t":"교실 화분에 물 주는 방법","correct":true},{"t":"어제 꾼 꿈 이야기","mis":"K3-2-u3-X31"},{"t":"내가 좋아하는 색깔과 그 까닭","mis":"K3-2-u3-X31"},{"t":"운동회 날 느낀 기쁨","mis":"K3-2-u3-X31"}],"explanation":["설명하는 글은 방법이나 차례를 알려 줘요.","읽는 사람이 따라 할 수 있어요.","물 주는 방법이 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#2','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C3',1,'sa','auto','책이나 누리집에서 가져온 자료가 어디에서 왔는지 알려 주는 것을 무엇이라고 하나요?','{}'::text[],false,'{"seq":2,"concept":"K3-2-u3-C3","difficulty":1,"kind":"sa","stem":"책이나 누리집에서 가져온 자료가 어디에서 왔는지 알려 주는 것을 무엇이라고 하나요?","answer":["출처"],"explanation":["자료가 온 곳을 알려 줘요.","「■」와 함께 적기도 해요.","출처예요."],"mis":"K3-2-u3-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#3','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C5',1,'mc','auto','출처를 밝히면 읽는 사람은 무엇을 할 수 있게 되나요?',ARRAY['K3-2-u3-X10','K3-2-u3-X03','K3-2-u3-X06']::text[],false,'{"seq":3,"concept":"K3-2-u3-C5","difficulty":1,"kind":"mc","stem":"출처를 밝히면 읽는 사람은 무엇을 할 수 있게 되나요?","options":[{"t":"믿을 만한 자료인지 살펴볼 수 있다","correct":true},{"t":"글을 읽지 않아도 된다","mis":"K3-2-u3-X10"},{"t":"글쓴이의 나이를 알 수 있다","mis":"K3-2-u3-X03"},{"t":"그 자료를 내 것처럼 쓸 수 있다","mis":"K3-2-u3-X06"}],"explanation":["읽는 사람 쪽에서 생각해요.","어디서 왔는지 알게 돼요.","살펴볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#4','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C6',1,'mc','auto','민결이 글에서 ㉯가 알려 주는 내용은 무엇인가요?',ARRAY['K3-2-u3-X08']::text[],false,'{"seq":4,"concept":"K3-2-u3-C6","difficulty":1,"kind":"mc","stem":"민결이 글에서 ㉯가 알려 주는 내용은 무엇인가요?","options":[{"t":"한 사람씩 차례대로 타야 한다는 것","correct":true},{"t":"미끄럼틀 앞에서 다툰 일","mis":"K3-2-u3-X08"},{"t":"그네 둘레에 선이 있다는 것","mis":"K3-2-u3-X08"},{"t":"놀이 기구를 타지 말라는 것","mis":"K3-2-u3-X08"}],"explanation":["㉯가 붙은 줄을 찾아요.","다음 줄까지 이어져요.","한 사람씩 차례대로예요."],"asset":{"type":"passage","lines":["놀이 기구를 탈 때에는 차례를 지켜야 합니다. 한꺼번에 몰리면 부딪치기 쉽기 때문입니다.","㉮ 옆 반 친구에게 들으니 미끄럼틀 앞에서 다툰 일이 있었다고 합니다.","㉯ 운동장 앞 「놀이 기구 이용 안내」 안내판에 따르면,","한 사람씩 차례대로 타야 한다고 합니다.","㉰ [그림] 미끄럼틀 앞에 한 줄로 서 있는 모습을 그린 그림","㉱ [그림] 그네 둘레에 그어 둔 선을 나타낸 그림","■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","우리 모두 놀이 기구는 차례를 지켜 타요."],"title":"주장하는 글 「놀이 기구는 차례를 지켜 타요」 — 글 민결"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#5','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C8',1,'mc','auto','이 단원에서 출처는 어떤 표와 같다고 했나요?',ARRAY['K3-2-u3-X12','K3-2-u3-X13','K3-2-u3-X10']::text[],false,'{"seq":5,"concept":"K3-2-u3-C8","difficulty":1,"kind":"mc","stem":"이 단원에서 출처는 어떤 표와 같다고 했나요?","options":[{"t":"살펴볼 수 있게 해 주는 표","correct":true},{"t":"무조건 믿으라는 표","mis":"K3-2-u3-X12"},{"t":"믿지 말라는 표","mis":"K3-2-u3-X13"},{"t":"빨리 읽으라는 표","mis":"K3-2-u3-X10"}],"explanation":["14차시에 다시 만난 물음이에요.","「믿어라」는 표가 아니에요.","「살펴볼 수 있다」는 표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#6','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C12',1,'mc','auto','「그러나」는 언제 쓰는 말인가요?',ARRAY['K3-2-u3-X16','K3-2-u3-X17']::text[],false,'{"seq":6,"concept":"K3-2-u3-C12","difficulty":1,"kind":"mc","stem":"「그러나」는 언제 쓰는 말인가요?","options":[{"t":"앞과 반대되는 내용이 이어질 때","correct":true},{"t":"앞과 비슷한 내용이 이어질 때","mis":"K3-2-u3-X16"},{"t":"앞이 뒤의 까닭이 될 때","mis":"K3-2-u3-X16"},{"t":"때를 나타낼 때","mis":"K3-2-u3-X17"}],"explanation":["채호의 체육 시간을 떠올려요.","기다렸는데 비가 왔어요.","반대되는 내용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#7','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C14',1,'ox','auto','설명하는 글을 쓰기 전에는 이 글을 누가 읽을지부터 생각해요.',ARRAY['K3-2-u3-X21']::text[],false,'{"seq":7,"concept":"K3-2-u3-C14","difficulty":1,"kind":"ox","stem":"설명하는 글을 쓰기 전에는 이 글을 누가 읽을지부터 생각해요.","answer":"O","reason_options":[{"t":"읽을 사람에 따라 어디까지 자세히 쓸지가 달라지기 때문에","correct":true},{"t":"읽을 사람과 상관없이 글은 언제나 같기 때문에","mis":"K3-2-u3-X21"}],"mis":"K3-2-u3-X21","explanation":["1학년 동생과 우리 반 친구는 달라요.","읽을 사람부터 정해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#8','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C20',1,'blank','auto','「짝이 그러는데 내일 체육관에서 수업을 한(　).」의 빈칸에 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X29']::text[],false,'{"seq":8,"concept":"K3-2-u3-C20","difficulty":1,"kind":"blank","stem":"「짝이 그러는데 내일 체육관에서 수업을 한(　).」의 빈칸에 알맞은 것은 무엇인가요?","options":[{"t":"대","correct":true},{"t":"데","mis":"K3-2-u3-X29"},{"t":"고","mis":"K3-2-u3-X29"},{"t":"네","mis":"K3-2-u3-X29"}],"explanation":["짝이 그러는데 — 들은 말이에요.","남의 말을 전해요.","‘대’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#9','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C4',2,'match','auto','민결이 글에서 출처를 밝힌 방법과 밝힌 곳을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u3-C4","difficulty":2,"kind":"match","stem":"민결이 글에서 출처를 밝힌 방법과 밝힌 곳을 알맞게 이으세요.","pairs":[{"l":"「놀이 기구 이용 안내」 안내판에 따르면","r":"글 속 문장 안"},{"l":"■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","r":"그림 자료 바로 아래"},{"l":"옆 반 친구에게 들으니","r":"출처를 밝히지 않음"}],"mis":"K3-2-u3-X04","explanation":["출처는 여러 곳에 적어요.","문장 안과 그림 아래예요.","들은 이야기는 출처가 없어요."],"asset":{"type":"passage","lines":["놀이 기구를 탈 때에는 차례를 지켜야 합니다. 한꺼번에 몰리면 부딪치기 쉽기 때문입니다.","㉮ 옆 반 친구에게 들으니 미끄럼틀 앞에서 다툰 일이 있었다고 합니다.","㉯ 운동장 앞 「놀이 기구 이용 안내」 안내판에 따르면,","한 사람씩 차례대로 타야 한다고 합니다.","㉰ [그림] 미끄럼틀 앞에 한 줄로 서 있는 모습을 그린 그림","㉱ [그림] 그네 둘레에 그어 둔 선을 나타낸 그림","■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","우리 모두 놀이 기구는 차례를 지켜 타요."],"title":"주장하는 글 「놀이 기구는 차례를 지켜 타요」 — 글 민결"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#10','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C6',2,'sa','auto','민결이 글의 자료 ㉮~㉱ 가운데 출처가 적혀 있는 자료는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u3-C6","difficulty":2,"kind":"sa","stem":"민결이 글의 자료 ㉮~㉱ 가운데 출처가 적혀 있는 자료는 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["하나씩 살펴봐요.","㉯와 ㉱에 있어요.","2개예요."],"asset":{"type":"passage","lines":["놀이 기구를 탈 때에는 차례를 지켜야 합니다. 한꺼번에 몰리면 부딪치기 쉽기 때문입니다.","㉮ 옆 반 친구에게 들으니 미끄럼틀 앞에서 다툰 일이 있었다고 합니다.","㉯ 운동장 앞 「놀이 기구 이용 안내」 안내판에 따르면,","한 사람씩 차례대로 타야 한다고 합니다.","㉰ [그림] 미끄럼틀 앞에 한 줄로 서 있는 모습을 그린 그림","㉱ [그림] 그네 둘레에 그어 둔 선을 나타낸 그림","■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","우리 모두 놀이 기구는 차례를 지켜 타요."],"title":"주장하는 글 「놀이 기구는 차례를 지켜 타요」 — 글 민결"},"mis":"K3-2-u3-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#11','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C7',2,'mc','auto','「급식실 이용 안내」라는 출처 덕분에 할 수 있는 일로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X10','K3-2-u3-X12']::text[],false,'{"seq":11,"concept":"K3-2-u3-C7","difficulty":2,"kind":"mc","stem":"「급식실 이용 안내」라는 출처 덕분에 할 수 있는 일로 알맞은 것은 무엇인가요?","options":[{"t":"학교 누리집에 들어가 식판 놓는 곳 그림을 찾아본다","correct":true},{"t":"서진이 글을 더 빨리 읽는다","mis":"K3-2-u3-X10"},{"t":"글을 읽지 않고 내용을 안다","mis":"K3-2-u3-X10"},{"t":"출처가 있으니 확인 없이 다 믿는다","mis":"K3-2-u3-X12"}],"explanation":["출처가 학교 누리집이에요.","들어가 볼 수 있어요.","더 찾아볼 수 있어요."],"asset":{"type":"passage","lines":["급식을 다 먹은 뒤 식판을 정리하는 방법을 알려 드리겠습니다.","먼저, 남은 음식을 한쪽으로 모아 정해진 통에 덜어 냅니다.","다음으로, 숟가락과 젓가락을 수저 통에 넣습니다.","끝으로, 빈 식판을 정해진 곳에 포개어 놓습니다.","식판을 놓는 곳은 「급식실 이용 안내」에 그림으로 나와 있습니다.","이 차례대로 하면 급식실을 깨끗하게 쓸 수 있습니다.","■ 출처: 「급식실 이용 안내」, 학교 누리집."],"title":"학급 신문 「식판 정리하는 방법」 — 글 서진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#12','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C10',2,'mc','auto','「모둠 화분」의 다올이네 모둠이 물뿌리개를 미리 「마련했다」면 무엇을 한 것인가요?',ARRAY['K3-2-u3-X15']::text[],false,'{"seq":12,"concept":"K3-2-u3-C10","difficulty":2,"kind":"mc","stem":"「모둠 화분」의 다올이네 모둠이 물뿌리개를 미리 「마련했다」면 무엇을 한 것인가요?","options":[{"t":"필요한 물뿌리개를 준비해 갖추었다","correct":true},{"t":"물뿌리개를 보살폈다","mis":"K3-2-u3-X15"},{"t":"물뿌리개를 버렸다","mis":"K3-2-u3-X15"},{"t":"물뿌리개를 쓸 차례가 돌아왔다","mis":"K3-2-u3-X15"}],"explanation":["마련하다의 뜻을 떠올려요.","필요한 것을 갖추는 거예요.","준비해 갖추었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#13','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C13',2,'mc','auto','「모둠 화분」에서 ㉠·㉡·㉢을 모두 비워 둔 채 읽으면 어떤 점이 아쉬운가요?',ARRAY['K3-2-u3-X19','K3-2-u3-X22']::text[],false,'{"seq":13,"concept":"K3-2-u3-C13","difficulty":2,"kind":"mc","stem":"「모둠 화분」에서 ㉠·㉡·㉢을 모두 비워 둔 채 읽으면 어떤 점이 아쉬운가요?","options":[{"t":"문장들이 왜 이어지는지(반대·까닭·더하기) 잘 드러나지 않는다","correct":true},{"t":"아쉬운 점이 없다 — 이어 주는 말은 없어도 된다","mis":"K3-2-u3-X19"},{"t":"글이 짧아져 오히려 좋아진다","mis":"K3-2-u3-X19"},{"t":"이야기의 차례가 바뀐다","mis":"K3-2-u3-X22"}],"explanation":["하선이처럼 하나도 안 쓴 경우예요.","말은 되지만 관계가 숨어요.","왜 이어지는지 안 보여요."],"asset":{"type":"passage","lines":["다올이네 모둠은 교실 화분을 맡았습니다.","모둠 친구들은 아침마다 흙을 만져 보기로 했습니다.","( ㉠ ) 금요일에는 모두 깜빡 잊고 말았습니다.","( ㉡ ) 월요일 아침, 흙이 바싹 말라 있었습니다.","다올이는 잎이 아니라 흙 쪽으로 천천히 물을 주었습니다.","( ㉢ ) 물받이에 고인 물도 비웠습니다.","며칠 뒤, 처졌던 잎이 다시 고개를 들었습니다."],"title":"이야기 「모둠 화분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#14','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C15',2,'mc','auto','서진이가 「남은 음식을 한쪽으로 모아 정해진 통에 덜어 냅니다」처럼 쉬운 말로 풀어 쓴 까닭은 무엇인가요?',ARRAY['K3-2-u3-X05','K3-2-u3-X22','K3-2-u3-X24']::text[],false,'{"seq":14,"concept":"K3-2-u3-C15","difficulty":2,"kind":"mc","stem":"서진이가 「남은 음식을 한쪽으로 모아 정해진 통에 덜어 냅니다」처럼 쉬운 말로 풀어 쓴 까닭은 무엇인가요?","options":[{"t":"읽는 사람이 뜻을 바로 알 수 있게 하려고","correct":true},{"t":"글을 길어 보이게 하려고","mis":"K3-2-u3-X05"},{"t":"차례를 바꾸려고","mis":"K3-2-u3-X22"},{"t":"출처를 밝히려고","mis":"K3-2-u3-X24"}],"explanation":["하경이의 「과습」을 떠올려요.","어려운 말은 풀어 써요.","뜻을 바로 알게 하려고요."],"asset":{"type":"passage","lines":["급식을 다 먹은 뒤 식판을 정리하는 방법을 알려 드리겠습니다.","먼저, 남은 음식을 한쪽으로 모아 정해진 통에 덜어 냅니다.","다음으로, 숟가락과 젓가락을 수저 통에 넣습니다.","끝으로, 빈 식판을 정해진 곳에 포개어 놓습니다.","식판을 놓는 곳은 「급식실 이용 안내」에 그림으로 나와 있습니다.","이 차례대로 하면 급식실을 깨끗하게 쓸 수 있습니다.","■ 출처: 「급식실 이용 안내」, 학교 누리집."],"title":"학급 신문 「식판 정리하는 방법」 — 글 서진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#15','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C16',2,'mc','auto','찾아본 안내 이름이 기억나지 않을 때 서진이가 할 일로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X23','K3-2-u3-X06']::text[],false,'{"seq":15,"concept":"K3-2-u3-C16","difficulty":2,"kind":"mc","stem":"찾아본 안내 이름이 기억나지 않을 때 서진이가 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"학교 누리집에 다시 들어가 확인해 적는다","correct":true},{"t":"「급식 박사」처럼 그럴듯한 이름을 지어 적는다","mis":"K3-2-u3-X23"},{"t":"출처 칸을 아무 말로 채운다","mis":"K3-2-u3-X23"},{"t":"내가 알아낸 것처럼 쓴다","mis":"K3-2-u3-X06"}],"explanation":["출처는 확인하는 것이에요.","다시 가서 봐요.","지어내지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#16','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C19',2,'mc','auto','이용 설명서에 넣는 자료의 종류와 출처에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X28','K3-2-u3-X23']::text[],false,'{"seq":16,"concept":"K3-2-u3-C19","difficulty":2,"kind":"mc","stem":"이용 설명서에 넣는 자료의 종류와 출처에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"안내판·안내장·누리집 알림 글·사진처럼 종류가 달라도 가져온 곳은 똑같이 적는다","correct":true},{"t":"사진은 출처를 적지 않는다","mis":"K3-2-u3-X28"},{"t":"안내판만 출처를 적는다","mis":"K3-2-u3-X28"},{"t":"종류가 다르면 출처를 지어 적는다","mis":"K3-2-u3-X23"}],"explanation":["자료의 종류는 여러 가지예요.","모두 가져온 자료예요.","가져온 곳을 똑같이 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#17','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C1',3,'mc','auto','「복도에서는 걸어 다녀요」와 「식판 정리하는 방법」의 다른 점으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u3-X31','K3-2-u3-X09']::text[],false,'{"seq":17,"concept":"K3-2-u3-C1","difficulty":3,"kind":"mc","stem":"「복도에서는 걸어 다녀요」와 「식판 정리하는 방법」의 다른 점으로 알맞은 것은 무엇인가요?","options":[{"t":"앞의 글은 의견을 내세우는 글이고, 뒤의 글은 일의 차례를 알려 주는 설명하는 글이다","correct":true},{"t":"둘 다 느낌을 쓴 글이다","mis":"K3-2-u3-X31"},{"t":"앞의 글은 설명하는 글이고 뒤의 글은 이야기이다","mis":"K3-2-u3-X31"},{"t":"둘 다 출처가 하나도 없다","mis":"K3-2-u3-X09"}],"explanation":["앞의 글은 걸어 다니자고 했어요.","뒤의 글은 차례를 알려 줘요.","글의 갈래가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#18','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C8',3,'mc','auto','민결이 글을 읽고 출처에 대해 가장 알맞게 말한 것은 무엇인가요?',ARRAY['K3-2-u3-X12','K3-2-u3-X13','K3-2-u3-X09']::text[],false,'{"seq":18,"concept":"K3-2-u3-C8","difficulty":3,"kind":"mc","stem":"민결이 글을 읽고 출처에 대해 가장 알맞게 말한 것은 무엇인가요?","options":[{"t":"“㉯·㉱는 학교 안에 있는 곳이라 가서 살펴볼 수 있겠어. ㉮는 확인할 길이 없네.”","correct":true},{"t":"“출처가 있든 없든 다 믿을래.”","mis":"K3-2-u3-X12"},{"t":"“출처가 있어도 다 거짓일 수 있으니 하나도 안 믿을래.”","mis":"K3-2-u3-X13"},{"t":"“그림이 있으니 ㉰가 가장 믿을 만해.”","mis":"K3-2-u3-X09"}],"explanation":["출처가 있는 것과 없는 것을 갈라요.","있는 것은 가서 살펴봐요.","없는 것은 확인할 길이 없어요."],"asset":{"type":"passage","lines":["놀이 기구를 탈 때에는 차례를 지켜야 합니다. 한꺼번에 몰리면 부딪치기 쉽기 때문입니다.","㉮ 옆 반 친구에게 들으니 미끄럼틀 앞에서 다툰 일이 있었다고 합니다.","㉯ 운동장 앞 「놀이 기구 이용 안내」 안내판에 따르면,","한 사람씩 차례대로 타야 한다고 합니다.","㉰ [그림] 미끄럼틀 앞에 한 줄로 서 있는 모습을 그린 그림","㉱ [그림] 그네 둘레에 그어 둔 선을 나타낸 그림","■ 출처: 「놀이터에서 지킬 것」, 보건실 안내장.","우리 모두 놀이 기구는 차례를 지켜 타요."],"title":"주장하는 글 「놀이 기구는 차례를 지켜 타요」 — 글 민결"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#19','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C11',3,'ox','auto','「급식실 이용 안내」가 정말 학교 누리집에 있는지 들어가 보는 것은 출처를 확인하는 방법이에요.',ARRAY['K3-2-u3-X14']::text[],false,'{"seq":19,"concept":"K3-2-u3-C11","difficulty":3,"kind":"ox","stem":"「급식실 이용 안내」가 정말 학교 누리집에 있는지 들어가 보는 것은 출처를 확인하는 방법이에요.","answer":"O","reason_options":[{"t":"적혀 있는 곳에 직접 가 보는 것이 확인이기 때문에","correct":true},{"t":"출처는 이름만 보면 되고 확인할 필요가 없기 때문에","mis":"K3-2-u3-X14"}],"mis":"K3-2-u3-X14","explanation":["누리집에 들어가 봐요.","그것이 확인이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#20','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C12',3,'ox','auto','「모둠 화분」의 마지막 문장 「며칠 뒤, 처졌던 잎이 다시 고개를 들었습니다.」 앞에 「그러나」를 넣으면 앞 문장과 뜻이 알맞게 이어져요.',ARRAY['K3-2-u3-X16']::text[],false,'{"seq":20,"concept":"K3-2-u3-C12","difficulty":3,"kind":"ox","stem":"「모둠 화분」의 마지막 문장 「며칠 뒤, 처졌던 잎이 다시 고개를 들었습니다.」 앞에 「그러나」를 넣으면 앞 문장과 뜻이 알맞게 이어져요.","answer":"X","reason_options":[{"t":"물을 주고 고인 물을 비운 일이 잎이 다시 선 까닭에 가까워 반대되는 내용이 아니기 때문에","correct":true},{"t":"「그러나」는 어느 문장 앞에나 넣을 수 있기 때문에","mis":"K3-2-u3-X16"}],"mis":"K3-2-u3-X16","explanation":["물을 주고 물받이를 비웠어요.","그 뒤 잎이 살아났어요.","반대가 아니라 X예요."],"asset":{"type":"passage","lines":["다올이네 모둠은 교실 화분을 맡았습니다.","모둠 친구들은 아침마다 흙을 만져 보기로 했습니다.","( ㉠ ) 금요일에는 모두 깜빡 잊고 말았습니다.","( ㉡ ) 월요일 아침, 흙이 바싹 말라 있었습니다.","다올이는 잎이 아니라 흙 쪽으로 천천히 물을 주었습니다.","( ㉢ ) 물받이에 고인 물도 비웠습니다.","며칠 뒤, 처졌던 잎이 다시 고개를 들었습니다."],"title":"이야기 「모둠 화분」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#21','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C15',3,'mc','auto','서진이 글에서 「다음으로」와 「끝으로」 문장의 차례를 바꾸면 어떤 일이 생기나요?',ARRAY['K3-2-u3-X22','K3-2-u3-X09','K3-2-u3-X01']::text[],false,'{"seq":21,"concept":"K3-2-u3-C15","difficulty":3,"kind":"mc","stem":"서진이 글에서 「다음으로」와 「끝으로」 문장의 차례를 바꾸면 어떤 일이 생기나요?","options":[{"t":"식판을 먼저 포개어 놓고 나서 수저를 넣게 되어 따라 하기 어려워진다","correct":true},{"t":"아무 일도 없다 — 차례 말은 꾸밈말이라서","mis":"K3-2-u3-X22"},{"t":"출처가 사라진다","mis":"K3-2-u3-X09"},{"t":"글이 짧아진다","mis":"K3-2-u3-X01"}],"explanation":["바뀐 차례대로 따라 해 봐요.","식판을 놓은 뒤에 수저가 남아요.","차례가 어긋나요."],"asset":{"type":"passage","lines":["급식을 다 먹은 뒤 식판을 정리하는 방법을 알려 드리겠습니다.","먼저, 남은 음식을 한쪽으로 모아 정해진 통에 덜어 냅니다.","다음으로, 숟가락과 젓가락을 수저 통에 넣습니다.","끝으로, 빈 식판을 정해진 곳에 포개어 놓습니다.","식판을 놓는 곳은 「급식실 이용 안내」에 그림으로 나와 있습니다.","이 차례대로 하면 급식실을 깨끗하게 쓸 수 있습니다.","■ 출처: 「급식실 이용 안내」, 학교 누리집."],"title":"학급 신문 「식판 정리하는 방법」 — 글 서진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#22','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C20',3,'mc','auto','「내가 먹어 보니 텃밭 상추가 맛있(　).」와 「친구에게 들어 보니 그 책이 재미있(　).」의 빈칸을 차례대로 쓴 것은 무엇인가요?',ARRAY['K3-2-u3-X29']::text[],false,'{"seq":22,"concept":"K3-2-u3-C20","difficulty":3,"kind":"mc","stem":"「내가 먹어 보니 텃밭 상추가 맛있(　).」와 「친구에게 들어 보니 그 책이 재미있(　).」의 빈칸을 차례대로 쓴 것은 무엇인가요?","options":[{"t":"데 · 대","correct":true},{"t":"데 · 데","mis":"K3-2-u3-X29"},{"t":"대 · 대","mis":"K3-2-u3-X29"},{"t":"대 · 데","mis":"K3-2-u3-X29"}],"explanation":["둘 다 ‘보니’가 있어요.","앞은 내가, 뒤는 친구에게 들었어요.","데 · 대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#23','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C19',4,'mc','auto','「놀이 기구 이용 설명서」를 모둠이 만들어 1학년 교실 앞에 붙이려고 해요. 가장 알맞게 준비한 모둠은 어디인가요?',ARRAY['K3-2-u3-X21','K3-2-u3-X02','K3-2-u3-X28']::text[],false,'{"seq":23,"concept":"K3-2-u3-C19","difficulty":4,"kind":"mc","stem":"「놀이 기구 이용 설명서」를 모둠이 만들어 1학년 교실 앞에 붙이려고 해요. 가장 알맞게 준비한 모둠은 어디인가요?","options":[{"t":"어떤 곳인지·타는 차례·지킬 것을 세 문단으로 나누고, 안내판에서 확인한 내용은 출처를 끝에 모아 적은 모둠","correct":true},{"t":"재미있는 놀이 기구 자랑만 길게 쓴 모둠","mis":"K3-2-u3-X21"},{"t":"확인하지 않은 규칙을 그럴듯하게 지어 넣은 모둠","mis":"K3-2-u3-X02"},{"t":"사진은 출처 없이 두고 글만 출처를 적은 모둠","mis":"K3-2-u3-X28"}],"explanation":["읽을 사람은 1학년 동생이에요.","문단과 차례가 필요해요.","확인한 것과 출처를 함께 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#24','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C20',4,'essay','teacher','‘-데’와 ‘-대’를 갈라 쓰는 방법을 쓰고, ‘보니’가 들어간 문장 가운데 ‘-대’를 써야 하는 문장을 하나 만들어 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u3-C20","difficulty":4,"kind":"essay","stem":"‘-데’와 ‘-대’를 갈라 쓰는 방법을 쓰고, ‘보니’가 들어간 문장 가운데 ‘-대’를 써야 하는 문장을 하나 만들어 까닭을 쓰세요.","answer_guide":{"answer":"예: 내가 직접 겪어 안 것을 말할 때는 ‘-데’, 남에게 들은 말을 전할 때는 ‘-대’를 쓴다. 문장: 짝에게 물어 보니 다음 주에 운동장에 새 그네가 생긴대. 까닭 — ‘보니’가 들어가 있어도 내가 겪은 것이 아니라 짝에게 들은 말을 전하는 것이라 ‘-대’를 쓴다.","scoring_points":["‘-데’·‘-대’를 가르는 방법을 썼는가","‘보니’가 들어간 ‘-대’ 문장을 만들었는가","들은 말을 전하기 때문이라는 까닭을 썼는가"]},"explanation":["겪었는지 들었는지가 갈라요.","‘보니’는 가르는 기준이 아니에요.","들은 말이면 ‘-대’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u3_review_d#25','kor',3,2,'u3','','g3_2_kor_u3_review_d','unit_review','K3-2-u3-C18',4,'essay','teacher','서진이와 다른 차례로 식판을 정리하는 친구가 글을 썼다면 어느 글이 알맞은지 어떻게 판단할지 쓰고, 쓴 글을 점검할 때 살펴볼 것 세 가지를 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u3-C18","difficulty":4,"kind":"essay","stem":"서진이와 다른 차례로 식판을 정리하는 친구가 글을 썼다면 어느 글이 알맞은지 어떻게 판단할지 쓰고, 쓴 글을 점검할 때 살펴볼 것 세 가지를 쓰세요.","answer_guide":{"answer":"예: 방법이 달라도 읽는 사람이 그대로 따라 할 수 있게 차례와 까닭이 드러나면 둘 다 알맞은 글이라고 판단한다. 점검할 것 — 일의 차례와 방법이 드러났는가, 이어 주는 말을 알맞게 썼는가, 가져온 자료가 있다면 출처를 밝혔는가.","scoring_points":["방법이 달라도 차례와 까닭이 드러나면 알맞다고 썼는가","점검할 것 세 가지를 썼는가","점검은 고치려고 하는 것임이 드러났는가"]},"explanation":["세연이와 다안이를 떠올려요.","같은 방법일 필요는 없어요.","고치려고 살펴봐요."],"asset":{"type":"passage","lines":["급식을 다 먹은 뒤 식판을 정리하는 방법을 알려 드리겠습니다.","먼저, 남은 음식을 한쪽으로 모아 정해진 통에 덜어 냅니다.","다음으로, 숟가락과 젓가락을 수저 통에 넣습니다.","끝으로, 빈 식판을 정해진 곳에 포개어 놓습니다.","식판을 놓는 곳은 「급식실 이용 안내」에 그림으로 나와 있습니다.","이 차례대로 하면 급식실을 깨끗하게 쓸 수 있습니다.","■ 출처: 「급식실 이용 안내」, 학교 누리집."],"title":"학급 신문 「식판 정리하는 방법」 — 글 서진"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
